head.b:skin:
/*
--------------------------------------------------
Blogger Template Style
Name:        ZaminDrive Premium
Version:     4.0.0
Base:        SoraFlix v1.0 → streaming platform reconstruction
Design note: one unified streaming system, no patch layers
--------------------------------------------------
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" hideEditor="true" default="#e50914" value="#e50914"/>
<Variable name="accent.color" description="Accent Color" type="color" hideEditor="true" default="#e50914" value="#e50914"/>
<Variable name="body.background.color" description="Body Background" type="color" hideEditor="true" default="#0d0d0f" value="#0d0d0f"/>
<Variable name="body.bg" description="Background" type="background" color="#0d0d0f" default="$(color) url() repeat scroll top left" value="$(color) url() repeat scroll top left"/>
<Variable name="body.text.color" description="Body Text Color" type="color" hideEditor="true" default="#b3b3b3" value="#b3b3b3"/>
<Variable name="link.color" description="Link Color" type="color" hideEditor="true" default="#e50914" value="#e50914"/>
<Variable name="body.font" description="Body Font" type="font" hideEditor="true" default="'Helvetica Neue',Helvetica,Arial,sans-serif" value="&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif"/>
<Variable name="title.font" description="Title Font" type="font" hideEditor="true" default="'Helvetica Neue',Helvetica,Arial,sans-serif" value="&#39;Helvetica Neue&#39;,Helvetica,Arial,sans-serif"/>
<Variable name="zamd.cardMode" description="Default card format (poster|landscape|compact)" type="string" hideEditor="true" default="landscape" value="landscape"/>
<Variable name="zamd.darkMode" description="Theme mode (dark|light|system)" type="string" hideEditor="true" default="dark" value="dark"/>
<Variable name="zamd.backToTop" description="Show back-to-top button" type="string" hideEditor="true" default="true" value="true"/>
<Variable name="zamd.lazyLoad" description="Lazy load images" type="string" hideEditor="true" default="true" value="true"/>
<Variable name="zamd.viewsCounter" description="Enable view counter" type="string" hideEditor="true" default="true" value="true"/>
<Variable name="zamd.searchLive" description="Enable live search" type="string" hideEditor="true" default="true" value="true"/>
<Variable name="zamd.bookmarks" description="Enable My List bookmarks" type="string" hideEditor="true" default="true" value="true"/>
<Variable name="zamd.boxedLayout" description="Boxed layout mode" type="string" hideEditor="true" default="false" value="false"/>
<Variable name="zamd.fixedSidebar" description="Sticky sidebar" type="string" hideEditor="true" default="true" value="true"/>
<Variable name="zamd.postPerPage" description="Posts per page" type="string" hideEditor="true" default="12" value="12"/>
<Variable name="zamd.cookieConsent" description="Show cookie consent bar" type="string" hideEditor="true" default="false" value="false"/>
<Variable name="zamd.colorScheme" description="Color scheme index (0-15)" type="string" hideEditor="true" default="0" value="0"/>
<Variable name="zamd.firebaseDatabaseURL" description="Firebase Realtime Database URL for view counting (empty = off)" type="string" hideEditor="true" default="" value=""/>
<Variable name="zamd.firebaseApiKey" description="Firebase API key for view counting" type="string" hideEditor="true" default="" value=""/>
<Variable name="zamd.pwa" description="Enable progressive web app registration" type="string" hideEditor="true" default="false" value="false"/>
<Variable name="zamd.lightbox" description="Enable image lightbox on post body" type="string" hideEditor="true" default="true" value="true"/>
*/

/* ============================================================
   1. Design tokens
   ============================================================ */
:root{
  --bg:#141414;
  --bg-deep:#0d0d0f;
  --bg-pop:#181818;
  --bg-hover:rgba(255,255,255,.12);
  --line:rgba(255,255,255,.09);
  --line-strong:rgba(255,255,255,.18);
  --text:#e5e5e5;
  --text-2:#b3b3b3;
  --text-3:#808080;
  --accent:#e50914;
  --accent-h:#ff1b26;
  --ok:#23d18b;
  --warn:#f5b942;
  --info:#5aa5ff;
  --white:#fff;
  --black:#0a0a0a;
  --radius:3px;
  --radius-l:8px;
  --header-h:68px;
  --gutter:clamp(16px,4vw,48px);
  --max-w:1920px;
  --font:'Helvetica Neue',Helvetica,Arial,sans-serif;
  --font-mono:"SFMono-Regular",Consolas,"Liberation Mono",Menlo,monospace;
  --ease:cubic-bezier(.22,.61,.36,1);
  --shadow-sm:0 2px 10px rgba(0,0,0,.35);
  --shadow-md:0 14px 40px rgba(0,0,0,.5);
  --shadow-lg:0 24px 60px rgba(0,0,0,.6);
  --rail-gap:10px;
  --card-poster:clamp(140px,10.5vw,200px);
  --card-land:clamp(240px,17.5vw,320px);
  --fs-xs:12px;
  --fs-sm:13px;
  --fs-base:15px;
  --fs-md:17px;
  --fs-lg:20px;
  --fs-xl:28px;
  --fs-2xl:40px;
  --fs-3xl:56px;
  --sp-1:4px;
  --sp-2:8px;
  --sp-3:12px;
  --sp-4:16px;
  --sp-5:24px;
  --sp-6:32px;
  --sp-7:48px;
  --sp-8:64px;
}

/* ============================================================
   2. Reset & base
   ============================================================ */
html{line-height:1.55;-webkit-text-size-adjust:100%;scroll-behavior:smooth}
*,*:before,*:after{box-sizing:border-box;margin:0;padding:0}
article,aside,details,figcaption,figure,footer,header,hgroup,main,nav,section,summary{display:block}
img{border:0;max-width:100%;height:auto;display:block}
svg{display:block}
a{background:transparent;color:inherit;text-decoration:none}
ul,ol{list-style:none}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer;background:none;border:0;-webkit-tap-highlight-color:transparent}
input,textarea,select{background:var(--bg-pop);border:1px solid var(--line);color:var(--text);border-radius:var(--radius);padding:10px 12px;outline:none;width:100%}
input:focus,textarea:focus,select:focus{border-color:var(--line-strong)}
input::placeholder,textarea::placeholder{color:var(--text-3)}
body{
  min-height:100vh;
  display:flex;
  flex-direction:column;
  background:var(--bg-deep);
  color:var(--text);
  font-family:var(--font);
  font-size:var(--fs-base);
  line-height:1.55;
  overflow-x:hidden;overflow-x:clip;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
  text-rendering:optimizeLegibility;
}
h1,h2,h3,h4,h5,h6{font-family:var(--font);line-height:1.2;color:var(--text);font-weight:700}
a{color:var(--text-2);transition:color .18s}
a:hover{color:var(--text)}
::selection{background:var(--accent);color:#fff;text-shadow:none}
::-webkit-scrollbar{width:10px;height:10px}
::-webkit-scrollbar-track{background:var(--bg-deep)}
::-webkit-scrollbar-thumb{background:#333;border-radius:8px;border:2px solid var(--bg-deep)}
::-webkit-scrollbar-thumb:hover{background:#454545}
:focus-visible{outline:2px solid #fff;outline-offset:3px;border-radius:2px}

/* ============================================================
   3. Accessibility
   ============================================================ */
.sr-only,.sr-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.skip-link{position:fixed;top:-52px;left:16px;z-index:250;background:#fff;color:#000;padding:12px 18px;border-radius:var(--radius);font-weight:700;font-size:14px;transition:top .2s}
.skip-link:focus{top:12px;color:#000}
.sfx-hidden{display:none!important;visibility:hidden!important}
@media (prefers-reduced-motion: reduce){
  *,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}
}

/* ============================================================
   4. Layout shell
   ============================================================ */
.layout{width:100%;max-width:var(--max-w);margin-inline:auto;padding-inline:var(--gutter)}
.site-row{display:flex;flex:1 0 auto;align-items:flex-start;gap:calc(var(--gutter) * 2);width:100%;max-width:var(--max-w);margin-inline:auto}
.site-row .site-main{min-width:0;width:100%}
.site-row .site-sidebar{width:300px;flex-shrink:0;min-width:0}
.site-main{flex:1 1 auto;padding-top:var(--header-h)}
body.view-home .site-main{padding-top:0}
body.view-home .site-row .site-sidebar{display:none}
body.drawer-locked{overflow:hidden}
.content-main{min-width:0}

/* ============================================================
   5. Buttons
   ============================================================ */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;height:48px;padding:0 24px;border-radius:var(--radius);font-weight:600;font-size:15px;border:0;cursor:pointer;text-decoration:none;white-space:nowrap;transition:background .18s,color .18s,transform .12s var(--ease)}
.btn:active{transform:scale(.97)}
.btn .fa{font-size:15px}
.btn-play{background:var(--white);color:var(--black)}
.btn-play:hover{background:#fff;color:var(--black)}
.btn-ghost{background:rgba(109,109,110,.72);color:var(--white)}
.btn-ghost:hover{background:rgba(109,109,110,.95);color:var(--white)}
.btn-sm{height:36px;padding:0 16px;font-size:13px}
.btn-accent{background:var(--accent);color:#fff}
.btn-accent:hover{background:var(--accent-h);color:#fff}

/* ============================================================
   6. Header — streaming navbar
   ============================================================ */
.site-header{
  position:fixed;top:0;left:0;right:0;z-index:90;
  height:var(--header-h);
  display:flex;align-items:center;
  background:linear-gradient(180deg,rgba(10,10,10,.7) 0%,rgba(10,10,10,0) 100%);
  transition:background .25s var(--ease),box-shadow .25s var(--ease);
}
body.is-scrolled .site-header,
body:not(.view-home) .site-header{
  background:rgba(15,15,17,.99);
  -webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);
  box-shadow:0 1px 0 var(--line);
}
.header-inner{display:flex;align-items:center;gap:0;width:100%}
.brand{display:flex;align-items:center;margin-right:18px;flex:0 0 auto;cursor:default}
.brand .header-widget{display:flex;align-items:center}
.brand .header-brand{display:inline-flex;align-items:center;text-decoration:none}
.brand .header-brand img{height:34px;width:auto;max-height:38px;object-fit:contain;transition:height .2s var(--ease)}
body.is-scrolled .brand .header-brand img{height:32px}
.brand .header-text-brand,.brand h1{
  font-size:25px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;
  font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;line-height:1;
  color:var(--accent);margin:0;display:inline-flex;align-items:center;
}
.brand .header-text-brand a,.brand h1 a{color:var(--accent);text-decoration:none}
.brand .header-text-brand a:hover,.brand h1 a:hover{color:var(--accent-h)}
.brand .header-description{display:none}

/* ghost icon button (burger / close) */
.ghost-btn{display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;color:#fff;font-size:17px;border-radius:var(--radius);transition:background .18s;cursor:pointer}
.ghost-btn:hover{background:rgba(255,255,255,.1)}
.ghost-btn .fa{pointer-events:none}
.hamburger{display:none}
.burger,.burger:before,.burger:after{display:block;width:20px;height:2px;background:currentColor;border-radius:2px;transition:transform .2s var(--ease),opacity .2s}
.burger{position:relative}
.burger:before{content:"";position:absolute;left:0;top:-7px}
.burger:after{content:"";position:absolute;left:0;top:7px}

/* primary nav (desktop) */
.menu-source{display:none!important}
.primary-nav{display:flex;align-items:center;flex:1}
.primary-nav .menu-list{display:flex;align-items:center;gap:0}
.primary-nav .menu-list>li{position:relative}
.primary-nav .menu-list>li>a,.primary-nav .sub-toggle{
  display:inline-flex;align-items:center;gap:6px;padding:8px 14px;
  color:rgba(229,229,229,.86);font-size:14px;font-weight:500;letter-spacing:.01em;
  cursor:pointer;white-space:nowrap;text-decoration:none;background:none;border:0;transition:color .18s;
}
.primary-nav .menu-list>li:first-child>a{font-weight:700;color:#fff}
.primary-nav .menu-list>li>a:hover,.primary-nav .sub-toggle:hover{color:#fff}
li.has-sub>.sub-toggle:after{content:"\f078";font-family:FontAwesome;font-size:10px;opacity:.7;margin-left:4px;transition:transform .18s}
li.has-sub:hover>.sub-toggle:after,li.has-sub:focus-within>.sub-toggle:after{transform:rotate(180deg)}
.primary-nav .sub-menu{
  position:absolute;top:calc(100% + 8px);left:6px;min-width:220px;margin:0;padding:8px;
  background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);
  box-shadow:var(--shadow-md);opacity:0;visibility:hidden;transform:translateY(8px);
  transition:opacity .18s var(--ease),transform .18s var(--ease),visibility .18s;z-index:60;
}
.primary-nav li.has-sub:hover>.sub-menu,.primary-nav li.has-sub:focus-within>.sub-menu{opacity:1;visibility:visible;transform:none}
.primary-nav .sub-menu a{display:block;padding:10px 12px;color:var(--text);font-size:13.5px;border-radius:2px;transition:color .15s,background .15s;white-space:nowrap}
.primary-nav .sub-menu a:hover{color:#fff;background:rgba(255,255,255,.12)}
.header-tools{display:flex;align-items:center;gap:8px;margin-left:auto}

/* ============================================================
   7. Inline search (Netflix-style)
   ============================================================ */
.nf-search{position:relative;display:flex;align-items:center}
.nf-search-form{position:relative;display:flex;align-items:center;min-width:0}
.nf-search-toggle{
  display:inline-flex;align-items:center;justify-content:center;width:42px;height:42px;
  color:#fff;font-size:18px;border-radius:var(--radius);cursor:pointer;transition:background .18s;
}
.nf-search-toggle:hover{background:rgba(255,255,255,.1)}
.nf-search-input{
  width:0;opacity:0;padding:6px 8px;margin-left:2px;
  background:transparent;border:0;border-bottom:1px solid transparent;border-radius:0;
  color:#fff;font-size:15px;outline:none;
  transition:width .28s var(--ease),opacity .28s,border-color .28s;
}
.nf-search-input:focus{border:0;border-bottom:1px solid #fff;background:transparent;box-shadow:none}
.nf-search-input::placeholder{color:var(--text-3);opacity:0;transition:opacity .2s}
.nf-search.is-open .nf-search-input{width:clamp(180px,22vw,340px);opacity:1;border-bottom-color:rgba(255,255,255,.35)}
.nf-search.is-open .nf-search-input:focus{border-bottom-color:#fff}
.nf-search.is-open .nf-search-input::placeholder{opacity:1}
.nf-search-clear{
  display:none;align-items:center;justify-content:center;width:34px;height:34px;
  color:#fff;font-size:15px;cursor:pointer;border-radius:var(--radius);
}
.nf-search-clear:hover{background:rgba(255,255,255,.1)}
.nf-search.has-input .nf-search-clear{display:inline-flex}
.nf-search-taglink{
  display:inline-flex;align-items:center;gap:10px;padding:9px 12px;
  color:var(--text-2);font-size:14.5px;font-weight:500;border-radius:var(--radius);
  transition:color .15s,background .15s;
}
.nf-search-taglink:hover{color:#fff;background:rgba(255,255,255,.06)}
.nf-search-taglink .fa{color:var(--accent);font-size:12px}.nf-item a:hover,.nf-item a.nf-active{background:rgba(255,255,255,.08)}


/* ============================================================
   8. Account menu
   ============================================================ */
.account-wrap{position:relative;display:inline-flex;align-items:center;gap:6px}
.account-avatar{
  width:34px;height:34px;border-radius:2px;
  background:linear-gradient(135deg,var(--accent),#a50710);color:#fff;
  display:flex;align-items:center;justify-content:center;cursor:pointer;transition:transform .15s;
}
.account-avatar .fa{font-size:15px}
.account-avatar:hover{transform:scale(1.06)}
.account-chevron{color:#fff;font-size:11px;transition:transform .18s;cursor:pointer}
.account-wrap:hover .account-chevron{transform:rotate(180deg)}
.account-drop{
  position:absolute;top:calc(100% + 12px);right:0;min-width:215px;
  background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);
  padding:6px 6px 8px;box-shadow:var(--shadow-md);
  opacity:0;visibility:hidden;transform:translateY(8px);
  transition:opacity .18s,transform .18s,visibility .18s;z-index:70;
}
.account-wrap:hover .account-drop,.account-wrap:focus-within .account-drop{opacity:1;visibility:visible;transform:none}
.account-drop-title{display:block;padding:10px 14px;color:#fff;font-size:14px;font-weight:700;border-bottom:1px solid var(--line);margin-bottom:4px}
.account-drop a{display:block;padding:9px 14px;color:var(--text);font-size:14px;white-space:nowrap;text-decoration:none}
.account-drop a:hover{background:rgba(255,255,255,.12);color:#fff}
.account-drop .widget-title{display:none}

/* ============================================================
   9. Drawer (mobile nav)
   ============================================================ */
.drawer{
  position:fixed;top:0;left:0;bottom:0;width:min(86vw,340px);z-index:200;
  background:var(--bg-deep);border-right:1px solid var(--line);
  display:flex;flex-direction:column;overflow-y:auto;overscroll-behavior:contain;
  transform:translateX(-106%);visibility:hidden;transition:transform .3s var(--ease),visibility .3s;
}
.drawer.is-open{transform:none;visibility:visible;box-shadow:var(--shadow-md)}
.drawer-top{display:flex;align-items:center;padding:10px 14px;border-bottom:1px solid var(--line)}
.drawer-brand{font-size:18px;font-weight:800;letter-spacing:.01em;color:var(--accent);text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;flex:1}
.drawer-nav{flex:1;padding:10px 0 4px}
.drawer-nav .menu-list>li>a,.drawer-nav .sub-toggle{
  display:flex;align-items:center;width:100%;padding:14px 22px;
  color:var(--text-2);font-size:16px;font-weight:600;letter-spacing:.01em;
  border-left:3px solid transparent;transition:color .15s,background .15s;
  cursor:pointer;background:none;border-right:0;border-top:0;border-bottom:0;
}
.drawer-nav .menu-list>li>a:hover,.drawer-nav .sub-toggle:hover{color:#fff;background:rgba(255,255,255,.05)}
.drawer-nav li.has-sub>.sub-toggle:after{content:"\f078";font-family:FontAwesome;font-size:12px;opacity:.7;margin-left:auto;transition:transform .2s}
.drawer-nav li.has-sub.is-open>.sub-toggle:after{transform:rotate(180deg)}
.drawer-nav li.has-sub>.sub-menu{display:none;padding:0 0 8px;background:#0a0a0c}
.drawer-nav li.has-sub.is-open>.sub-menu{display:block}
.drawer-nav li.has-sub>.sub-menu a{padding:12px 22px 12px 40px;color:var(--text-3);font-size:15px;font-weight:500}
.drawer-nav li.has-sub>.sub-menu a:hover{color:#fff}
.drawer-extra{border-top:1px solid var(--line);padding:14px 22px 24px}
.drawer-extra .widget-title{display:none}
.drawer-links ul{display:flex;flex-wrap:wrap;gap:4px 18px}
.drawer-links a{display:inline-flex;padding:5px 0;color:var(--text-3);font-size:13.5px;font-weight:500}
.drawer-links a:hover{color:#fff}
.drawer-social{margin-top:14px}
.drawer-social ul{display:flex;flex-wrap:wrap;gap:4px}
.drawer-social a{
  display:inline-flex;width:38px;height:38px;align-items:center;justify-content:center;
  color:var(--text-3);font-size:15px;border-radius:var(--radius);transition:color .15s,background .15s;
}
.drawer-social a:hover{color:#fff;background:rgba(255,255,255,.08)}
.drawer-copy{color:var(--text-3);font-size:12px;margin-top:16px;padding-top:12px;border-top:1px solid var(--line)}
.backdrop{position:fixed;inset:0;z-index:180;background:rgba(0,0,0,.6);opacity:0;visibility:hidden;transition:opacity .25s,visibility .25s}
.backdrop.is-show{opacity:1;visibility:visible}

/* ============================================================
   10. Billboard hero (homepage)
   ============================================================ */
.hero{
  position:relative;display:flex;align-items:flex-end;
  min-height:min(74vh,780px);overflow:hidden;
  background:linear-gradient(180deg,#0f0f11,var(--bg-deep));
  width:100vw;margin-left:calc(50% - 50vw);
}
.hero-media{position:absolute;inset:0}
.hero-img{width:100%;height:100%;object-fit:cover;transform:scale(1.01)}
.hero-shade{
  position:absolute;inset:0;background:
    linear-gradient(90deg,rgba(13,13,15,.85) 0%,rgba(13,13,15,.45) 38%,rgba(13,13,15,.05) 75%),
    linear-gradient(180deg,rgba(13,13,15,.2) 0%,rgba(13,13,15,0) 16%,rgba(13,13,15,0) 55%,rgba(13,13,15,.4) 78%,rgba(13,13,15,.96) 100%);
}
.hero-body{position:relative;z-index:2;width:100%;max-width:820px;padding:0 var(--gutter) 8vh}
.hero-eyebrow{
  display:inline-flex;align-items:center;gap:8px;font-size:12px;font-weight:700;
  letter-spacing:.2em;text-transform:uppercase;color:rgba(255,255,255,.7);margin-bottom:16px;
}
.hero-title{font-size:clamp(32px,5.2vw,60px);line-height:1.06;font-weight:800;letter-spacing:-.02em;margin:0 0 14px}
.hero-title a{color:#fff;text-decoration:none}
.hero-title a:hover{color:#fff}
.hero-synopsis{color:rgba(255,255,255,.85);font-size:clamp(14.5px,1.4vw,17px);line-height:1.6;margin:0 0 18px;max-width:640px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.hero-meta{display:flex;align-items:center;flex-wrap:wrap;gap:10px;margin-bottom:22px;font-size:14px;color:rgba(255,255,255,.88)}
.hero-meta .sep{opacity:.45}
.hero-label{font-weight:700;color:#fff}
.hero-actions{display:flex;gap:12px;flex-wrap:wrap}
.hero-actions .btn{min-height:52px;padding:0 26px;font-size:16px}
.hero-actions .btn-play{min-width:150px}

/* ============================================================
   11. Row heads & home zones
   ============================================================ */
.row-head{display:flex;align-items:baseline;justify-content:space-between;gap:14px;margin:42px 0 12px}
.row-head:first-child{margin-top:0}
.row-title{font-size:19px;font-weight:700;letter-spacing:-.005em;margin:0;display:inline-flex;align-items:center;gap:10px}
.row-more{display:inline-flex;align-items:center;gap:7px;color:var(--text-3);font-size:13px;font-weight:600}
.row-more:hover{color:#fff}
.row-more:after{content:"\f105";font-family:FontAwesome;font-size:12px;transition:transform .18s}
.row-more:hover:after{transform:translateX(3px)}
.home-zone{margin-top:34px}
.home-genres{padding:4px 0 0}
.genre-nav{display:flex;gap:2px;overflow-x:auto;padding:6px 0 4px;-webkit-overflow-scrolling:touch;scrollbar-width:none}
.genre-nav::-webkit-scrollbar{display:none}
.genre-nav a{
  flex:0 0 auto;white-space:nowrap;padding:9px 14px;font-size:13px;font-weight:600;
  letter-spacing:.02em;color:var(--text-3);border-radius:var(--radius);transition:color .15s,background .15s;
}
.genre-nav a:hover{color:#fff;background:rgba(255,255,255,.08)}
.genre-nav a.is-active{color:#fff}

/* trending section header (PopularPosts widget title) */
.home-popular .widget-title{margin:42px 0 12px}
.home-popular .widget-title .title,.rail-heading .rail-heading-title{font-size:19px;font-weight:700;letter-spacing:-.005em;display:inline-flex;align-items:center;gap:10px}
.rail-heading{margin:42px 0 12px}
.rail-heading .rail-heading-title{margin:0}

/* home extras (formerly sidebar) */
.home-browse{margin-top:48px}
.home-browse-grid{display:grid;grid-template-columns:1fr 1fr;gap:36px var(--gutter)}
.sfx-home-zone,.sfx-xcard{min-width:0}
.sfx-home-zone{grid-column:1/-1}
.sfx-xcard .widget-content{font-size:14px;color:var(--text-2)}
.sfx-xcard .widget-content ul li,.sfx-xcard .widget-content p{color:var(--text-2)}
.sfx-xcard iframe,.sfx-xcard .fb-page{max-width:100%}
/* The global "ul,ol{list-style:none}" reset drops the bullets but leaves the
   browser's default padding and margin, and leaves the list a block. These two
   Blogger widget lists are built as chip rows and were inheriting neither, so
   they arrived indented and one item per line. */
.flat{list-style:none;padding:0;margin:0}
.cat-chips,.label-chips,.label-list{display:flex;flex-wrap:wrap;gap:10px}
.cat-chips a,.label-chips a,.label-list a{
  display:inline-flex;align-items:center;gap:8px;padding:9px 16px;
  border:1px solid var(--line);border-radius:2px;color:var(--text-2);
  font-size:13.5px;font-weight:600;transition:color .15s,border-color .15s,background .15s;
}
.cat-chips a:hover,.label-chips a:hover,.label-list a:hover{color:#fff;border-color:rgba(255,255,255,.5);background:rgba(255,255,255,.06)}
.cat-chips .count,.label-chips .count,.label-list .post-count{display:inline-flex;align-items:center;justify-content:center;min-width:22px;height:20px;padding:0 7px;border-radius:2px;background:rgba(255,255,255,.08);color:var(--text-3);font-size:11.5px;font-weight:700}
.sfx-shortcode-rail{margin-top:6px}

/* P6: homepage genre chips + series browser on index */
.home-chips-zone .genre-chips{margin-top:6px}
.genre-chips.is-empty{display:none}
.genre-chips .chip{display:inline-flex;align-items:center;gap:7px;padding:9px 15px;border:1px solid var(--line);border-radius:var(--radius);color:var(--text-2);font-size:13px;font-weight:600;text-decoration:none;transition:color .15s,border-color .15s,background .15s}
.genre-chips .chip:hover{color:#fff;border-color:var(--accent);background:rgba(229,9,20,.1)}
.genre-chips .chip.is-active{color:#fff;border-color:var(--accent);background:rgba(229,9,20,.22)}
.menu-list a.is-active,#drawer-acc a.is-active,.genre-nav a.is-active{color:var(--accent)}
.series-index{margin-top:34px;min-width:0}
.series-index .zamd-ep-header{display:flex;align-items:baseline;gap:12px;margin-bottom:14px}
.series-index .zamd-ep-series{font-size:21px;font-weight:800;letter-spacing:-.01em;color:#fff;text-transform:capitalize}
.series-index .zamd-ep-count{font-size:13.5px;color:var(--text-2)}
.series-index .zamd-ep-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}
.series-index .zamd-ep-item{position:relative;display:block;border-radius:var(--radius);overflow:hidden;background:#0e0e10;border:1px solid var(--line);transition:transform .2s,border-color .2s}
.series-index .zamd-ep-item:hover{transform:translateY(-3px);border-color:rgba(255,255,255,.25)}
.series-index .zamd-ep-item-thumb{width:100%;aspect-ratio:16/9;object-fit:cover;display:block}
.series-index .zamd-ep-item-num{position:absolute;top:8px;left:8px;width:26px;height:26px;display:inline-flex;align-items:center;justify-content:center;background:rgba(0,0,0,.72);border:1px solid rgba(255,255,255,.18);color:#fff;font-size:12.5px;font-weight:700;border-radius:50%}
.series-index .zamd-ep-item-title{display:block;padding:10px 12px;font-size:13px;font-weight:600;color:#fff;line-height:1.35}

.videoWrapper{position:relative;width:100%;height:0;padding-top:56.25%;overflow:hidden;background:#000}
.videoWrapper iframe{position:absolute;top:0;left:0;width:100%;height:100%;border:0}

/* ============================================================
   12. Rail system (one architecture for every row)
   ============================================================ */
.rail-wrap{position:relative}
.rail{
  display:flex;gap:var(--rail-gap);overflow-x:auto;
  padding-bottom:8px;-webkit-overflow-scrolling:touch;
  scroll-snap-type:x proximity;scrollbar-width:none;
}
.rail::-webkit-scrollbar{display:none}
.rail>*{flex:0 0 auto}
.rail-btn{
  position:absolute;top:0;bottom:0;z-index:6;width:56px;
  display:none;align-items:center;justify-content:center;
  color:#fff;font-size:20px;cursor:pointer;border:0;
  background:rgba(20,20,20,.5);
  opacity:0;visibility:hidden;transition:opacity .18s,visibility .18s,background .18s;
}
.rail-btn .fa{pointer-events:none;text-shadow:0 2px 8px rgba(0,0,0,.5)}
.rail-btn:hover{background:rgba(20,20,20,.8)}
.rail-btn.prev{
  left:0;
  background:linear-gradient(90deg,rgba(13,13,15,.9) 0%,rgba(13,13,15,0) 100%);
}
.rail-btn.next{
  right:0;
  background:linear-gradient(270deg,rgba(13,13,15,.9) 0%,rgba(13,13,15,0) 100%);
}
@media (min-width:1100px) and (pointer:fine){
  .rail-btn{display:inline-flex}
  .rail-wrap:hover .rail-btn,.rail-wrap:focus-within .rail-btn,
  .rail-btn:focus-visible{opacity:1;visibility:visible}
  .rail-btn.is-hidden{display:none}
}

/* landscape rail cards (trending / popular) */
.rail-card{flex-basis:var(--card-land);scroll-snap-align:start;min-width:0}
.rail-media{
  position:relative;display:block;aspect-ratio:16/9;
  border-radius:var(--radius);overflow:hidden;background:var(--bg-pop);
}
.rail-media img{width:100%;height:100%;object-fit:cover;transition:transform .35s var(--ease)}
.rail-card:hover .rail-media img,.rail-media:focus-within img{transform:scale(1.05)}
.rail-shade{position:absolute;inset:0;background:linear-gradient(180deg,transparent 30%,rgba(0,0,0,.62) 100%)}
.rail-card:hover .rail-shade{background:linear-gradient(180deg,rgba(0,0,0,.16) 0%,rgba(0,0,0,.68) 100%)}
.rail-play{
  position:absolute;inset:0;margin:auto;width:52px;height:52px;border-radius:50%;
  background:rgba(0,0,0,.55);border:2px solid #fff;color:#fff;
  display:flex;align-items:center;justify-content:center;font-size:16px;padding-left:3px;
  opacity:0;transform:scale(.6);transition:opacity .2s,transform .24s var(--ease);
}
.rail-card:hover .rail-play{opacity:1;transform:scale(1)}
.rail-number{
  position:absolute;bottom:-14px;right:8px;font-size:clamp(52px,5vw,84px);font-weight:800;
  font-style:italic;letter-spacing:-.05em;line-height:1;color:#fff;
  text-shadow:0 6px 18px rgba(0,0,0,.85);z-index:3;
}
.rail-info{min-width:0}
.rail-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:14px;font-weight:600;line-height:1.32;margin:8px 0 2px}
.rail-title a{color:#e8e8ea}
.rail-title a:hover{color:#fff}
.rail-meta{display:flex;align-items:center;gap:8px;color:var(--text-3);font-size:12px;flex-wrap:wrap}
.rail-label{color:var(--text-2);font-weight:600}

/* card-mode rails: one geometry contract for server- AND JS-rendered cards */
.rail-mode-poster > .poster-rail-card,.rail-mode-poster > .rail-card-poster,
.poster-rail:not(.rail-mode-landscape) > .poster-rail-card,.poster-rail:not(.rail-mode-landscape) > .rail-card-poster{flex-basis:var(--card-poster);scroll-snap-align:start;min-width:0}
.rail-mode-landscape > .poster-rail-card,.rail-mode-landscape > .rail-card-landscape{flex-basis:var(--card-land);scroll-snap-align:start;min-width:0}
.rail-mode-poster > .poster-rail-card .poster-media,.rail-mode-poster > .rail-card-poster .poster-media,
.poster-rail:not(.rail-mode-landscape) .poster-media{aspect-ratio:2/3}
.rail-mode-landscape > .poster-rail-card .poster-media,.rail-mode-landscape > .rail-card-landscape .poster-media{aspect-ratio:16/9}
.rail-mode-poster > .poster-rail-card .poster-title,.rail-mode-poster > .rail-card-poster .poster-title{font-size:13px}
.rail-mode-poster > .poster-rail-card .poster-sub,.rail-mode-poster > .rail-card-poster .poster-sub{display:none}
.rail-card-landscape .poster-media{aspect-ratio:16/9}
.rail-card-compact{display:flex;gap:12px;align-items:center;width:280px}
.rail-card-compact .poster-media{width:120px;flex-shrink:0;aspect-ratio:16/9}

/* ============================================================
   13. Poster cards (grid / catalog / related)
   ============================================================ */
.poster-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(var(--card-poster),1fr));gap:24px 14px}
    .poster-card{min-width:0;position:relative}
    .cw-bar{position:absolute;left:8px;right:8px;bottom:6px;height:3px;border-radius:2px;background:rgba(255,255,255,.25);z-index:4;overflow:hidden;pointer-events:none}
    .cw-bar i{display:block;height:100%;background:var(--accent);border-radius:2px}
    .cw-ep{display:block;font-size:12px;color:var(--text-3);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.poster-media{
  position:relative;display:block;aspect-ratio:2/3;
  border-radius:var(--radius);overflow:hidden;background:var(--bg-pop);border:1px solid transparent;
}
.poster-media img{width:100%;height:100%;object-fit:cover;transition:transform .35s var(--ease);position:relative;z-index:1}
/* Portrait art arrives from OMDb some time after the card is built, so until it
   lands - and for good when the lookup misses - the slot is a black plate
   carrying the clean title. .poster-media already supplies the box through
   aspect-ratio, so the plate only has to fill it and centre its title. */
.poster-plate{position:absolute;inset:0;z-index:0;display:flex;align-items:center;justify-content:center;padding:12%;background:#000}
.poster-plate-t{
  color:var(--text-2);font-size:13.5px;font-weight:600;line-height:1.32;text-align:center;
  display:-webkit-box;-webkit-line-clamp:4;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;
}
/* the plate is the resting state, not an overlay: the hover play control and the
   badge have to stay reachable above it */
.poster-media.is-plate{background:#000}
.poster-hover{z-index:1}
.poster-card:hover .poster-media img,.poster-media:focus-within img{transform:scale(1.06)}
.poster-card:hover .poster-media{border-color:var(--line-strong);box-shadow:var(--shadow-md)}
.poster-hover{
  position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(180deg,rgba(0,0,0,0) 40%,rgba(13,13,16,.7) 100%);
  opacity:0;transition:opacity .22s;
}
.poster-hover .play-ic{
  width:52px;height:52px;border-radius:50%;background:rgba(229,9,20,.92);color:#fff;
  display:flex;align-items:center;justify-content:center;font-size:17px;padding-left:3px;
  transform:scale(.7);transition:transform .24s var(--ease);box-shadow:0 8px 24px rgba(0,0,0,.5);
}
.poster-card:hover .poster-hover,.poster-card:focus-within .poster-hover{opacity:1}
.poster-card:hover .poster-hover .play-ic,.poster-card:focus-within .poster-hover .play-ic{transform:scale(1)}
.poster-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:13.5px;font-weight:600;line-height:1.32;margin-top:clamp(4px,1vw,9px);min-height:2.64em}
.poster-title a{color:#e8e8ea}
.poster-title a:hover{color:#fff}
.poster-sub{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:2px;font-size:12px;color:var(--text-3)}
.poster-sub .sep{opacity:.6}
.poster-more{
  position:absolute;top:10px;right:10px;z-index:3;width:32px;height:32px;border-radius:50%;
  background:rgba(13,13,16,.72);color:#fff;border:1px solid rgba(255,255,255,.18);
  display:flex;align-items:center;justify-content:center;font-size:13px;cursor:pointer;
  opacity:0;transform:translateY(-4px);transition:opacity .22s,transform .22s,background .22s;
}
.poster-card:hover .poster-more,.poster-card:focus-within .poster-more{opacity:1;transform:translateY(0)}
.poster-more:hover{background:var(--accent,#dc1f26);border-color:var(--accent,#dc1f26)}

/* ============================================================
   14. Catalog pages (search / label / archive / index)
   ============================================================ */
    .catalog{margin-top:10px}
    .catalog .poster-sub, .nf-results-grid .poster-sub{display:none}
.catalog-head{margin:26px 0 24px}
.catalog-title{font-size:clamp(22px,3vw,32px);font-weight:800;letter-spacing:-.015em;margin:0 0 8px}
.catalog-title em{font-style:normal;color:var(--accent)}
.catalog-desc{color:var(--text-3);font-size:14.5px;margin:0}
.queryEmpty{color:var(--text-3);padding:56px 0 40px;text-align:center;font-size:15.5px}
.error-hero{min-height:62vh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:48px var(--gutter)}
.error-code{font-size:120px;font-weight:800;line-height:1;color:#fff;letter-spacing:-.04em;text-shadow:0 10px 40px rgba(229,9,20,.35)}
.error-title{font-size:26px;margin:14px 0 10px}
.error-text{color:var(--text-3);margin:0 0 26px;max-width:480px;font-size:14.5px}
.blog-pager{display:flex;align-items:center;justify-content:center;gap:10px;margin:48px 0 6px;flex-wrap:wrap}

.blog-pager:empty{display:none}
.blog-pager a{
  display:inline-flex;align-items:center;gap:9px;height:42px;padding:0 20px;
  border-radius:var(--radius);background:rgba(255,255,255,.08);color:#e8e8ea;
  font-size:13.5px;font-weight:600;border:1px solid transparent;transition:background .18s,color .18s;
}
.blog-pager a:hover{background:var(--accent);color:#fff}
.blog-pager .blog-pager-newer-link:before{content:"\f104";font-family:FontAwesome;font-size:12px}
.blog-pager .blog-pager-older-link:after{content:"\f105";font-family:FontAwesome;font-size:12px}

/* BlogSearch default form (results pages) */
.search-form{display:flex;align-items:center;gap:12px;border-bottom:2px solid rgba(255,255,255,.25);padding:4px 2px 10px}
.search-form .fa-search{color:var(--text-3);font-size:20px}
.search-form .search-input{flex:1;background:none;border:0;box-shadow:none;color:#fff;font-size:clamp(20px,3vw,28px);font-weight:600;padding:6px 2px}
.search-form .search-input:focus{border:0;box-shadow:none;background:none}

/* ============================================================
   15. Detail page (streaming detail)
   ============================================================ */
  .detail-hero{
    position:relative;display:block;overflow:hidden;
    background:#000;
    width:auto;margin-inline:calc(-1 * var(--gutter));
  }
  .detail-hero.is-empty{display:none}
.detail-entry{margin-top:0}
.detail-head{position:relative;z-index:2;padding:24px 0 4px;max-width:920px}
.detail-meta{display:flex;align-items:center;flex-wrap:wrap;gap:10px;font-size:14px;color:rgba(255,255,255,.85);margin-bottom:14px}
.detail-meta .sep{opacity:.45}
.detail-label{font-weight:700;color:#fff}
.detail-title{font-size:clamp(30px,4.6vw,50px);line-height:1.06;font-weight:800;letter-spacing:-.02em;margin:0 0 14px}
.detail-synopsis{color:rgba(255,255,255,.82);font-size:clamp(14.5px,1.5vw,17px);line-height:1.6;margin:0 0 22px;max-width:660px}
.detail-actions{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:20px}
.detail-actions .btn{min-height:52px;padding:0 26px;font-size:16px}
.detail-genres{display:flex;flex-wrap:wrap;gap:8px}
.detail-genres a{
  display:inline-flex;align-items:center;padding:7px 14px;
  border:1px solid var(--line);border-radius:2px;color:var(--text-2);
  font-size:12.5px;font-weight:600;transition:color .15s,border-color .15s,background .15s;
}
.detail-genres a:hover{color:#fff;border-color:rgba(255,255,255,.5);background:rgba(255,255,255,.06)}
.detail-wrap{margin-top:8px}
.detail-main{max-width:1100px;margin-inline:auto}
.detail-player{
  position:relative;width:100%;aspect-ratio:16/9;margin:0;
  background:#000;border-radius:0;overflow:hidden;
  box-shadow:none;max-height:min(78vh,780px);
}
.detail-player.is-empty{display:none}
.detail-player-frame{position:relative;width:100%;height:100%}
.detail-player-frame iframe,.detail-player-frame video{position:absolute;inset:0;width:100%;height:100%;border:0;display:block;object-fit:contain;background:#000}
.detail-player-postfallback{display:none;width:100%;height:100%;align-items:center;justify-content:center}
.detail-player-postfallback img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.5}
.detail-player-postfallback .btn{position:relative;z-index:1}
.detail-player.has-player .detail-player-postfallback{display:none!important}
/* post pages only: reserved poster/banner alt images never render as content
   (homepage, search, labels, archives, widgets keep showing them normally) */
body.view-post .detail-entry img[alt*="poster" i],
body.view-post .detail-entry img[alt*="banner" i],
body.view-post .detail-entry img[alt*="hide" i],
body.view-post .detail-entry img[alt*="dont-show" i]{display:none!important}
body.preview-open{overflow:hidden}
.entry-kicker{display:inline-flex;align-items:center;gap:7px;color:var(--accent);font-weight:700;font-size:12px;letter-spacing:.14em;text-transform:uppercase;margin-bottom:10px}
.post-title{font-size:clamp(24px,3.6vw,38px);font-weight:800;letter-spacing:-.015em;line-height:1.1;margin:0 0 12px}
.entry-meta{display:flex;flex-wrap:wrap;gap:8px 16px;color:var(--text-3);font-size:13.5px;margin-bottom:22px}
.entry-meta a{color:var(--text-2)}
.entry-meta a:hover{color:#fff}
.meta-item{display:inline-flex;align-items:center;gap:7px}

/* ============================================================
   16. Post content
   ============================================================ */
.post-body{font-size:16px;line-height:1.7;color:var(--text-2);word-wrap:break-word}
.post-body p{margin:0 0 22px}
.post-body h1,.post-body h2,.post-body h3,.post-body h4,.post-body h5,.post-body h6{color:var(--text);margin:28px 0 14px;line-height:1.25}
.post-body h2{font-size:24px}
.post-body h3{font-size:20px}
.post-body h4{font-size:17px}
.post-body a:not(.button){color:var(--accent);text-decoration:underline;text-underline-offset:3px}
.post-body a:not(.button):hover{color:#fff}
.post-body img{border-radius:var(--radius);height:auto!important;max-width:100%}

.post-body iframe{max-width:100%}
.post-body img.separator{max-width:100%}
.post-body ul,.post-body ol{padding:0;margin:0 0 22px;list-style:none}
.post-body ul li,.post-body ol li{padding:3px 0 3px 22px;position:relative}
.post-body ul li:before{content:"\f111";font-family:FontAwesome;font-size:7px;color:var(--accent);position:absolute;left:2px;top:10px}
.post-body ol{counter-reset:sfx}
.post-body ol li:before{content:counter(sfx);counter-increment:sfx;position:absolute;left:2px;top:6px;width:16px;height:16px;border-radius:50%;background:var(--accent);color:#fff;font-size:10px;font-weight:700;display:flex;align-items:center;justify-content:center;line-height:1}
blockquote{position:relative;background:var(--bg-pop);border-left:3px solid var(--accent);color:var(--text-2);padding:18px 22px;margin:0 0 22px;border-radius:var(--radius)}
.post-body pre,pre.code-box{position:relative;display:block;background:#0a0a0c;font-family:var(--font-mono);font-size:13px;color:var(--text-2);white-space:pre-wrap;line-height:1.5;padding:16px;margin:0 0 22px;border:1px solid var(--line);border-radius:var(--radius);overflow-x:auto}
.post-body code{font-family:var(--font-mono);background:var(--bg-pop);border:1px solid var(--line);border-radius:2px;padding:1px 6px;font-size:.92em;color:var(--text-2)}
.post-body pre code{background:none;border:0;padding:0}
.post-body table{width:100%;text-align:left;margin:0 0 22px;border-collapse:collapse}
.post-body table th,.post-body table td{padding:10px 14px;border-bottom:1px solid var(--line);text-align:left}
.post-body table thead th{color:var(--text);font-weight:700;background:var(--bg-pop)}
table.tr-caption-container,table.tr-caption-container td,table.tr-caption-container th{line-height:1;padding:0;border:0}
table.tr-caption-container td.tr-caption{font-size:13px;color:var(--text-3);padding:6px 0 0}
.post-body .google-auto-placed{margin:25px 0}
.post-videoWrapper,.post-body .videoWrapper,.post-body .responsive-video-wrap{position:relative!important;width:100%;height:0;padding-top:56.25%;overflow:hidden;border-radius:var(--radius);background:#000;margin:0 0 24px}
.post-videoWrapper iframe,.post-body .videoWrapper iframe,.post-body .responsive-video-wrap iframe{position:absolute;top:0;left:0;width:100%;height:100%;border:0}

/* ============================================================
   17. SoraFlix movie-detail markup (existing post content)
   ============================================================ */
.video-details-bar,#sora-video-details{display:flex;flex-wrap:wrap;align-items:center;gap:16px;margin:0 0 22px;padding:18px;background:var(--bg-pop);border:1px solid var(--line);border-radius:var(--radius)}
.videopost-top-image,.videopost-top-image img{display:block;max-width:110px;border-radius:var(--radius)}
.moviethumbnail{margin:0 0 22px}
.moviethumbnail img{width:auto;height:158px;object-fit:cover;border-radius:var(--radius);box-shadow:var(--shadow-md)}
.moviestoryline,.movietechdetails{display:block;margin:0 0 22px;font-size:15.5px;line-height:1.7}
.moviestoryline b,.movietechdetails b,.movietechdetails strong{color:var(--text);font-weight:600}
.moviestoryline h2,.moviestoryline h3,.movietechdetails h2,.movietechdetails h3{color:var(--text);margin:0 0 8px}
#moviedownloadlinks,.moviedownloadlinks{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 24px}
.sora-duration,.time-value{display:inline-flex;align-items:center;gap:6px;background:rgba(229,9,20,.14);color:#ff6b74;font-size:12.5px;font-weight:700;padding:4px 12px;border-radius:2px}
.sora-duration:before,.time-value:before{content:"\f017";font-family:FontAwesome;font-size:12px}
.imdbRatingPlugin{display:inline-flex;align-items:center;gap:6px;background:rgba(242,188,39,.16);color:#f8c944;font-size:12.5px;font-weight:700;padding:4px 12px;border-radius:2px}
.imdbRatingPlugin:before{content:"\f005";font-family:FontAwesome;font-size:12px}
.videotoolextra,#video-tool-shift{display:block;margin:0 0 22px}
.post-details-hide .post-body .movie-details-insidepost,.post-details-hide .post-body .video-details-bar .videopost-top-image,.post-details-hide .post-body .hide-this-on-index,.post-details-hide .detail-actions,.post-details-hide .detail-genres{display:none}

/* in-post buttons & alerts */
.post-body a.button{
  display:inline-flex;align-items:center;gap:9px;min-height:40px;padding:0 18px;
  background:rgba(255,255,255,.1);color:#fff;font-size:13.5px;font-weight:600;text-align:center;
  text-decoration:none;border-radius:var(--radius);cursor:pointer;margin:0 8px 8px 0;
  transition:background .18s,transform .12s var(--ease);
}
.post-body a.button:hover{background:var(--accent);color:#fff;transform:translateY(-1px)}
.button:before{font-family:FontAwesome;font-size:13px;font-weight:400}
.button.preview:before{content:"\f06e"}
.button.download:before{content:"\f019"}
.button.link:before{content:"\f0c1"}
.button.cart:before{content:"\f07a"}
.button.info:before{content:"\f06a"}
.button.share:before{content:"\f1e0"}
.button.contact:before{content:"\f0e0"}
.alert-message{display:flex;align-items:flex-start;gap:10px;padding:14px 16px;margin:0 0 22px;border:1px solid var(--line);border-radius:var(--radius);font-size:14.5px;color:var(--text-2)}
.alert-message:before{font-family:FontAwesome;font-size:15px;margin-top:2px}
.alert-message.alert-success{background:rgba(35,209,139,.07);border-color:rgba(35,209,139,.4)}
.alert-message.alert-success:before{content:"\f058";color:var(--ok)}
.alert-message.alert-info{background:rgba(90,165,255,.07);border-color:rgba(90,165,255,.4)}
.alert-message.alert-info:before{content:"\f05a";color:var(--info)}
.alert-message.alert-warning{background:rgba(245,185,66,.07);border-color:rgba(245,185,66,.4)}
.alert-message.alert-warning:before{content:"\f06a";color:var(--warn)}
.alert-message.alert-error{background:rgba(229,9,20,.07);border-color:rgba(229,9,20,.45)}
.alert-message.alert-error:before{content:"\f057";color:var(--accent)}
.firstcharacter{float:left;color:var(--accent);font-size:78px;line-height:.82;font-weight:800;padding-right:12px}
.post-body .tocify-inner{background:var(--bg-pop);border:1px solid var(--line);border-radius:var(--radius);padding:6px 0}
.post-body a.tocify-title{display:flex;align-items:center;justify-content:space-between;color:var(--text);font-weight:700;padding:10px 16px;text-decoration:none}
.post-body a.tocify-title:after{content:"\f078";font-family:FontAwesome;font-size:12px;opacity:.6}
.post-body #tocify{padding:0 16px 12px}
.post-body #tocify li{margin:6px 0}
.post-body #tocify a{color:var(--text-2)}
.post-body .contact-form{display:table}
.post-body .contact-form .contact-form-name,.post-body .contact-form .contact-form-email{width:calc(50% - 5px);display:inline-block}
.post-body .contact-form .contact-form-email{margin-left:10px}

/* ============================================================
   18. Post footer: labels / share / author / nav / related
   ============================================================ */
.post-labels{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px;margin:0 0 22px;font-size:13.5px}
.post-labels .labels-label{color:var(--text-3);font-weight:700;margin-right:4px}
.post-labels a.label-link,.post-labels .Label a{color:var(--text-2);font-weight:500;padding:2px 6px;border-radius:2px;transition:color .15s,background .15s}
.post-labels a.label-link:hover,.post-labels .Label a:hover{color:#fff;background:rgba(255,255,255,.08)}
.post-share{margin:0 0 26px}
.post-share ul{display:flex;flex-wrap:wrap;gap:8px}
.post-share li{display:inline-flex}
.post-share li.share-it{align-items:center;color:var(--text-3);font-size:13px;font-weight:700;padding-right:6px}
.post-share li a{
  display:inline-flex;align-items:center;justify-content:center;height:38px;min-width:38px;padding:0 13px;
  border-radius:var(--radius);background:rgba(255,255,255,.08);color:#e8e8ea;font-size:14px;
  text-decoration:none;transition:background .18s,color .18s,transform .15s var(--ease);
}
.post-share li a:hover{color:#fff;transform:translateY(-2px)}
.post-share li.facebook-f a:hover{background:#1877f2}
.post-share li.twitter a:hover{background:#000}
.post-share li.pinterest-p a:hover{background:#bd081c}
.post-share li.linkedin a:hover{background:#0a66c2}
.post-share li.whatsapp a:hover{background:#25d366}
.post-share li.email a:hover{background:#6c6c76}
.about-author{display:flex;align-items:center;gap:14px;margin:0 0 30px}
.avatar-container{flex:0 0 46px}
.author-avatar{width:46px;height:46px;border-radius:50%;object-fit:cover}
.author-name{font-size:14.5px;font-weight:700;margin:0;display:flex;gap:8px;align-items:baseline;flex-wrap:wrap}
.author-name span{color:var(--text-3);font-size:12.5px;font-weight:500}
.author-name a{color:#fff}
.author-description{color:var(--text-3);font-size:13px;line-height:1.5}
.author-description:empty{display:none}
.post-nav{display:flex;justify-content:space-between;gap:16px;margin:6px 0 0;padding:20px 0;border-top:1px solid var(--line)}
.post-nav a{display:block;font-size:13.5px;text-decoration:none;color:var(--text-2);transition:color .15s;min-width:0}
.post-nav a:hover{color:#fff}
.post-nav-inner{display:flex;flex-direction:column;gap:4px}
.post-nav-inner span{color:var(--text-3);font-size:11.5px;text-transform:uppercase;letter-spacing:.1em}
.post-nav-inner p{margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:320px}
#related-wrap{margin:48px 0 8px}
.related-ready{display:none}
#related-list{margin-top:10px}

/* ============================================================
   19. Comments
   ============================================================ */
.entry-comments{margin-top:48px;border-top:1px solid var(--line);padding-top:28px}
#comments-panel .title,.comments .title{font-size:18px;font-weight:700;margin:0 0 18px}
.comments-content #comment-holder,.comments-content .comment-holder{margin:0 0 20px}
.comment{display:flex;gap:14px;padding:16px 0;border-bottom:1px solid var(--line)}
.comment:last-child{border-bottom:0}
.avatar-image-container{flex:0 0 42px}
.avatar-image-container .author-avatar{width:42px;height:42px;border-radius:50%;object-fit:cover;display:block}
.comment-block{flex:1;min-width:0}
.comment-author{font-weight:600;font-size:14.5px;margin-bottom:2px}
.comment-author a{color:var(--text)}
.comment-body{font-size:14.5px;line-height:1.6;color:var(--text-2)}
.comment-body p{margin:4px 0}
.comment-body.deleted{opacity:.5;font-style:italic}
.comment-footer{display:flex;align-items:center;gap:10px;margin-top:6px}
.comment-timestamp{color:var(--text-3);font-size:12px}
.comment-timestamp a{color:var(--text-3)}
.comment-timestamp a:hover{color:var(--text)}
.comment-form{margin-top:22px}
.comment-form p{color:var(--text-3);font-size:14px;margin:0 0 12px}
.comment-form form input,.comment-form .comment-form input,.comment-form form textarea{margin:0 0 12px}
.comment-form .comment-action-buttons button,.comment-form button{background:var(--accent);color:#fff;border:0;border-radius:var(--radius);padding:10px 20px;font-weight:700;cursor:pointer;transition:background .18s}
.comment-form .comment-action-buttons button:hover,.comment-form button:hover{background:var(--accent-h)}
.comment-delete img{filter:invert(1)}
.blogger-iframe-colorize{height:263px!important}
.paging-control-container{display:flex;align-items:center;gap:14px;flex-wrap:wrap;color:var(--text-3);font-size:13px;margin:14px 0}
.paging-control-container a{color:var(--accent)}
#comment-holder iframe,.comment-form iframe{max-width:100%}

/* ============================================================
   20. Ads
   ============================================================ */
.home-ad{padding:6px 0 0}
.home-ad .widget-title{display:none}
.home-ad .widget-content{display:flex;justify-content:center;margin:0}
.home-ad .sora-ads-here{
  display:block;width:100%;background:var(--bg-pop);border:1px dashed var(--line);
  color:var(--text-3);text-align:center;font-size:13px;font-style:normal;line-height:90px;border-radius:var(--radius);
}
.home-ad-footer{margin-top:48px}
.inline-ad{display:flex;justify-content:center;margin:0 0 26px}
.inline-ad-placeholder{width:100%;height:100px;border:1px dashed var(--line);border-radius:var(--radius);display:flex;align-items:center;justify-content:center;color:var(--text-3);font-size:13px}

/* ============================================================
   21. Footer — Netflix-style premium footer
   ============================================================ */
.site-footer{flex-shrink:0;margin-top:56px;background:#141414;border-top:1px solid var(--line)}
.footer-inner{padding:36px var(--gutter) 26px}
.footer-nf{width:100%}
.footer-nf-q{color:var(--text-3);font-size:16px;font-weight:600;margin:0 0 20px}
.footer-nf-q a{color:var(--text-3);font-size:16px;text-decoration:none}
.footer-nf-q a:hover{color:var(--text)}
.footer-cols{width:100%;margin-bottom:20px}
.footer-nf-nav{width:100%}
.menu-footer .widget-title,.menu-footer .footer-col-title{display:none}
.menu-footer .footer-nav ul{display:grid;grid-template-columns:repeat(4,auto);justify-content:center;gap:12px 64px;text-align:center}
.menu-footer .footer-nav a{color:#8c8c8c;font-size:13px;text-decoration:none}
.menu-footer .footer-nav a:hover{color:var(--text)}
.footer-links ul{display:flex;flex-direction:column;gap:10px}
.footer-links a{color:var(--text-3);font-size:13.5px;font-weight:500}
.footer-links a:hover{color:#fff}
.footer-bottom{display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;color:#8c8c8c;font-size:12.5px;padding-top:20px;border-top:1px solid var(--line)}
.footer-bottom a{color:#8c8c8c}
.footer-bottom a:hover{color:var(--text)}

/* ============================================================
   22. Back to top / hidden widgets
   ============================================================ */
.hidden-widgets,.hidden-widgets-wrap{display:none!important;visibility:hidden!important}

/* ============================================================
   23. Responsive (one master breakpoint set)
   ============================================================ */
@media (max-width:1099px){
  :root{
    --header-h:60px;
    --card-poster:clamp(120px,20vw,168px);
    --card-land:clamp(200px,30vw,260px);
  }
  .primary-nav{display:none}
  .hamburger{display:inline-flex}
  .brand{order:1;margin-right:auto}
  .header-tools{order:2;margin-left:0}
  .hamburger{order:3;margin-left:6px}
  .account-wrap{display:none}
  .nf-search{flex:1;max-width:52vw}
  .nf-search.is-open .nf-search-input{width:100%}
}
@media (max-width:900px){
  .site-row{flex-direction:column;gap:var(--gutter)}
  .site-row .site-sidebar{width:100%;flex-shrink:1}
  body.zamd-fixed-sidebar .site-sidebar{position:static;align-self:auto}
  .home-browse-grid{grid-template-columns:1fr}
  .sfx-home-zone{grid-column:auto}
  .menu-footer .footer-nav ul{grid-template-columns:repeat(2,1fr);gap:12px 18px}
}
@media (max-width:680px){
  :root{
    --header-h:56px;
    --card-poster:clamp(120px,34vw,152px);
    --card-land:clamp(180px,44vw,220px);
    --rail-gap:8px;
  }
  .brand{margin-right:8px}
  .brand .header-brand img{height:28px;max-height:30px}
  body.is-scrolled .brand .header-brand img{height:27px}
  .brand .header-text-brand,.brand h1{font-size:20px;letter-spacing:.035em}
  .hero{min-height:min(54vh,440px)}
  .hero-body{padding-bottom:7vh}
  .hero-title{font-size:clamp(26px,8.4vw,36px)}
  .poster-grid{gap:18px 10px}
  .rail{padding-bottom:6px}
  .rail-card .rail-number{font-size:44px;bottom:-10px}
  .post-nav-inner p{max-width:150px}
  .about-author{flex-wrap:wrap}
  .post-share li.whatsapp-desktop{display:none}
  .post-body table{display:block;overflow-x:auto}
  .detail-main{padding-inline:0}
  .footer-nf-q{margin-bottom:16px}
  .footer-inner{padding:28px var(--gutter) 22px}
}
@media (hover:none){
  .rail-btn{display:none!important}
}
/* ============================================================
   S8. Trending rail (PopularPosts defaultmarkup)
   ============================================================ */
.rail-rank{
  position:absolute;top:8px;left:8px;z-index:3;min-width:30px;height:30px;padding:0 6px;
  border-radius:var(--radius);background:var(--accent);color:#fff;font-weight:800;
  font-size:var(--fs-sm);display:flex;align-items:center;justify-content:center;
  box-shadow:0 3px 10px rgba(0,0,0,.45);
}

/* ============================================================
   S9. Preview overlay (More Info modal)
   ============================================================ */
.zamd-preview-overlay{position:fixed;inset:0;z-index:9000;display:none;background:rgba(0,0,0,.85);overflow-y:auto;-webkit-overflow-scrolling:touch}
.zamd-preview-overlay.is-active{display:block}
.zamd-preview{background:var(--bg);border-radius:var(--radius-l);max-width:860px;width:96%;margin:40px auto;position:relative;overflow:hidden;box-shadow:var(--shadow-lg)}
 .zamd-preview-hero{position:relative;width:100%;aspect-ratio:16/9;background:var(--bg-pop);overflow:visible}
.zamd-preview-hero img{width:100%;height:100%;object-fit:cover}
.zamd-preview-hero-shade{position:absolute;inset:0;background:linear-gradient(transparent 30%,rgba(0,0,0,.35) 60%,var(--bg))}
.zamd-preview-posterwrap{position:absolute;left:28px;bottom:-42px;width:150px;z-index:2}
.zamd-preview-poster{width:100%;aspect-ratio:2/3;object-fit:cover;border-radius:var(--radius);box-shadow:var(--shadow-lg);border:2px solid var(--bg)}
.zamd-preview:not(.has-poster) .zamd-preview-posterwrap,.zamd-preview:not(.has-poster) .zamd-preview-hero img{display:none}
.zamd-preview-close{position:absolute;top:12px;right:12px;width:36px;height:36px;border-radius:50%;background:rgba(0,0,0,.6);color:#fff;display:flex;align-items:center;justify-content:center;z-index:3;cursor:pointer;border:0;font-size:18px}
.zamd-preview-close:hover{background:rgba(255,255,255,.2)}
.zamd-preview-body{padding:24px}
.zamd-preview.has-poster .zamd-preview-title{margin-top:34px}
.zamd-preview-title{font-size:var(--fs-xl);font-weight:700;margin-bottom:8px}
.zamd-preview-meta{display:flex;align-items:center;gap:8px;font-size:var(--fs-sm);color:var(--text-2);margin-bottom:12px;flex-wrap:wrap}
.zamd-preview-meta .sep{color:var(--text-3)}
.zamd-preview-meta .label-tag{background:var(--accent);color:#fff;padding:2px 8px;border-radius:var(--radius);font-size:var(--fs-xs);font-weight:600}
.zamd-preview-desc{font-size:var(--fs-base);color:var(--text-2);line-height:1.6;margin-bottom:20px}
.zamd-preview-genres{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:20px}
.zamd-preview-genres span{background:var(--bg-pop);color:var(--text-2);padding:4px 10px;border-radius:var(--radius);font-size:var(--fs-xs)}
.zamd-preview-actions{display:flex;gap:12px;flex-wrap:wrap}
.zamd-preview-actions .btn{min-width:140px}
.zamd-preview-views{font-size:var(--fs-sm);color:var(--text-3);margin-top:12px}
.zamd-lightbox{position:fixed;inset:0;z-index:9500;display:none;background:rgba(0,0,0,.92);align-items:center;justify-content:center;padding:24px;overflow-y:auto;-webkit-overflow-scrolling:touch}
.zamd-lightbox.is-active{display:flex}
.zamd-lightbox-stage{max-width:1100px;width:100%;text-align:center}
.zamd-lightbox-img{max-width:100%;max-height:86vh;object-fit:contain;border-radius:var(--radius-l);box-shadow:var(--shadow-lg)}
.zamd-lightbox-cap{color:var(--text-2);font-size:var(--fs-base);margin-top:14px}
.zamd-lightbox-close{position:absolute;top:16px;right:16px;width:44px;height:44px;border:0;border-radius:50%;background:rgba(255,255,255,.12);color:#fff;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;z-index:3;transition:background .18s}
.zamd-lightbox-close:hover{background:var(--accent)}
body.lightbox-open{overflow:hidden}
.blog-pager .pager-cur-wrap{display:inline-flex;align-items:center;gap:8px}
.blog-pager .pager-cur{display:inline-flex;align-items:center;justify-content:center;min-width:40px;height:40px;padding:0 14px;border-radius:var(--radius);background:var(--accent);color:#fff;font-size:14px;font-weight:700}
@media(max-width:600px){
  .zamd-preview-overlay{display:none}
  .zamd-preview-overlay.is-active{display:flex;align-items:flex-end}
  .zamd-preview{width:100%;margin:0;border-radius:var(--radius-l) var(--radius-l) 0 0;max-height:92vh;overflow-y:auto;-webkit-overflow-scrolling:touch}
  .zamd-preview-hero{aspect-ratio:16/10}
  .zamd-preview-posterwrap{left:16px;bottom:-30px;width:108px}
  .zamd-preview-body{padding:16px}
  .zamd-preview.has-poster .zamd-preview-title{margin-top:26px}
  .zamd-preview-actions .btn{flex:1 1 140px;min-width:0;justify-content:center}
}

/* ============================================================
   S10. Bookmarks panel (My List)
   ============================================================ */
.zamd-bookmarks-panel{
      position:fixed;left:50%;top:50%;z-index:9100;width:min(430px,92vw);max-height:82vh;
    transform:translate(-50%,-46%) scale(.98);opacity:0;visibility:hidden;
    background:var(--bg);border:1px solid var(--line);border-radius:8px;
    box-shadow:var(--shadow-lg);display:flex;flex-direction:column;overflow:hidden;
    transition:opacity .25s var(--ease),transform .25s var(--ease),visibility .25s;
  }
  .zamd-bookmarks-panel.is-open{opacity:1;visibility:visible;transform:translate(-50%,-50%)}
.zamd-bm-header{display:flex;align-items:center;justify-content:space-between;padding:16px 20px;border-bottom:1px solid var(--line)}
.zamd-bm-header h3{font-size:var(--fs-md);font-weight:700}
.zamd-bm-close{background:none;border:0;color:var(--text);font-size:20px;cursor:pointer;padding:4px}
.zamd-bm-list{flex:1;overflow-y:auto;padding:12px 20px}
.zamd-bm-item{display:flex;gap:12px;padding:10px 0;border-bottom:1px solid var(--line)}
.zamd-bm-item:last-child{border-bottom:none}
.zamd-bm-item img{width:60px;height:80px;object-fit:cover;border-radius:var(--radius);flex-shrink:0}
.zamd-bm-item-info{flex:1;min-width:0}
.zamd-bm-item-title{font-size:var(--fs-sm);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.zamd-bm-item-title a{color:var(--text)}
.zamd-bm-item-meta{font-size:var(--fs-xs);color:var(--text-3);margin-top:2px}
.zamd-bm-item-remove{background:none;border:0;color:var(--text-3);font-size:var(--fs-xs);cursor:pointer;margin-top:4px;padding:0}
.zamd-bm-item-remove:hover{color:var(--accent)}
.zamd-bm-empty{text-align:center;padding:40px 20px;color:var(--text-3);font-size:var(--fs-sm)}
.zamd-bm-btn{position:relative;background:none;border:0;color:var(--text);font-size:18px;cursor:pointer;padding:6px}
.zamd-bm-count{position:absolute;top:-2px;right:-4px;background:var(--accent);color:#fff;font-size:10px;font-weight:700;min-width:16px;height:16px;border-radius:8px;display:flex;align-items:center;justify-content:center;padding:0 4px}
.zamd-bm-count:empty,.zamd-bm-count[data-count="0"]{display:none}
.zamd-bm-backdrop{position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9099;display:none}
.zamd-bm-backdrop.is-show{display:block}

/* ============================================================
   S11. Episode browser
   ============================================================ */
/* The episode strip's own vertical margin. The wrapper is emitted as
   .zamd-ep by the engine (and .zamd-ep series-index on the series browser);
   the rule was written for .zamd-episodes, which nothing emits, so the wrapper
   itself never got its margin and only its children were spaced. */
.zamd-episodes,.zamd-ep{margin:24px 0}
.zamd-ep-header{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:12px;flex-wrap:wrap}
.zamd-ep-series{font-size:var(--fs-md);font-weight:700}
.zamd-ep-count{font-size:var(--fs-xs);color:var(--text-3)}
.zamd-ep-list{display:flex;gap:8px;overflow-x:auto;scroll-snap-type:x mandatory;padding-bottom:8px;scrollbar-width:none}
.zamd-ep-list::-webkit-scrollbar{display:none}
.zamd-ep-item{flex:0 0 150px;scroll-snap-align:start;text-align:left;cursor:pointer;border-radius:var(--radius);overflow:hidden;background:var(--bg-pop);border:2px solid transparent;transition:border-color .2s;text-decoration:none;color:var(--text)}
.zamd-ep-item:hover{border-color:var(--text-3);color:var(--text)}
.zamd-ep-item.is-current{border-color:var(--accent)}
.zamd-ep-item-thumb{width:100%;aspect-ratio:16/9;object-fit:cover}
.zamd-ep-item-num{position:absolute;top:6px;left:6px;background:rgba(0,0,0,.7);color:#fff;font-size:var(--fs-xs);font-weight:600;padding:2px 6px;border-radius:var(--radius)}
.zamd-ep-item-title{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:var(--fs-xs);font-weight:600;padding:6px 8px;line-height:1.3;color:var(--text)}
.zamd-ep-item{position:relative}
.zamd-ep-seasons{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
.zamd-ep-season{padding:6px 12px;border-radius:99px;background:var(--bg-pop);border:1px solid var(--line);color:var(--text-2);font-size:var(--fs-xs);font-weight:700}
.zamd-ep-season:hover{border-color:var(--text-3);color:var(--text)}
.zamd-ep-season.is-current{background:var(--accent);border-color:var(--accent);color:#fff}
.zamd-ep-nav{display:flex;gap:8px;margin-top:12px}
.zamd-ep-nav a{flex:1;min-width:140px;display:flex;flex-direction:column;gap:2px;text-align:center;padding:10px 14px;background:var(--bg-pop);border-radius:var(--radius);color:var(--text);font-size:var(--fs-sm);font-weight:600;border:1px solid var(--line);transition:all .2s;text-decoration:none}
.zamd-ep-nav a:hover{border-color:var(--accent);color:var(--accent)}
.zamd-ep-nav a.is-disabled{opacity:.3;pointer-events:none}
.zamd-ep-nav-label{font-size:var(--fs-xs);color:var(--text-3);text-transform:uppercase;letter-spacing:.06em}
.zamd-ep-nav-title{font-size:var(--fs-sm);font-weight:600;color:var(--text)}
.zamd-ep-nav .fa{font-size:16px;color:var(--accent)}

/* ============================================================
   S12. Cookie consent bar
   ============================================================ */
.zamd-cookie-bar{position:fixed;bottom:0;left:0;right:0;background:var(--bg);border-top:1px solid var(--line);padding:14px 20px;display:none;z-index:9200;align-items:center;justify-content:space-between;gap:16px}
.zamd-cookie-bar.is-show{display:flex}
.zamd-cookie-bar p{font-size:var(--fs-sm);color:var(--text-2);flex:1}
.zamd-cookie-accept{background:var(--accent);color:#fff;border:0;padding:8px 20px;border-radius:var(--radius);font-size:var(--fs-sm);font-weight:600;cursor:pointer;white-space:nowrap}
.zamd-cookie-accept:hover{background:var(--accent-h)}

/* ============================================================
   S13. Views counter badge
   ============================================================ */
.zamd-views{font-size:var(--fs-xs);color:var(--text-3)}
.zamd-views i{margin-right:3px}

/* ============================================================
   S14. Lazy loading
   ============================================================ */
.zamd-lazy{opacity:0;transition:opacity .3s}
.zamd-lazy.is-loaded{opacity:1}

/* ============================================================
   S15. Sidebar
   ============================================================ */
.site-sidebar{width:300px;flex-shrink:0}
.site-sidebar .widget{margin-bottom:24px}
.site-sidebar .widget-title .title{font-size:var(--fs-md);font-weight:700;margin-bottom:12px;padding-bottom:8px;border-bottom:1px solid var(--line)}

/* ============================================================
   S16. Detail page episode section
   ============================================================ */
.detail-episodes{margin:24px 0;padding:24px;background:var(--bg-pop);border-radius:var(--radius-l)}
.detail-episodes:empty{display:none}

/* ============================================================
   S18. Theme modes (light / system), boxed layout, views
   ============================================================ */
html[data-mode="light"]{
  --bg:#f5f5f5;--bg-deep:#e9e9eb;--bg-pop:#ffffff;--bg-hover:rgba(0,0,0,.05);
  --line:rgba(0,0,0,.1);--line-strong:rgba(0,0,0,.2);
  --text:#1a1a1a;--text-2:#444;--text-3:#767676;
  --shadow-sm:0 2px 10px rgba(0,0,0,.06);--shadow-md:0 14px 40px rgba(0,0,0,.12);--shadow-lg:0 24px 60px rgba(0,0,0,.18);
}
html[data-mode="light"] .site-footer,html[data-mode="light"] .site-header{background:var(--bg);border-color:var(--line)}
html[data-mode="light"] .drawer{background:#ffffff}
html[data-mode="light"] .nf-search{background:#ffffff}
html[data-mode="light"] .zamd-views{background:var(--bg-pop)}

body.zamd-boxed .layout,body.zamd-boxed .site-row,body.zamd-boxed .site-main>.layout,body.zamd-boxed .footer-inner{max-width:1400px}
body.zamd-boxed .site-header .layout{max-width:1400px}
body.zamd-fixed-sidebar .site-sidebar{position:sticky;top:calc(var(--header-h) + 20px);align-self:flex-start}
body.zamd-fixed-sidebar .detail-wrap.layout{align-items:flex-start}

.zamd-views{display:inline-flex;align-items:center;gap:6px;font-size:var(--fs-xs);color:var(--text-3)}
.zamd-views i{font-size:.9em}
.zamd-views.has-count::after{content:attr(data-label)}
.detail-meta .zamd-views::before{content:'\2022';margin-right:6px;opacity:.5}
.zamd-bm-count[data-count="0"],.zamd-bm-count:not([data-count]){display:none}
    /* ============================================================
       24. Post meta disclosure (labels + share collapse)
       ============================================================ */
    .zd-post-meta{margin:22px 0;padding-top:14px;border-top:1px solid var(--line);font-size:13.5px}
    .zd-post-meta>summary{cursor:pointer;color:var(--text-3);font-weight:600;letter-spacing:.02em;list-style:none;display:inline-flex;align-items:center;gap:8px}
    .zd-post-meta>summary::-webkit-details-marker{display:none}
    .zd-post-meta>summary:after{content:"\f078";font-family:FontAwesome;font-size:11px;transition:transform .2s var(--ease)}
    .zd-post-meta[open]>summary:after{transform:rotate(180deg)}
    .zd-post-meta[open]>summary{color:var(--text-2)}
    .zd-post-meta>*:not(summary){margin-top:14px}

    /* ============================================================
       25. Responsive anchors + hero step-down + print
       ============================================================ */
    .post-body h1,.post-body h2,.post-body h3,.post-body h4,[id]{scroll-margin-top:calc(var(--header-h) + 14px)}
    @media (max-width:900px){
      .hero{min-height:min(62vh,560px)}
      .detail-head{padding-top:16px}
    }
    @media print{
      .site-header,.drawer,.backdrop,.home-hero,.hero,.detail-hero,.detail-player,#back-top,.zamd-preview-overlay,.zamd-cookie-bar,.zamd-bookmarks-panel,.blog-pager,.post-share,.social-widget,.home-ad{display:none!important}
      body{background:#fff;color:#000}
      .post-body,.post-body h1,.post-body h2,.post-body h3,.post-body h4,.post-title,.detail-title{color:#000}
      .zd-post-meta{display:block}
    }

    /* ============================================================
       Skeleton loading (professional, Netflix-calm)
       One soft pulse, never a hard sweep: a slow brightness wash over
       #1a1a1a plates with per-card stagger, so a loading row reads as
       "about to fill in" rather than a barcode. Cards carry a media box
       plus a single title line, mirroring what will actually replace them.
       ============================================================ */
    @keyframes zamd-skel{0%{opacity:.55}50%{opacity:1}100%{opacity:.55}}
    .skel,.rail-skel,.nf-results-skel{
      background:#1c1c1e;border-radius:4px;
      animation:zamd-skel 1.4s ease-in-out infinite;
      animation-delay:calc(var(--skel-i,0) * 110ms);
      will-change:opacity;
    }
    .skel-card{flex:0 0 var(--card-land);min-width:0}
    .skel-media{aspect-ratio:16/9;border-radius:4px}
    .skel-line{height:11px;border-radius:3px;margin-top:10px;width:82%}
    .skel-line.is-short{width:52%;margin-top:7px;height:9px}
    .skel-card.is-poster{flex-basis:var(--card-poster)}
    .skel-card.is-poster .skel-media{aspect-ratio:2/3}
    .rail-skel{flex:0 0 var(--card-land);aspect-ratio:16/9;border-radius:4px}
    .rail-mode-poster>.rail-skel,.poster-rail:not(.rail-mode-landscape)>.rail-skel{flex-basis:var(--card-poster);aspect-ratio:2/3}
    .nf-results-skel{aspect-ratio:16/9}
    .rail.rail-empty{display:flex;align-items:center;justify-content:center;min-height:132px;padding:16px;border:1px dashed var(--line);border-radius:var(--radius);color:var(--text-3);font-size:var(--fs-sm);text-align:center}

    /* ============================================================
       26. Continue Watching + hero hardening
       ============================================================ */
    #cw-rail:empty{display:none}
    .cw-card{min-width:0}
    .hero{background:radial-gradient(120% 90% at 70% 10%,rgba(229,9,20,.14),transparent 55%),linear-gradient(180deg,#141416,var(--bg-deep))}
    .hero-body{padding-top:calc(var(--header-h) + 10px)}

    /* ============================================================
       27. Netflix UI layer — full-bleed rails, pill nav, instant
          search takeover, card badges, streaming footer.
       ============================================================ */
    :root{
      --nf-head:80px;
      --nf-red:#e50914;
      --nf-bg:#141414;
      --nf-ink:#141414;
      --nf-txt:#e5e5e5;
      --nf-mute:#b3b3b3;
      --nf-dim:#737373;
      --nf-gap:8px;
      /* Results are a grid, not a rail: they need their own, roomier rhythm.
         --nf-gap is deliberately tiny because Netflix rows run cards edge to
         edge, and reusing it left the results titles touching. */
      --nf-grid-gap-y:clamp(22px,2.2vw,34px);
      --nf-grid-gap-x:clamp(14px,1.4vw,24px);
      --nf-pad:clamp(16px,3.4vw,60px);
      --nf-card:clamp(186px,15.4vw,298px);
      --nf-card-p:clamp(124px,10.1vw,190px);
      --nf-row-gap:clamp(28px,2.8vw,46px);
    }
    @media (max-width:1000px){ :root{ --nf-head:64px } }
    @media (max-width:560px){ :root{ --nf-head:56px } }

    /* ---- 27a. header ---- */
    body.view-home .site-header{height:var(--nf-head);background:linear-gradient(180deg,rgba(0,0,0,.82) 0%,rgba(0,0,0,0) 100%)}
    body.view-home.is-scrolled .site-header{background:rgba(20,20,20,.99);-webkit-backdrop-filter:blur(12px);backdrop-filter:blur(12px);box-shadow:0 1px 0 rgba(255,255,255,.06)}
    body.view-home .header-inner{padding:0 var(--nf-pad);gap:0}
    body.view-home .brand{margin-right:22px}
    body.view-home .brand .header-brand img,
    body.view-home .brand .header-text-brand,
    body.view-home .brand h1{height:26px;font-size:23px;letter-spacing:.02em}
    body.view-home.is-scrolled .brand .header-brand img{height:24px}

    /* pill nav */
    body.view-home .primary-nav .menu-list{gap:2px;overflow-x:auto;scrollbar-width:none}
    body.view-home .primary-nav .menu-list::-webkit-scrollbar{display:none}
    body.view-home .primary-nav .menu-list>li>a,
    body.view-home .primary-nav .sub-toggle{
      padding:6px 12px;border-radius:999px;font-size:13.5px;font-weight:500;
      color:rgba(255,255,255,.86);background:none;transition:background .18s,color .18s;
    }
    body.view-home .primary-nav .menu-list>li>a:hover,
    body.view-home .primary-nav .sub-toggle:hover{background:rgba(255,255,255,.12);color:#fff}
    body.view-home .primary-nav .menu-list>li:first-child>a{font-weight:500}
    /* activeNav() marks the current page with .is-active - match on that, and on
       .is-current too, so the white pill shows on whichever is applied */
    body.view-home .primary-nav .menu-list>li>a.is-active,
    body.view-home .primary-nav .menu-list>li>a.is-current,
    body.view-home .primary-nav .menu-list>li.is-active>a,
    body.view-home .primary-nav .menu-list>li.is-current>a{background:#fff;color:#000;font-weight:600}
    body.view-home .primary-nav .sub-menu{top:calc(100% + 6px);background:#1f1f1f;border:0}

    /* right cluster: search pill, bell, avatar */
    body.view-home .header-tools{gap:14px;margin-left:auto}
    body.view-home .zamd-bm-btn{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:999px;font-size:16px;color:#fff;background:none;border:0;cursor:pointer;transition:background .18s}
    body.view-home .zamd-bm-btn:hover{background:rgba(255,255,255,.12)}
    body.view-home .zamd-bm-count{font-size:12px;color:var(--nf-mute)}
    body.view-home .account-avatar{width:32px;height:32px;border-radius:6px;background:#333;color:#fff}
    body.view-home .account-drop{background:#1f1f1f;border:0}

    /* search: always-visible pill on the homepage */
    body.view-home .nf-search-input{
      width:clamp(120px,15vw,240px);opacity:1;padding:7px 34px 7px 36px;margin:0;
      background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.35);border-radius:4px;
      color:#fff;font-size:14px;transition:border-color .2s,background .2s,width .25s;
    }
    body.view-home .nf-search-input::placeholder{opacity:1;color:var(--nf-dim)}
    body.view-home .nf-search-input:focus{background:rgba(0,0,0,.85);border-color:transparent;box-shadow:0 0 0 1px #fff}
    body.view-home .nf-search-input::-webkit-search-cancel-button{display:none}
    body.view-home .nf-search-toggle{width:34px;height:34px;font-size:15px;position:absolute;left:1px;z-index:2;background:none;border-radius:4px;cursor:pointer}
    body.view-home .nf-search-toggle:hover{background:rgba(255,255,255,.12)}
    body.view-home .nf-search-toggle .nf-search-glass{display:none}
    body.view-home .nf-search.is-open .nf-search-input{width:clamp(180px,26vw,420px)}
    body.view-home .nf-search-clear{position:absolute;right:1px;width:32px;height:32px;font-size:14px;background:none;cursor:pointer}

    /* ---- 27b. rail geometry: 16:9 cards, tight gap, edge bleed ---- */
    body.view-home .rail{gap:var(--nf-gap);padding-inline:0;margin-top:0}
    body.view-home .rail-wrap{margin-top:0}
    body.view-home .rail-heading{margin:0 0 10px;padding:0;display:flex;align-items:center;justify-content:space-between;gap:16px}
    body.view-home .rail-heading .rail-heading-title{font-size:clamp(16px,1.35vw,21px);font-weight:700;letter-spacing:-.01em;color:#fff}
    body.view-home .rail-explore{
      display:inline-flex;align-items:center;gap:6px;flex:0 0 auto;
      color:var(--nf-mute);font-size:13px;font-weight:500;text-decoration:none;white-space:nowrap;transition:color .15s;
    }
    body.view-home .rail-explore:hover{color:#fff}
    body.view-home .rail-explore .fa{font-size:10px;opacity:.8}
    /* One rhythm for the whole page. These used to be a mix of per-widget
       margins, which is why some rows sat on top of the previous one while
       others floated away. Every home block now gets the same bottom gap. */
    body.view-home .home-zone,
    body.view-home .home-rails-wrap,
    body.view-home .home-rails,
    body.view-home .home-chips-zone,
    body.view-home .home-trending-zone,
    body.view-home #cw-zone{margin:0 0 var(--nf-row-gap)}
    body.view-home .home-rails .widget,
    body.view-home .home-rails-wrap>.zd-shortcode,
    body.view-home .poster-grid,
    body.view-home .latest-zone{margin:0 0 var(--nf-row-gap)}
    body.view-home .home-rails .widget:empty,
    body.view-home .zd-shortcode:empty{display:none}
    body.view-home .home-zone:last-child,
    body.view-home .home-chips-zone:last-child{margin-bottom:0}
    /* Latest Posts lives inside Blogger's own "main" section while the other rows
       are top-level zones, so that section's own spacing used to stack on top of
       the rhythm: Continue Watching -> Latest Posts read as two gaps while
       Latest Posts -> Trending Now read as none. Only the TOP is cleared here.
       An earlier version of this rule used the `margin` shorthand, which also
       wiped the bottom - and because the row inside the section is the one that
       owns the gap, that removed it from Latest Posts alone. That is exactly the
       "one row sits too close to the next" asymmetry, and it only appeared on
       the real Blogger page, where the section wrapper puts the row one level
       deeper than the preview does. The gap is re-asserted below for the same
       reason, so the nesting depth cannot change the result. */
    body.view-home .content-main,
    body.view-home #main{margin:0;padding:0}
    body.view-home .content-main>.widget,
    body.view-home .content-main>.widget-content{margin-top:0;padding-top:0}
    body.view-home .content-main .home-zone,
    body.view-home .content-main .latest-zone,
    body.view-home #main .home-zone,
    body.view-home #main .latest-zone{margin:0 0 var(--nf-row-gap)}
    /* a row heading hugs its own cards, not the row above it */
    body.view-home .rail{padding-bottom:0}
    body.view-home .rail-heading{margin:0 0 clamp(8px,.8vw,12px)}
    body.view-home .poster-title{margin-top:clamp(6px,.55vw,9px)}
    body.view-home .home-chips-zone .rail-heading{margin-bottom:clamp(8px,.8vw,12px)}

    /* edge fade like Netflix */
    body.view-home .rail-wrap::before,
    body.view-home .rail-wrap::after{
      content:"";position:absolute;top:0;bottom:0;width:clamp(24px,4vw,68px);z-index:4;pointer-events:none;opacity:0;transition:opacity .2s;
    }
    body.view-home .rail-wrap::before{left:calc(-1 * var(--nf-pad));background:linear-gradient(90deg,var(--nf-bg) 12%,rgba(20,20,20,0))}
    body.view-home .rail-wrap::after{right:calc(-1 * var(--nf-pad));background:linear-gradient(270deg,var(--nf-bg) 12%,rgba(20,20,20,0))}
    body.view-home .rail-wrap.has-scroll.at-start::before{opacity:0}
    body.view-home .rail-wrap.at-start::before{opacity:0}
    body.view-home .rail-wrap.has-scroll::before,
    body.view-home .rail-wrap.has-scroll::after{opacity:1}
    body.view-home .rail-wrap.at-end::after{opacity:0}
    body.view-home .rail-wrap{overflow:visible}
    body.view-home .rail{scroll-padding-inline:0}

    /* arrows: circular, Netflix-ish. `bottom:auto` is required because the base
       rule stretches the button between top:0 and bottom:0. */
    body.view-home .rail-btn{
      width:34px;height:34px;min-height:34px;top:50%;bottom:auto;transform:translateY(-50%);
      margin-top:0;border-radius:50%;background:rgba(20,20,20,.72);color:#fff;font-size:12px;
      z-index:6;opacity:0;visibility:hidden;transition:opacity .2s,background .2s,visibility .2s;
    }
    body.view-home .rail-wrap:hover .rail-btn:not(.is-hidden){opacity:1;visibility:visible}
    body.view-home .rail-btn:hover{background:rgba(48,48,48,.92)}
    body.view-home .rail-btn.prev{left:-14px;background:rgba(20,20,20,.72)}
    body.view-home .rail-btn.next{right:-14px;background:rgba(20,20,20,.72)}
    @media (max-width:700px){
      body.view-home .rail-btn{display:none}
    }

    /* ---- 27c. cards ---- */
    body.view-home .poster-card{position:relative;scroll-snap-align:start}
    body.view-home .rail-card-landscape,
    body.view-home .rail-mode-landscape>.rail-card-landscape{flex-basis:var(--nf-card);min-width:var(--nf-card);max-width:var(--nf-card)}
    body.view-home .rail-card-poster,
    body.view-home .rail-mode-poster>.rail-card-poster{flex-basis:var(--nf-card-p);min-width:var(--nf-card-p);max-width:var(--nf-card-p)}
    body.view-home .poster-media{
      border-radius:4px;background:#232323;overflow:hidden;
      transition:transform .28s var(--ease),box-shadow .28s var(--ease);
    }
    body.view-home .rail-card-landscape .poster-media{aspect-ratio:16/9}
    body.view-home .poster-card:hover .poster-media,
    body.view-home .poster-card:focus-within .poster-media{transform:scale(1.055);box-shadow:0 8px 26px rgba(0,0,0,.55);z-index:6}
    body.view-home .poster-card:hover,
    body.view-home .poster-card:focus-within{z-index:6}
    /* A title block is a fixed two-line box, not a variable one. Clamping to two
       lines is not enough on its own: a rail whose titles all fit on one line
       ended up 18px shorter than a rail with a two-line title, so the rows did
       not share a baseline and the page read as broken rhythm. The subtitle line
       is reserved too, because it is only rendered when the post has a year. */
    body.view-home .poster-title{margin-top:9px;font-size:13.5px;line-height:1.35;font-weight:500;color:#e8e8ea;-webkit-line-clamp:2;min-height:2.7em}
    body.view-home .poster-sub,
    body.view-home .rail-card .poster-sub{min-height:1.35em}
    body.view-home .poster-title a{color:inherit}
    body.view-home .poster-title a:hover{color:#fff;text-decoration:none}
    body.view-home .poster-sub{display:none}
    body.view-home .poster-more{opacity:0;transform:translateY(4px)}
    body.view-home .poster-card:hover .poster-more,
    body.view-home .poster-card:focus-within .poster-more{opacity:1;transform:none}
    body.view-home .poster-hover .play-ic{background:rgba(20,20,20,.7);border-radius:50%;width:34px;height:34px}
    body.view-home .rail-rank{
      left:0;bottom:0;top:auto;transform:none;width:30px;height:34px;
      font-size:24px;font-weight:800;color:#fff;-webkit-text-stroke:2px rgba(0,0,0,.65);
    }
    /* a landscape card is a third of the height of a poster one, so the
       Netflix-style rank block has to be scaled back to stay a label and not
       swallow the artwork */
    body.view-home .rail-mode-landscape .rail-rank{
      width:24px;height:26px;font-size:17px;background:var(--accent);
      -webkit-text-stroke:0;border-radius:0 0 var(--radius) 0;
    }

    /* Netflix corner badges */
    .nf-badge{
      position:absolute;left:0;top:0;z-index:3;padding:3px 7px;
      font-size:10.5px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;
      color:#fff;background:var(--nf-red);border-radius:0 0 4px 0;
    }
    .nf-badge.is-dark{background:rgba(20,20,20,.82);backdrop-filter:blur(4px);border-radius:0 0 4px 0}
    .nf-badge.is-new{background:linear-gradient(120deg,#e50914,#b20710)}
    body.view-home .poster-media .nf-badge{left:0;top:0}


    /* ---- 27e. instant search takeover ---- */
    .nf-taken-over .hero,
    .nf-taken-over .home-trending,
    .nf-taken-over .home-chips-zone,
    .nf-taken-over .home-rails-wrap,
    .nf-taken-over .latest-zone,
    .nf-taken-over #cw-zone{display:none!important}
    .nf-taken-over .site-main>.layout{padding-top:calc(var(--nf-head) + 18px)}
    .nf-results{display:none}
    body.nf-taken-over .nf-results{display:block}
    body.nf-taken-over:not(.view-home) .nf-results{padding-top:calc(var(--header-h) + 26px)}
    body.nf-taken-over .site-main .layout > :not(.nf-results){display:none!important}
    .nf-results-head{display:flex;align-items:baseline;gap:12px;margin:0 0 6px}
    .nf-results-head h2{margin:0;font-size:clamp(17px,1.5vw,22px);font-weight:700;letter-spacing:-.01em;color:#fff}
    .nf-results-head span{color:var(--nf-dim);font-size:13.5px}
    .nf-results-grid{
      display:grid;
      grid-template-columns:repeat(auto-fill,minmax(clamp(150px,15vw,240px),1fr));
      gap:var(--nf-grid-gap-y) var(--nf-grid-gap-x);
      padding:14px 0 8px;
    }
    .nf-results-grid .poster-card{scroll-snap-align:none;min-width:0}
    .nf-results-grid .poster-media{aspect-ratio:16/9}
    .nf-results-grid .poster-sub{display:flex}
    /* long release titles must wrap inside their own column, never spill into
       the next result */
    .nf-results-grid .poster-title{overflow-wrap:anywhere;word-break:normal}
    .nf-results-empty{padding:38px 0;color:var(--nf-mute);font-size:15px}

    /* ---- 27f. hero: text first, image later ---- */
    body.view-home .hero{
      min-height:min(78vh,660px);
      background:radial-gradient(120% 100% at 72% 22%,rgba(229,9,20,.2),transparent 58%),linear-gradient(180deg,#1b1b1e 0%,#101012 100%);
    }
    body.view-home .hero-media{opacity:0;transition:opacity .45s var(--ease)}
    body.view-home .hero-media.is-ready{opacity:1}
    body.view-home .hero-shade{background:linear-gradient(90deg,rgba(0,0,0,.92) 0%,rgba(0,0,0,.62) 38%,rgba(0,0,0,0) 68%),linear-gradient(180deg,rgba(0,0,0,.5) 0%,rgba(0,0,0,0) 30%,rgba(0,0,0,.55) 88%,rgba(20,20,20,1) 100%)}
    body.view-home .hero-body{padding-top:clamp(96px,13vh,160px);max-width:640px}
    body.view-home .hero-title{font-size:clamp(28px,4.4vw,52px);margin-bottom:12px}
    body.view-home .hero-synopsis{font-size:clamp(14px,1.15vw,16.5px);-webkit-line-clamp:3;margin-bottom:16px;max-width:560px}
    body.view-home .hero-eyebrow{
      display:inline-flex;align-items:center;gap:7px;margin:0 0 12px;padding:4px 10px;border-radius:3px;
      background:rgba(229,9,20,.92);color:#fff;font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
    }
    body.view-home .hero-actions .btn{font-size:clamp(14px,1.15vw,17px);padding:9px 22px;border-radius:4px}
    body.view-home .hero-actions .btn-play{background:#fff;color:#141414}
    body.view-home .hero-actions .btn-play:hover{background:rgba(255,255,255,.78)}
    body.view-home .hero-actions .btn-ghost{background:rgba(109,109,110,.62);color:#fff}
    body.view-home .hero-actions .btn-ghost:hover{background:rgba(109,109,110,.85)}
    @keyframes zamd-hero-pulse{0%,100%{opacity:.5}50%{opacity:.85}}
    body.view-home .hero:not(.has-art) .hero-body{animation:zamd-hero-in .5s var(--ease) both}
    @keyframes zamd-hero-in{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}

    /* ---- 27g. footer ---- */
    .site-footer{background:var(--nf-bg);border-top:1px solid rgba(255,255,255,.09);color:var(--nf-dim);margin-top:64px}
    html[data-mode="light"] .site-footer{background:#f5f5f5;border-top-color:rgba(0,0,0,.1)}
    .footer-inner{padding:44px var(--nf-pad) 28px;max-width:none}
    .footer-nf-q{display:none}
    .footer-cols{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:26px var(--nf-pad);margin:0 0 26px}
    .footer-cols .footer-nf-nav{grid-column:1/-1}
    .footer-nf-nav{width:100%}
    .footer-nav ul{display:flex;flex-direction:column;gap:13px;margin:0;padding:0}
    .footer-nav a,.footer-links a{color:var(--nf-dim);font-size:13.5px;font-weight:500;text-decoration:none;transition:color .15s}
    .footer-nav a:hover,.footer-links a:hover{color:#e5e5e5;text-decoration:none}
    .footer-links ul{gap:13px}
    .footer-col-title{color:var(--nf-dim);font-size:13.5px;margin-bottom:12px}
        .footer-bottom{
      display:flex;flex-wrap:wrap;align-items:center;justify-content:center;gap:14px;
      padding:0;border:0;color:var(--nf-dim);font-size:13.5px;text-align:center;
    }
    .footer-bottom a{color:var(--nf-dim)}
    .footer-bottom a:hover{color:#e5e5e5}
    .site-footer .social-widget{display:none}
    .footer-lang{
      display:inline-flex;align-items:center;gap:9px;padding:7px 13px;border-radius:4px;
      border:1px solid rgba(255,255,255,.3);color:#e5e5e5;font-size:13.5px;background:transparent;cursor:pointer;
    }
    .footer-lang:hover{border-color:rgba(255,255,255,.6)}
    @media (max-width:820px){
      .footer-cols{grid-template-columns:repeat(2,minmax(0,1fr));gap:22px var(--nf-pad)}
    }
    @media (max-width:420px){
      .footer-cols{grid-template-columns:1fr}
    }

    /* ---- 27h. genre chips ---- */
    body.view-home .genre-nav{gap:8px;padding:0;margin-bottom:6px}
    body.view-home .genre-nav a{
      padding:6px 14px;border-radius:999px;background:rgba(255,255,255,.08);
      color:rgba(255,255,255,.85);font-size:13px;font-weight:500;transition:background .15s,color .15s;
    }
    body.view-home .genre-nav a:hover{background:rgba(255,255,255,.2);color:#fff}
    body.view-home .genre-nav a.is-active{background:#fff;color:#141414}
    body.view-home .home-chips-zone .rail-heading{margin-bottom:12px}

    /* ---- 27i. mobile step-down: these body.view-home rules outrank the base
       breakpoints above, so the smaller hero/pill sizes must be restated here ---- */
    @media (max-width:900px){
      body.view-home .hero{min-height:min(58vh,520px)}
      body.view-home .hero-body{padding-top:clamp(84px,11vh,124px);max-width:none}
      body.view-home .hero-shade{background:linear-gradient(180deg,rgba(0,0,0,.72) 0%,rgba(0,0,0,.35) 45%,rgba(0,0,0,.7) 90%,rgba(20,20,20,1) 100%)}
      body.view-home .rail-card-landscape,
      body.view-home .rail-mode-landscape>.rail-card-landscape{flex-basis:clamp(200px,42vw,280px);min-width:clamp(200px,42vw,280px);max-width:clamp(200px,42vw,280px)}
      body.view-home .rail-card-poster,
      body.view-home .rail-mode-poster>.rail-card-poster{flex-basis:clamp(124px,27vw,168px);min-width:clamp(124px,27vw,168px);max-width:clamp(124px,27vw,168px)}
    }
    @media (max-width:560px){
      body.view-home .hero{min-height:min(52vh,460px)}
      body.view-home .hero-title{font-size:clamp(25px,7.4vw,34px)}
      body.view-home .hero-actions{gap:8px}
      body.view-home .header-tools{gap:6px}
      body.view-home .brand .header-brand img,
      body.view-home .brand .header-text-brand,
      body.view-home .brand h1{font-size:17px;height:22px}
      /* icon-first search: the field only opens when the visitor asks for it,
         which is what keeps a 390px header from overflowing */
      body.view-home .nf-search-input{
        width:0;opacity:0;padding:0;border:0;background:transparent;box-shadow:none;
      }
      body.view-home .nf-search.is-open .nf-search-input{
        width:min(54vw,230px);opacity:1;padding:6px 28px 6px 31px;font-size:13.5px;
        background:rgba(0,0,0,.6);border:1px solid rgba(255,255,255,.35);
      }
      body.view-home .nf-search-toggle{position:absolute;left:0;width:34px}
      body.view-home .nf-results-grid{grid-template-columns:repeat(auto-fill,minmax(140px,1fr))}
      body.view-home .rail-heading .rail-heading-title{font-size:16px}
      body.view-home .rail-explore{font-size:12px}
    }

    /* ============================================================
       28. Netflix billboard + hover preview (values mirrored from
          the captured netflix.com skin: 56.25vw billboard, 36% info
          column, 14.7vw hero vignette, 77deg trailer vignette,
          28.125% card padding, 6px preview radius, #181818 info).
       ============================================================ */

    /* ---- 28a. billboard geometry ---- */
    body.view-home .hero{
      height:min(56.25vw,78vh);
      min-height:400px;
      max-height:760px;
      background:#000;
      overflow:hidden;
      isolation:isolate;
    }
    body.view-home .hero-media{z-index:1}
    body.view-home .hero-media .hero-img,
    body.view-home .hero-media .zd-trailer{
      position:absolute;inset:0;width:100%;height:100%;object-fit:cover;
    }
    /* still -> trailer cross-fade, using Netflix's own curve */
    body.view-home .hero.has-trailer .hero-img{opacity:0;transition:opacity .4s cubic-bezier(.665,.235,.265,.8)}
    body.view-home .hero.has-trailer .zd-trailer{opacity:1}

    /* Two separate vignette layers, exactly as Netflix splits them: a bottom fade
       that melts the billboard into the page, and a left wash that keeps the copy
       readable over the trailer. Keeping them apart avoids a hard seam. */
    body.view-home .hero-shade{
      background-image:linear-gradient(180deg,
        hsla(0,0%,8%,0) 0,
        hsla(0,0%,8%,.15) 15%,
        hsla(0,0%,8%,.35) 29%,
        hsla(0,0%,8%,.58) 44%,
        #141414 68%,
        #141414);
      inset:auto 0 -1px 0;height:min(14.7vw,190px);z-index:2;pointer-events:none;
    }
    body.view-home .hero-shade::after{
      content:"";position:absolute;left:0;right:26.09%;top:0;bottom:0;
      background:linear-gradient(77deg,rgba(0,0,0,.6),transparent 85%);
      opacity:1;transition:opacity .5s;
    }
    body.view-home .hero.video-playing .hero-shade::after{opacity:.71}
    body.view-home .hero:not(.has-trailer) .hero-shade::after{
      background:linear-gradient(77deg,rgba(0,0,0,.72),rgba(0,0,0,.3) 45%,transparent 85%);
    }

    /* ---- 28b. the info column: left 4%, 36% wide, bottom aligned ---- */
    body.view-home .hero-body{
      position:absolute;left:4%;bottom:6%;width:min(36%,560px);max-width:none;
      padding:0;z-index:4;display:flex;flex-direction:column;justify-content:flex-end;
      align-items:flex-start;
    }
    body.view-home .hero-eyebrow{margin-bottom:.9vw;font-size:clamp(10px,.82vw,13px)}
    body.view-home .hero-title{
      font-size:clamp(30px,3.5vw,62px);line-height:1.05;margin:0 0 1.2vw;font-weight:800;
    }
    body.view-home .hero-synopsis{
      font-size:clamp(13px,1.2vw,19px);line-height:1.45;margin:0;
      text-shadow:2px 2px 4px rgba(0,0,0,.45);max-width:none;-webkit-line-clamp:3;
    }
    body.view-home .hero-meta{
      margin:1vw 0 0;font-size:clamp(12px,1.05vw,16px);text-shadow:2px 2px 4px rgba(0,0,0,.45);
    }
    body.view-home .hero-actions{margin-top:1.5vw;gap:.9vw;flex-wrap:nowrap}
    body.view-home .hero-actions .btn{
      min-height:0;padding:.72em 1.6em;font-size:clamp(13px,1.15vw,18px);
      line-height:1;border-radius:2px;white-space:nowrap;
    }
    body.view-home .hero-actions .btn-play{background:#fff;color:#141414;font-weight:700}
    body.view-home .hero-actions .btn-play:hover{background:rgba(255,255,255,.78)}
    body.view-home .hero-actions .btn-ghost{
      background:rgba(42,42,42,.6);border:2px solid hsla(0,0%,100%,.5);color:#fff;font-weight:500;
    }
    body.view-home .hero-actions .btn-ghost:hover{background:#2a2a2a;border-color:#fff}

    /* ---- 28c2. filler blanks that close out a short row (see padRail) ----
       A 7-title row in a wide window used to stop dead and leave a void on
       the right; these inert blanks keep the strip reading as edge-to-edge.
       They vanish on touch, where a rail is swiped rather than scanned. */
    .rail-pad{display:contents}
    .rail-filler{
      flex:0 0 var(--nf-card);align-self:stretch;border-radius:4px;
      background:#1a1a1a;pointer-events:none;
    }
        .rail-mode-poster>.rail-pad>.rail-filler,
    .poster-rail:not(.rail-mode-landscape)>.rail-pad>.rail-filler{flex-basis:var(--nf-card-p)}
    /* a row with too few titles gets visible "coming soon" blanks instead of
       stopping short or showing a lone card */
    .rail-filler.is-soon{
      display:flex;align-items:center;justify-content:center;text-align:center;padding:8px;
      border:1px dashed rgba(255,255,255,.09);background:rgba(255,255,255,.02);
      color:#5c5c5c;font-size:11px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;
    }
    .rail-filler.is-soon:after{content:"Coming soon"}
    @media (hover:none){ .rail-filler{display:none} .rail-filler.is-soon{display:flex} }

    /* The hero trailer's controls come from ytTrailer(), which builds the same
       .zt-bar (play / mute / volume) the card and the hover preview use, so the
       hero needs no rule of its own here. */

    /* ---- 28c. YouTube trailer chrome: exactly play/pause, mute, volume ----
       The iframe is controls=0, so this bar is the entire interface. It sits
       over the bottom of the frame, fades out while the trailer plays, and
       returns on any pointer movement. */
    .zt-frame{
      position:absolute;inset:0;width:100%!important;height:100%!important;
      border:0;display:block;
    }
    .zt-bar{
      position:absolute;left:0;right:0;bottom:0;z-index:6;
      display:flex;align-items:center;gap:clamp(6px,1vw,14px);
      padding:clamp(10px,1.6vw,20px) clamp(12px,1.8vw,26px);
      background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,.72));
      opacity:1;transition:opacity .3s ease;
    }
    .zt-tape{position:absolute;inset:0}
    .is-idle > .zt-bar{opacity:0;pointer-events:none}
    .zt-btn{
      width:2.3rem;height:2.3rem;flex:0 0 auto;padding:0;border:0;border-radius:4px;
      background:none;color:#fff;cursor:pointer;opacity:.94;
      display:inline-flex;align-items:center;justify-content:center;
      transition:opacity .15s,transform .15s;
    }
    .zt-btn:hover{opacity:1;transform:scale(1.12)}
    .zt-btn:focus-visible{outline:2px solid #fff;outline-offset:2px}
    .zt-btn svg{width:1.35rem;height:1.35rem;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
    .zt-btn .ic-fill{fill:currentColor;stroke:none}
    .zt-vol{
      flex:0 1 5.4em;min-width:0;height:3px;accent-color:#fff;cursor:pointer;
      background:rgba(255,255,255,.35);
    }
    @media (max-width:600px){
      .zt-btn{width:2rem;height:2rem}
      .zt-btn svg{width:1.15rem;height:1.15rem}
      .zt-vol{flex-basis:3.6em}
    }
    @media (prefers-reduced-motion:reduce){
      .zt-bar,.zt-btn{transition-duration:.01ms!important}
    }

    /* ============================================================
       28e. Netflix-style detail card (OMDb)
       The captured reference card is ~885px wide with a 16:9 media region and a
       2fr/1fr metadata split on #181818. Those are treated as evidence of the
       intended scale, not as fixed pixels: the card is a percentage of the
       viewport with a max-width, collapses to one column on narrow screens and
       can never scroll sideways.
       ============================================================ */
    /* ============================================================
       28e. Netflix-style detail card.
       Every value below is taken from the captured reference
       (infocard example.htm): #181818 surfaces; a metadata grid of
       minmax(0,2fr) minmax(0,1fr) with a 2em column gap; 0 3em container
       padding; a 16px/26px synopsis; 14px/20px tag rows; a 24px/500 section
       header with 48px above and 20px below; a 12px/500 season dropdown
       aligned to the end; 20px season labels; episode rows separated by #404040
       with the current one on #333; and a 56.3925% story-art padding for the
       16:9 media region. Those are evidence of the intended scale, not fixed
       pixels: the card is a percentage of the viewport with a max-width, drops
       to one column on narrow screens, and can never scroll sideways.
       ============================================================ */
    .zamd-preview-overlay{
      display:none;position:fixed;inset:0;z-index:9000;
      background:rgba(0,0,0,.88);
      overflow-y:auto;-webkit-overflow-scrolling:touch;
      padding:clamp(12px,3vh,44px) clamp(10px,3vw,32px);
    }
    .zamd-preview-overlay.is-active{display:flex;align-items:flex-start;justify-content:center}
    .zmd-card{
      position:relative;width:min(96vw,885px);min-width:0;margin:auto;
      background:#181818;color:#fff;border-radius:6px;overflow:hidden;
      font-size:16px;box-shadow:0 24px 70px rgba(0,0,0,.7);
      animation:zamd-pop .32s var(--ease) both;
    }
    @keyframes zamd-pop{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
    /* loading state inside the card: shimmering plates where the metadata and
       plot will land, so the card never shows a black void or fake text */
    .zmd-skel-row{display:flex;align-items:center;gap:.8em;margin-bottom:1em}
    .zmd-skel-line{height:14px;border-radius:3px;flex:0 0 auto;background:#262628;animation:zamd-skel 1.4s ease-in-out infinite}
    .zmd-skel-line.w4{width:4.5em}.zmd-skel-line.w3{width:3.2em}.zmd-skel-line.w2{width:2.2em}
    .zmd-skel-plot{height:13px;border-radius:3px;background:#242426;margin-bottom:.7em;animation:zamd-skel 1.4s ease-in-out infinite}
    .zmd-skel-plot.l1{width:96%}.zmd-skel-plot.l2{width:88%}.zmd-skel-plot.l3{width:64%}
    .zmd-close{
      position:absolute;top:12px;right:12px;z-index:9;
      width:2.6rem;height:2.6rem;border:0;border-radius:50%;
      background:rgba(20,20,20,.7);color:#fff;cursor:pointer;
      display:inline-flex;align-items:center;justify-content:center;
    }
    .zmd-close svg{width:1.15rem;height:1.15rem;fill:none;stroke:currentColor;stroke-width:2.2;stroke-linecap:round}
    .zmd-close:hover{background:#333}
    .zmd-close:focus-visible{outline:2px solid #fff;outline-offset:2px}

    /* media: 16:9 by padding-top, never a fixed height */
    .zmd-player_container{background:#000}
    .zmd-media{position:relative;width:100%;padding-top:56.3925%;overflow:hidden}
    .zmd-media-bg,.zmd-media-yt{position:absolute;inset:0}
    .zmd-media-bg img{width:100%;height:100%;object-fit:cover;display:block}
    .zmd-media-shade{
      position:absolute;inset:0;z-index:4;pointer-events:none;
      background:linear-gradient(0deg,#181818 0%,rgba(24,24,24,.35) 34%,rgba(0,0,0,.15) 100%);
    }
    .zmd-title-wrap{position:absolute;left:0;right:0;bottom:0;z-index:5;padding:0 3em 1.6em}
    .zmd-brand{
      display:block;font-size:1rem;font-weight:800;letter-spacing:.16em;
      color:#e50914;text-transform:uppercase;margin-bottom:.5rem;
    }
    .zmd-title{
      margin:0 0 1.1rem;font-size:clamp(24px,3.1vw,40px);font-weight:800;line-height:1.06;
      letter-spacing:-.02em;text-shadow:0 2px 18px rgba(0,0,0,.6);max-width:22ch;
    }
    .zmd-play-row{display:flex;align-items:center;gap:.8rem;flex-wrap:wrap}
    .zmd-play{
      display:inline-flex;align-items:center;gap:.6rem;background:#fff;color:#000;
      text-decoration:none;font-size:1.05rem;font-weight:700;padding:.55rem 1.5rem;border-radius:3px;
    }
    .zmd-play svg{width:1.3rem;height:1.3rem;fill:currentColor;stroke:none}
    .zmd-play:hover{background:rgba(255,255,255,.82)}
    .zmd-round{
      width:2.5rem;height:2.5rem;border:2px solid rgba(255,255,255,.7);border-radius:50%;
      background:rgba(42,42,42,.55);color:#fff;cursor:pointer;
      display:inline-flex;align-items:center;justify-content:center;
      transition:border-color .15s,background .15s;
    }
    .zmd-round svg{width:1.25rem;height:1.25rem;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
    .zmd-round:hover{border-color:#fff;background:#2f2f2f}
    .zmd-round.is-on{border-color:#e50914;background:rgba(229,9,20,.22)}

    /* metadata: LEFT is deliberately about twice the width of RIGHT */
    .zmd-detail-modal-container{padding:0 3em}
    .zmd-detail{
      background:#181818;display:grid;position:relative;width:100%;
      grid-template-columns:minmax(0,2fr) minmax(0,1fr);
      column-gap:2em;align-items:start;padding:1.2em 0 1.6em;
    }
    .zmd-meta-left{display:flex;flex-direction:column;min-width:0}
    .zmd-meta-left > *{margin-bottom:.5em}
    .zmd-meta-row{
      display:flex;flex-wrap:wrap;align-items:center;gap:.45em .8em;margin-bottom:.9em;
    }
    .zmd-f{font-size:15px;color:#ddd}
    .zmd-chip{
      font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;
      border:1px solid #777;color:#ddd;border-radius:2px;padding:.15em .45em;
    }
    .zmd-rating{display:inline-flex;align-items:center;gap:.25em;font-size:15px;font-weight:700;color:#fff}
    .zmd-rating svg{width:1em;height:1em;fill:#f5c518;stroke:none}
    .zmd-of{color:#9a9a9a;font-weight:400;font-size:.8em}
    .zmd-votes{font-size:13px;color:#9a9a9a}
    .zmd-mat{
      display:inline-flex;align-items:center;justify-content:center;
      border:1px solid #999;color:#ddd;font-size:12px;font-weight:600;
      padding:.1em .45em;border-radius:2px;line-height:1.4;
    }
    .zmd-cap{display:inline-flex;align-items:center;gap:.3em;color:#bbb}
    .zmd-cap svg{width:1.05em;height:1.05em;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
    .zmd-cap-t{font-size:11px;letter-spacing:.04em}
    .zmd-plot{margin:0;max-width:62ch;font-size:16px;line-height:26px;color:#ddd}
    .zmd-note{margin:0;font-size:16px;line-height:26px;color:#9a9a9a}
    .zmd-meta-right{display:flex;flex-direction:column;gap:.6em;min-width:0}
    .zmd-field{display:flex;flex-direction:column;gap:.1em;font-size:14px;line-height:20px}
    .zmd-label{color:#777}
    .zmd-val{color:#ddd;overflow-wrap:anywhere}
    .zmd-mat.is-cw{border-color:#e50914;color:#ff6b74}
    .zmd-more{color:#ddd;cursor:pointer;font-style:italic}
    .zmd-more:hover{text-decoration:underline}

    /* sections */
    .zmd-sect{background:#181818;padding:0 3em 2em}
    .zmd-h{margin:48px 0 20px;font-size:24px;font-weight:500;color:#fff}
    .zmd-sect-head{display:grid;grid-template-columns:2fr 1fr;column-gap:2rem;align-items:baseline}
    .zmd-sect-head .zmd-h{margin:48px 0 20px}
    .zmd-dropdown{justify-self:end;align-self:center;position:relative;display:inline-flex;align-items:center}
    .zmd-select{
      appearance:none;-webkit-appearance:none;background:#333;color:#fff;
      border:1px solid #666;border-radius:3px;font-size:12px;font-weight:500;
      padding:.6em 2.2em .6em .9em;cursor:pointer;
    }
    .zmd-dropdown svg{
      position:absolute;right:.6em;width:1rem;height:1rem;pointer-events:none;
      fill:none;stroke:#fff;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;
    }
    .zmd-season-label{
      font-size:20px;font-weight:500;padding:2em 0 1em;
      display:flex;align-items:center;gap:.5em;
    }
    .zmd-ep-season[hidden]{display:none}

    .zmd-ep{
      display:grid;grid-template-columns:3.2em minmax(0,1fr) 2.2em;align-items:center;gap:16px;
      width:100%;text-align:left;border:0;border-bottom:1px solid #404040;border-radius:.25em;
      background:transparent;color:#ddd;font:inherit;padding:1em;cursor:pointer;
    }
    .zmd-ep:hover{background:#2a2a2a}
    .zmd-ep.is-cur{background:#333;color:#fff}
    .zmd-ep-n{font-size:1.5em;font-weight:500;color:#9a9a9a;text-align:center}
    .zmd-ep.is-cur .zmd-ep-n{color:#fff}
    .zmd-ep-main{display:flex;align-items:baseline;gap:1em;min-width:0}
    .zmd-ep-t{font-size:16px;font-weight:600;color:inherit;overflow-wrap:anywhere}
    .zmd-ep-d{margin-left:auto;font-size:13px;color:#9a9a9a;white-space:nowrap}
    .zmd-ep-go{display:inline-flex;justify-content:flex-end;color:inherit;opacity:.8}
    .zmd-ep-go svg{width:1.15rem;height:1.15rem;fill:currentColor;stroke:none}

    .about-wrapper{padding-bottom:2em}
    .about-wrapper .zmd-h{font-weight:400}
    .zmd-maturity{display:flex;align-items:center;gap:1em;margin-top:.5em;font-size:14px;line-height:20px}

    @media (max-width:820px){
      .zmd-card{width:100%}
      .zmd-detail{grid-template-columns:1fr;row-gap:1.1em}
      .zmd-detail-modal-container,.zmd-sect{padding-left:1.4em;padding-right:1.4em}
      .zmd-title-wrap{padding:0 1.4em 1.2em}
      .zmd-sect-head{grid-template-columns:1fr;row-gap:.4em}
      .zmd-dropdown{justify-self:start}
      .zmd-h{margin:32px 0 14px;font-size:20px}
      .zmd-season-label{font-size:17px;padding:1.4em 0 .8em}
      .zmd-ep{grid-template-columns:2.4em minmax(0,1fr);gap:12px}
      .zmd-ep-go{display:none}
    }
    @media (prefers-reduced-motion:reduce){
      .zmd-card,.zmd-close,.zmd-round{transition-duration:.01ms!important}
    }
    body.view-home .poster-media{background:#1a1a1a}
    body.view-home .poster-card.is-hp{z-index:30}

    /* ---- 28e. hover preview panel ---- */
    .zd-hp{
      position:fixed;z-index:8000;border-radius:6px;overflow:hidden;
      background:transparent;color:#fff;pointer-events:auto;
      box-shadow:0 10px 34px rgba(0,0,0,.62),0 2px 8px rgba(0,0,0,.5);
      opacity:0;transform:translateY(6px);
      transition:opacity .18s ease-out,transform .18s ease-out;
      will-change:transform;
    }
    .zd-hp.is-open{opacity:1;transform:none}
    .zd-hp-video{
      display:block;width:100%;aspect-ratio:16/9;background:#000;border:0;
      object-fit:cover;pointer-events:none;
    }
    .zd-hp-acts{
      position:static;display:flex;align-items:center;gap:8px;
      padding:12px 12px 4px;background:#181818;
    }
    .zd-hp-btn,.zd-hp-mute{
      width:2rem;height:2rem;min-width:2rem;border-radius:50%;
      display:inline-flex;align-items:center;justify-content:center;
      font-size:14px;cursor:pointer;border:2px solid hsla(0,0%,100%,.5);
      background:rgba(42,42,42,.6);color:#fff;padding:0;
      transition:background .18s,border-color .18s,transform .12s var(--ease);
    }
    .zd-hp-btn:hover,.zd-hp-mute:hover{background:#2a2a2a;border-color:#fff;transform:scale(1.06)}
    .zd-hp-btn.is-primary{background:#fff;color:#141414;border-color:#fff}
    .zd-hp-btn.is-primary:hover{background:#e6e6e6}
    .zd-hp-btn.is-expand{margin-left:auto}
    .zd-hp-btn .fa,.zd-hp-mute .fa{pointer-events:none}
    .zd-hp-still{background-size:cover;background-position:center;display:block;width:100%;aspect-ratio:16/9}
    .zd-hp-info{background:#181818;padding:2px 12px 12px}
    .zd-hp-meta{
      display:flex;align-items:center;flex-wrap:wrap;gap:6px;
      font-size:12.5px;color:#d2d2d2;
    }
    .zd-hp-meta span+span::before{content:"\2022";margin:0 6px 0 2px;opacity:.55}
    @media (hover:none){ .zd-hp{display:none} }

    /* ---- 28f. ambient: a soft wash of the hero art behind the nav ---- */
    body.view-home .site-header::after{
      content:"";position:absolute;left:0;right:0;top:100%;height:170px;z-index:-1;
      pointer-events:none;opacity:1;transition:opacity .35s var(--ease);
      background:radial-gradient(120% 100% at 50% 0,rgba(229,9,20,.16),rgba(20,20,20,0) 70%);
    }
    body.view-home.is-scrolled .site-header::after{opacity:0}
    body.view-home .site-header{isolation:isolate}

    /* ---- 28g. mobile billboard step-down ---- */
    @media (max-width:900px){
      body.view-home .hero{height:auto;min-height:min(64vh,520px);max-height:none;padding-bottom:0}
      body.view-home .hero-body{position:static;width:auto;padding:0 var(--gutter) 6%}
      body.view-home .hero-shade{right:0!important;height:auto;top:0;bottom:0;
        background-image:linear-gradient(180deg,hsla(0,0%,8%,.55) 0,hsla(0,0%,8%,.25) 40%,#141414 88%,#141414)!important}
      body.view-home .hero-actions{flex-wrap:wrap;gap:8px}
    }
    @media (max-width:560px){
      body.view-home .hero{min-height:min(58vh,440px)}
      body.view-home .hero-title{font-size:clamp(24px,7.6vw,34px);margin-bottom:10px}
      body.view-home .hero-actions .btn{padding:.66em 1.1em}
    }    /* ============================================================
       29. Page ground (#141414 + one subtle red wash at the very
          top), inset billboard, and card control stacking.
       ============================================================ */

    /* ---- 29a. Netflix ground: #141414 everywhere, red only at the top ---- */
    html[data-mode="dark"] body{background:#141414}
    html[data-mode="dark"] body::before{
      content:"";position:fixed;inset:0 0 auto 0;height:min(64vh,520px);z-index:0;pointer-events:none;
      background:linear-gradient(180deg,
        rgba(229,9,20,.11) 0%,
        rgba(229,9,20,.045) 26%,
        rgba(20,20,20,0) 66%);
    }
    /* the ground layer sits behind everything, and only the content columns
       need stacking. The header must stay position:fixed - promoting it here
       put it back into flow and shoved the billboard down by its own height. */
    .site-row,.site-footer{position:relative;z-index:1}
    .site-header{z-index:90}
    /* Netflix: the billboard starts at y=0 and the nav floats over it, turning
       solid only once the reader scrolls. */
    body.view-home .site-main{padding-top:0}
    /* the old per-component red washes produced visible colour bands */
    body.view-home .site-header::after{display:none}
    body.view-home .hero{background:#000}

    /* ---- 29b. the billboard is inset, not full-bleed ----
       The base sheet makes .hero full-bleed with width:100vw +
       margin-left:calc(50% - 50vw); both have to be undone or the inset is
       pushed straight back off the viewport. */
    body.view-home .hero,
    body.view-home .home-zone > .hero{width:auto;margin-left:auto;margin-right:auto}
    body.view-home .home-hero,
    body.view-home .home-zone > .hero{
      margin-inline:clamp(0px,1.4vw,20px);
      border-radius:10px;
      overflow:hidden;
      box-shadow:0 18px 50px rgba(0,0,0,.55);
    }
    body.view-home .home-hero{display:block}
    @media (max-width:700px){
      body.view-home .home-hero,
      body.view-home .home-zone > .hero{margin-inline:0;border-radius:0;box-shadow:none}
    }

    /* ---- 29c. the card's More Info (+) must sit above the hover-scaled art ----
       .poster-media scales to 1.055 with z-index:6 on hover, which was painting
       over the + and making it vanish the instant the pointer reached it. */
    body.view-home .poster-more{z-index:8}
    body.view-home .poster-title{position:relative;z-index:8}
    body.view-home .poster-card:hover .poster-more,
    body.view-home .poster-card:focus-within .poster-more{opacity:1;transform:none;pointer-events:auto}
    /* and stop the scaled art from eating the pointer over the button */
    body.view-home .poster-more:hover{transform:scale(1.08)}

    /* ---- 29d. comments hidden by the Blogger post setting ---- */
    .comments-closed-note{
      margin-top:16px;padding:12px 16px;border:1px solid var(--line);border-radius:4px;
      background:rgba(255,255,255,.03);color:var(--text-3);font-size:13.5px;
    }

    /* ---- 29e. Blogger static Pages must never render as posts ----
       A static Page always lives at /p/slug.html while a post always carries a
       /YYYY/MM/ date segment. Hiding them in CSS means they never flash, and the
       engine sweeps them out of any server-rendered grid as well. */
    .poster-card:has(> a[href*="/p/"]){display:none!important}
    .catalog > .poster-card:has(> a[href*="/p/"]),
    .poster-grid > .poster-card:has(> a[href*="/p/"]){display:none!important}
    /* safety net for anything that is not wrapped in .poster-card */
    a[href*="/p/"]:is(.index-link,.post-link){display:none!important}

    /* ============================================================
       30. Custom HTML5 player (Netflix chrome)
          Scrubber/track/head values mirrored from the captured netflix.com
          player: track #5b5b5 at .5em growing to 1em on hover, played #e50914,
          buffered hsla(0,0%,100%,.2), 2.3em round head scaling to 1.2.
       ============================================================ */
    .zd-player{
      position:relative;width:100%;height:100%;background:#000;overflow:hidden;
      color:#fff;font-family:var(--font);
      -webkit-tap-highlight-color:transparent;
      display:flex;flex-direction:column;
    }
    /* the video column: stage + chrome live together so opening comments can
       never stretch the control bar across the thread. flex:1 + min-height:0
       is what makes the comments bar sit UNDER the video and share the frame
       with it, instead of either overflowing or pushing the picture away. */
    .zd-player-main{position:relative;width:100%;flex:1 1 auto;min-height:0}
    .zd-player-video{
      position:absolute;inset:0;width:100%;height:100%;object-fit:contain;background:#000;
      display:block;
    }
    .zd-player.is-embed .zd-player-video{object-fit:cover}
    .zd-player-stage{position:absolute;inset:0}

    /* scrims */
    .zd-player-grad{position:absolute;left:0;right:0;pointer-events:none;opacity:0;transition:opacity .28s ease;z-index:2}
    .zd-player-grad.is-top{top:0;height:14%;background:linear-gradient(180deg,rgba(0,0,0,.55),rgba(0,0,0,0))}
    .zd-player-grad.is-bottom{bottom:0;height:34%;background:linear-gradient(180deg,rgba(0,0,0,0),rgba(0,0,0,.82))}
    .zd-player.is-chrome-off .zd-player-grad{opacity:0}
    .zd-player:not(.is-chrome-off) .zd-player-grad{opacity:1}

    /* big centred play / pause */
    .zd-player-big{
      position:absolute;left:50%;top:50%;transform:translate(-50%,-50%) scale(1);
      z-index:4;width:4.4rem;height:4.4rem;border-radius:50%;border:0;cursor:pointer;
      background:rgba(20,20,20,.62);color:#fff;font-size:1.7rem;
      display:inline-flex;align-items:center;justify-content:center;
      transition:opacity .22s ease,transform .22s cubic-bezier(.5,0,.1,1),background .18s;
    }
    .zd-player-big:hover{background:rgba(20,20,20,.82);transform:translate(-50%,-50%) scale(1.06)}
    .zd-player-big .fa-play{margin-left:3px}
    /* only show the big button while paused / idle */
    .zd-player.is-playing .zd-player-big{opacity:0;pointer-events:none}
    .zd-player.is-playing:hover .zd-player-big{opacity:.001}

    /* buffering spinner - three pulsing dots */
    .zd-player-spinner{
      position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);z-index:5;
      display:none;align-items:center;gap:.45rem;pointer-events:none;
    }
    .zd-player.is-buffering .zd-player-spinner{display:flex}
    .zd-player.is-buffering .zd-player-big{opacity:0}
    .zd-player-spinner span{
      width:.7rem;height:.7rem;border-radius:50%;background:#e50914;
      animation:zd-pl 1s ease-in-out infinite;
    }
    .zd-player-spinner span:nth-child(2){animation-delay:.16s}
    .zd-player-spinner span:nth-child(3){animation-delay:.32s}
    @keyframes zd-pl{0%,100%{opacity:.25;transform:translateY(0)}50%{opacity:1;transform:translateY(-5px)}}
    .zd-player.is-error .zd-player-spinner{display:none}

    /* ---- control bar ----
       Layout copied from the netflix.com player: a hairline scrubber pinned to
       the top edge of the chrome with the remaining time sitting at its right
       end, then one row split into play/volume on the left, the episode title
       dead centre, and the secondary actions on the right. Icons are inline
       thin-stroke SVGs rather than the chunky Font Awesome glyphs. */
    .zd-player-chrome{
      position:absolute;left:0;right:0;bottom:0;z-index:6;
      padding:0 clamp(10px,1.6vw,26px) clamp(8px,1.1vw,16px);
      display:flex;flex-direction:column;
      opacity:1;transform:translateY(0);
      transition:opacity .28s ease,transform .28s cubic-bezier(.5,0,.1,1);
    }
    .zd-player.is-chrome-off .zd-player-chrome{opacity:0;transform:translateY(8px);pointer-events:none}

    /* scrubber: full-bleed line + right-aligned remaining time */
    .zd-player-scrubwrap{
      display:flex;align-items:center;gap:14px;
      margin:0 calc(-1 * clamp(10px,1.6vw,26px));
      padding:0 clamp(10px,1.6vw,26px);
    }
    .zd-player-scrub{
      position:relative;flex:1 1 auto;height:2.4em;display:flex;align-items:center;
      cursor:pointer;touch-action:none;outline:none;
    }
    .zd-player-scrub:focus-visible .zd-player-head{box-shadow:0 0 0 3px #fff}
    .zd-player-track{
      position:relative;width:100%;height:3px;background:#5b5b5b;border-radius:2px;
      transition:height .18s ease;
    }
    .zd-player-scrub:hover .zd-player-track,
    .zd-player.is-scrubbing .zd-player-track{height:5px}
    .zd-player-buffered{
      position:absolute;left:0;top:0;bottom:0;width:0;background:hsla(0,0%,100%,.28);border-radius:2px;
    }
    .zd-player-played{
      position:absolute;left:0;top:0;bottom:0;width:0;background:#e50914;border-radius:2px;
    }
    /* Netflix always shows a small head, growing on hover */
    .zd-player-head{
      position:absolute;top:50%;left:0;width:11px;height:11px;margin:-5.5px 0 0 -5.5px;
      background:#e50914;border-radius:50%;transform:scale(1);
      transition:transform .18s ease;pointer-events:none;
    }
    .zd-player-scrub:hover .zd-player-head,
    .zd-player.is-scrubbing .zd-player-head{transform:scale(1.5)}
    .zd-player-tip{
      position:absolute;bottom:2.2em;transform:translateX(-50%);
      padding:3px 8px;border-radius:3px;background:rgba(0,0,0,.82);
      font-size:12px;font-weight:600;white-space:nowrap;opacity:0;pointer-events:none;
      transition:opacity .15s;
    }
    .zd-player-scrub:hover .zd-player-tip{opacity:1}
    .zd-remain{
      flex:0 0 auto;font-size:.82rem;font-weight:600;color:#fff;opacity:.92;
      font-variant-numeric:tabular-nums;white-space:nowrap;
    }
    .zd-player.is-embed .zd-player-scrubwrap,
    .zd-player.is-embed .zd-volume,
    .zd-player.is-embed .is-back10,
    .zd-player.is-embed .is-fwd10,
    .zd-player.is-embed .is-next,
    .zd-player.is-embed .is-speed,
    .zd-player.is-embed .zd-player-eps,
    .zd-player.is-embed .zd-player-title{display:none}

    /* button row: left / centre / right */
    .zd-player-row{
      display:flex;align-items:center;gap:clamp(4px,.8vw,14px);margin-top:2px;
    }
    .zd-player-group{display:flex;align-items:center;gap:clamp(2px,.55vw,10px)}
    .zd-player-group.is-left{flex:0 0 auto}
    .zd-player-group.is-right{flex:0 0 auto;margin-left:auto}
    .zd-player-title{
      flex:1 1 auto;min-width:0;text-align:center;
      font-size:.86rem;font-weight:700;color:#fff;
      white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
      padding:0 clamp(4px,1vw,18px);opacity:.95;
    }
    .zd-pbtn{
      width:2.6rem;height:2.6rem;border:0;background:none;color:#fff;font-size:1rem;
      display:inline-flex;align-items:center;justify-content:center;cursor:pointer;
      border-radius:4px;padding:0;opacity:.92;
      transition:opacity .15s,transform .15s;
    }
    .zd-pbtn:hover{opacity:1;transform:scale(1.14)}
    .zd-pbtn:focus-visible{outline:2px solid #fff;outline-offset:2px}
    .zd-pbtn[hidden]{display:none}
    .zd-pbtn svg{width:1.6rem;height:1.6rem;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
    .zd-pbtn.is-play svg,.zd-pbtn.is-big-play svg{width:2rem;height:2rem}
    .zd-pbtn.is-play .ic-fill,.zd-pbtn.is-big-play .ic-fill{fill:currentColor;stroke:none}
    .zd-pbtn.is-skip svg{width:1.95rem;height:1.95rem}
    .zd-pbtn.is-on{color:#e50914;opacity:1}
    .zd-time{font-size:.85rem;color:#fff;opacity:.9;white-space:nowrap;display:inline-flex;gap:4px}
    .zd-time i{opacity:.6;font-style:normal}
    .zd-time .zd-dur{opacity:.7}

    /* volume */
    .zd-volume{display:flex;align-items:center}
    .zd-vol{
      width:0;opacity:0;transition:width .2s ease,opacity .2s ease,height .2s ease;
      height:3px;cursor:pointer;accent-color:#fff;
    }
    .zd-volume:hover .zd-vol,.zd-vol:focus{width:5.2em;opacity:1}

    /* ---- playback speed panel (Netflix: rail of ticks + labels) ---- */
    .zd-speed{position:relative}
    .zd-speed-menu{
      position:absolute;right:0;bottom:calc(100% + 14px);z-index:8;
      background:#1f1f1f;border:1px solid #5b5b5b;border-radius:2px;
      padding:16px 18px 12px;min-width:270px;box-shadow:0 10px 30px rgba(0,0,0,.7);
    }
    .zd-speed-menu[hidden]{display:none}
    .zd-speed-title{
      display:block;font-size:1.05rem;font-weight:700;color:#fff;margin-bottom:18px;
    }
    .zd-speed-rail{
      position:relative;display:flex;justify-content:space-between;align-items:center;
      margin:0 6px;
    }
    .zd-speed-rail-line{
      position:absolute;left:0;right:0;top:50%;height:2px;margin-top:-1px;
      background:#8f8f8f;
    }
    .zd-speed-rail button{
      position:relative;z-index:1;width:14px;height:14px;padding:0;border:0;border-radius:50%;
      background:#fff;cursor:pointer;transition:box-shadow .15s,transform .15s;
    }
    .zd-speed-rail button:hover{transform:scale(1.15)}
    .zd-speed-rail button.is-on{box-shadow:0 0 0 4px #fff,0 0 0 6px #1f1f1f}
    .zd-speed-legend{
      display:flex;justify-content:space-between;margin:10px 0 0;
      font-size:.72rem;color:#c9c9c9;white-space:nowrap;
    }
    .zd-speed-legend span{flex:0 0 auto}
    .zd-speed-legend .is-on{color:#fff;font-weight:700}

    /* ---- episodes panel: mirrors the captured detail-card episode list ----
       A centred card above the control bar: "Episodes" with the season
       dropdown on the right, then numbered rows separated by #404040 with the
       current row on #333 and a red progress line - the exact pattern of the
       reference screenshot, not a side drawer. */
    .zd-player-eps{
      position:absolute;left:50%;bottom:clamp(64px,9vh,86px);z-index:9;
      transform:translateX(-50%) translateY(12px);
      width:min(885px,94%);max-height:min(62vh,520px);
      display:flex;flex-direction:column;
      background:rgba(22,22,22,.98);border-radius:6px;
      box-shadow:0 24px 70px rgba(0,0,0,.72);
      opacity:0;visibility:hidden;pointer-events:none;
      transition:opacity .22s var(--ease),transform .22s var(--ease),visibility .22s;
      overflow:hidden;
    }
    .zd-player.is-eps-open .zd-player-eps{
      opacity:1;visibility:visible;pointer-events:auto;
      transform:translateX(-50%);
    }
    .zd-eps-head{
      flex:0 0 auto;display:grid;grid-template-columns:1fr auto;align-items:center;
      gap:1rem;padding:1em 1.4em .5em;
    }
    .zd-eps-head b{font-size:1.4rem;font-weight:500;color:#fff}
    .zd-eps-select{
      appearance:none;-webkit-appearance:none;background:#333;color:#fff;
      border:1px solid #666;border-radius:3px;font-size:12px;font-weight:500;
      padding:.6em 2.2em .6em .9em;cursor:pointer;
    }
    .zd-eps-body{flex:1 1 auto;min-height:0;overflow-y:auto;-webkit-overflow-scrolling:touch;padding:0 1.4em 1em}
    .zd-eps-season{font-size:1.15rem;font-weight:500;padding:1.1em 0 .4em;color:#fff;display:flex;align-items:center;gap:.5em}
    .zd-eps-row{
      display:grid;grid-template-columns:3.2em minmax(0,1fr) 2.2em;align-items:center;gap:16px;
      width:100%;text-align:left;border:0;border-bottom:1px solid #404040;border-radius:.25em;
      background:transparent;color:#ddd;font:inherit;padding:1em .6em;cursor:pointer;
      transition:background .15s;
    }
    .zd-eps-row:hover{background:#2a2a2a}
    .zd-eps-row.is-cur{background:#333;color:#fff}
    .zd-eps-n{font-size:1.5em;font-weight:500;color:#9a9a9a;text-align:center}
    .zd-eps-row.is-cur .zd-eps-n{color:#e50914}
    .zd-eps-main{display:block;min-width:0}
    .zd-eps-t{font-size:16px;font-weight:600;color:inherit;overflow-wrap:anywhere;display:block}
    .zd-eps-prog{display:block;height:3px;border-radius:2px;background:rgba(255,255,255,.22);margin-top:.5em;overflow:hidden;max-width:240px}
    .zd-eps-prog i{display:block;height:100%;width:0;background:#e50914;border-radius:2px}
    .zd-eps-go{display:inline-flex;justify-content:flex-end;color:inherit;opacity:.8}
    .zd-eps-go svg{width:1.15rem;height:1.15rem;fill:currentColor;stroke:none}

    /* ---- comments: a real section under the watch frame ----
       Disqus renders in the page flow below the player and never inside or
       over the video. The control-bar button leaves the fullscreen watch view
       (body.zd-show-comments): the frame drops to 16:9, the page unlocks, and
       the thread sits below the player. Pressing again returns to fullscreen. */
    body.view-post.zd-show-comments{overflow:auto!important}
    body.view-post.zd-show-comments .detail-hero,
    body.view-post.zd-show-comments .site-main,
    body.view-post.zd-show-comments .site-row,
    body.view-post.zd-show-comments .layout,
    body.view-post.zd-show-comments .detail-entry{
      height:auto;max-height:none;overflow:visible;
    }
    body.view-post.zd-show-comments .detail-player{
      width:100%;height:auto;aspect-ratio:16/9;max-height:min(78vh,780px);
    }
    body.view-post.zd-show-comments .detail-head{display:none!important}
    body.view-post.zd-show-comments .detail-wrap{display:block!important}
    /* only the thread: no title block, no synopsis, no leftover post body */
    body.view-post.zd-show-comments .detail-main > :not(.entry-comments){display:none!important}
    body.view-post.zd-show-comments .entry-comments{margin-top:10px}
    body.view-post #comments-panel,
    body.view-post .entry-comments{display:none!important}
    body.view-post.zd-show-comments #comments-panel,
    body.view-post.zd-show-comments .entry-comments{display:block!important}
    body.view-post.zd-show-comments #comments-panel{
      max-width:1100px;margin:30px auto 0;padding:0 var(--gutter);
    }
    body.view-post.zd-show-comments #comments-panel .title{font-size:18px;margin:0 0 16px}
    body.view-post.zd-show-comments #disqus_thread iframe{max-width:100%!important;width:100%!important}

    /* inline players inside the post body */
    .post-body .zd-player{
      width:100%;aspect-ratio:16/9;height:auto;border-radius:4px;margin:0 0 24px;
      box-shadow:0 8px 26px rgba(0,0,0,.5);
    }
    .post-body .zd-player-video{position:absolute;inset:0}

    /* the hero player sits in the watch frame */
    .detail-player .zd-player{border-radius:0}

    /* ---- responsive ----
       The comments bar keeps pushing the video up instead of covering it: an
       overlay here is what made the thread swallow the picture on phones. */
    @media (max-width:760px){
      .zd-player-big{width:3.4rem;height:3.4rem;font-size:1.3rem}
      .zd-pbtn{width:2.35rem;height:2.35rem}
      .zd-pbtn svg{width:1.42rem;height:1.42rem}
      .zd-pbtn.is-play svg,.zd-pbtn.is-big-play svg{width:1.8rem;height:1.8rem}
      .zd-remain{font-size:.76rem}
      .zd-volume{display:none}
      .zd-player-title{font-size:.76rem}
      .zd-player-eps{bottom:56px;max-height:72vh}
    }
    @media (max-width:520px){
      /* the centre title is the first thing to go when space runs out */
      .zd-player-title{display:none}
      .zd-player.is-speed-open .zd-player-title{display:none}
      .zd-speed-menu{min-width:0;width:min(84vw,300px)}
    }
    @media (max-height:520px){
      .zd-player-eps{max-height:78vh}
    }
    @media (prefers-reduced-motion:reduce){
      .zd-player *{transition-duration:.01ms!important;animation-duration:.01ms!important}
    }

    /* ============================================================
       31. Post page = a full-screen Netflix watch view.
          No site header, no footer, no sidebar, no share bar, no
          related rail - just the player filling the viewport and a
          back button in the top left. The post body and comments
          stay below the fold so they remain readable/indexable.
       ============================================================ */
    body.view-post{background:#000}
    body.view-post .site-header,
    body.view-post .site-footer,
    body.view-post .site-sidebar,
    body.view-post .blog-pager,
    body.view-post .post-share,
    body.view-post .about-author,
    body.view-post .zd-post-meta,
    body.view-post .post-nav,
    body.view-post #related-wrap,
    body.view-post .sora-related,
    body.view-post .home-ad,
    body.view-post .drawer,
    body.view-post .backdrop,
    body.view-post #back-top,
    body.view-post .zamd-cookie-bar{display:none!important}

    body.view-post .site-main{padding-top:0}
    body.view-post .site-row{gap:0}
    /* the red top wash belongs to the browse page, not the watch page */
    html[data-mode="dark"] body.view-post::before{display:none}
    /* the player runs edge to edge: undo the content gutter for the hero only */
    body.view-post .site-main>.layout{padding-inline:0;max-width:none}
    body.view-post .detail-entry{margin:0;padding:0;border:0}
    body.view-post .detail-hero{
      height:100vh;height:100dvh;max-height:none;margin:0;background:#000;
    }
    body.view-post .detail-player{
      width:100%;height:100%;max-height:none;aspect-ratio:auto;
      border-radius:0;box-shadow:none;background:#000;
    }
    body.view-post .detail-player-frame{position:absolute;inset:0;width:100%;height:100%}
    body.view-post .detail-player-frame .zd-player{border-radius:0}
    /* Nothing but the player: the title block and the post body are off the
       page for good. The comment section is only hidden until the reader presses
       the player's comment button - the engine then sets body.zd-show-comments,
       the fullscreen lock releases, and the existing thread section shows in the
       page flow directly under the video. */
    body.view-post .detail-head,
    body.view-post .detail-wrap,
    body.view-post .detail-episodes{display:none!important}
    /* the thread is hidden in the post body on a watch page, and shown again in
       the one place it is actually docked: the bar under the video. Structural,
       so it does not depend on a body class being toggled at the right moment. */
    body.view-post #comments-panel{display:none!important}
    body.view-post .entry-comments,
    body.view-post #comments{display:none!important}
    body.view-post .detail-hero,
    body.view-post .site-main,
    body.view-post .site-row,
    body.view-post .layout,
    body.view-post .detail-entry{height:100dvh;max-height:100dvh;overflow:hidden}

    /* back button, top left, the only chrome on the watch page */
    .zamd-gate{
      position:fixed;inset:0;z-index:12000;display:none;
      background:#0b0b0b;align-items:center;justify-content:center;
    }
    .zamd-gate.is-on{display:flex}
    .zamd-gate-inner{display:flex;flex-direction:column;align-items:center;gap:1.1rem}
    .zamd-gate-mark{
      font-size:1rem;font-weight:800;letter-spacing:.16em;text-transform:uppercase;
      color:#e50914;
    }
    .zamd-gate-bar{
      display:block;width:180px;height:3px;border-radius:2px;overflow:hidden;
      background:rgba(255,255,255,.14);
    }
    .zamd-gate-bar i{
      display:block;width:40%;height:100%;border-radius:2px;background:#e50914;
      animation:zamd-gate-slide 1.1s ease-in-out infinite;
    }
    @keyframes zamd-gate-slide{
      0%{transform:translateX(-100%)}
      100%{transform:translateX(250%)}
    }
    @media (prefers-reduced-motion:reduce){
      .zamd-gate-bar i{animation:none;width:100%}
    }

    .zamd-back{
      position:fixed;left:16px;top:16px;z-index:11500;
      display:inline-flex;align-items:center;gap:8px;
      padding:9px 16px 9px 13px;border:0;border-radius:4px;cursor:pointer;
      background:rgba(20,20,20,.62);color:#fff;font-size:15px;font-weight:500;
      transition:background .18s,transform .15s var(--ease);
    }
    .zamd-back:hover{background:rgba(20,20,20,.88)}
    .zamd-back:active{transform:scale(.97)}
    .zamd-back .fa{font-size:19px;line-height:1}
    @media (max-width:560px){
      .zamd-back span{display:none}
      .zamd-back{left:12px;top:12px;padding:10px 12px}
    }
    /* a post with no video should not be a black void */
    body.view-post .detail-hero.is-empty{height:auto;padding:clamp(40px,8vw,90px) 0}

    /* ============================================================
       32. Mobile app shell — the Netflix phone layout.
       The reference app screenshots show NO sidebar: a top bar, a
       horizontally scrolling chip row, poster-art rails, and a floating
       bottom tab bar (Home / Search / My List). The drawer disappears
       entirely below the desktop breakpoint and the tab bar takes over.
       ============================================================ */
    .zd-tabbar{
      display:none;position:fixed;left:50%;bottom:14px;z-index:190;
      transform:translateX(-50%);
      align-items:stretch;gap:4px;padding:8px 10px;
      background:rgba(24,24,24,.92);
      -webkit-backdrop-filter:blur(18px);backdrop-filter:blur(18px);
      border:1px solid rgba(255,255,255,.1);border-radius:999px;
      box-shadow:0 14px 44px rgba(0,0,0,.6);
    }
    .zd-tab{
      display:inline-flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;
      min-width:78px;padding:8px 12px;border-radius:999px;border:0;background:none;
      color:#b3b3b3;font-size:11.5px;font-weight:600;letter-spacing:.02em;cursor:pointer;
      transition:background .18s,color .18s;text-decoration:none;
    }
    .zd-tab .fa{font-size:19px;line-height:1}
    .zd-tab:hover{color:#fff}
    .zd-tab.is-active{background:#fff;color:#141414}
    .zd-tab.is-active .fa{color:#141414}
    @media (max-width:1099px){
      /* the app's header is solid; the billboard starts below it */
      .site-header{background:#141414!important}
      body.view-home .site-header{background:#141414!important}
      body.view-home .site-main{padding-top:var(--nf-head)}
      /* the drawer is gone; the tab bar is the navigation */
      .hamburger{display:none!important}
      .drawer,.backdrop{display:none!important}
      .zd-tabbar{display:inline-flex}
      body{padding-bottom:86px}
      body.view-post{padding-bottom:0}
      /* search results are the page itself, so the sheet needs no chrome */
      /* rails read as the app's poster rows: 2:3 art, no text underneath */
      body.view-home .rail-card-landscape,
      body.view-home .rail-mode-landscape>.rail-card-landscape,
      body.view-home .poster-rail .rail-card-landscape{flex-basis:clamp(116px,30vw,148px);min-width:clamp(116px,30vw,148px);max-width:clamp(116px,30vw,148px)}
      body.view-home .rail .rail-card-landscape .poster-media{aspect-ratio:2/3}
      body.view-home .rail .poster-title,
      body.view-home .rail .poster-sub{display:none}
      body.view-home .rail{gap:8px}
      /* the billboard reads as the app's rounded hero card */
      body.view-home .home-hero,
      body.view-home .home-zone>.hero{
        margin-inline:10px;border-radius:14px;overflow:hidden;
        min-height:min(72vh,560px);box-shadow:0 18px 50px rgba(0,0,0,.55);
      }
      body.view-home .hero-body{padding:0 18px 20px}
      /* genre chips sit under the header, scrolling sideways, app-style */
      .home-chips-top{display:block;margin:10px 0 14px}
      .home-chips-top .rail-heading{display:none}
      .home-chips-top .genre-chips{display:flex;flex-wrap:nowrap;gap:8px;overflow-x:auto;padding:0 var(--gutter);scrollbar-width:none;-webkit-overflow-scrolling:touch}
      body.view-home .hero-body{padding-bottom:118px}
      .home-chips-top .genre-chips::-webkit-scrollbar{display:none}
      .home-chips-top .genre-chips .chip{
        flex:0 0 auto;background:rgba(255,255,255,.1);border:0;border-radius:999px;
        color:#fff;font-size:14px;font-weight:600;padding:12px 20px;
      }
      .home-chips-top .genre-chips .chip.is-active{background:#fff;color:#141414}
    }
    @media (min-width:1100px){
      .home-chips-top{display:none}
    }
    /* the watch page is fullscreen chrome like the app's player */
    body.view-post .zd-tabbar{display:none}

head.b:template-skin:
/*------ZaminDrive Layout Editor Mode ------*/
body#layout{width:900px;max-width:100%;padding:90px 5px 5px;position:relative;margin:0;background:#f5f5f5}
body#layout > .layout{display:block;max-width:100%;padding:0}
body#layout div.section{margin:0 4px 10px!important;padding:14px!important;border-radius:6px;border:1px solid #d0d0d0;background:#fff}
body#layout .section h4{font-size:13px;margin:0 0 4px;color:#333;font-weight:600}
body#layout .layout-widget-description{display:none}

/* Section descriptions — one per real b:section id */
    body#layout #zamd-settings-section > h4::after{content:' - Runtime config: comments, views, search, bookmarks, PWA';color:#888;font-weight:400}
    body#layout #main-logo > h4::after{content:' - Site logo or text title (Header widget)';color:#888;font-weight:400}
    body#layout #top-bar-nav > h4::after{content:' - Top bar links (secondary navigation)';color:#888;font-weight:400}
    body#layout #top-bar-social > h4::after{content:' - Social icon links in top bar';color:#888;font-weight:400}
    body#layout #main-menu > h4::after{content:' - Main navigation (use _ prefix for dropdown groups)';color:#888;font-weight:400}
    body#layout #home-hero > h4::after{content:' - FeaturedPost widget: hero spotlight';color:#888;font-weight:400}
    body#layout #home-trending > h4::after{content:' - PopularPosts widget: trending rail (set time range inside the widget)';color:#888;font-weight:400}
    body#layout #menu-cat > h4::after{content:' - Genre/category menu + homepage genre chips (LinkList)';color:#888;font-weight:400}
    body#layout #home-rails > h4::after{content:' - Content rails: HTML widget title = rail heading, content = $source=recent|label $label=X $sort=newest|oldest $period=7|30|all $count=12 $card=poster|landscape';color:#888;font-weight:400}
    body#layout #main > h4::after{content:' - Blog widget: core post engine (homepage grid, post, archive, search)';color:#888;font-weight:400}
    body#layout #sidebar-home > h4::after{content:' - Homepage sidebar: Label, PopularPosts, or HTML widgets';color:#888;font-weight:400}
    body#layout #sidebar-post > h4::after{content:' - Post-page sidebar widgets';color:#888;font-weight:400}
    body#layout #sidebar-r1 > h4::after{content:' - Footer column widgets';color:#888;font-weight:400}
    body#layout #home-ad-top > h4::after{content:' - Ad code above homepage content';color:#888;font-weight:400}
    body#layout #home-ad-footer > h4::after{content:' - Ad code below homepage content';color:#888;font-weight:400}
    body#layout #menu-footer > h4::after{content:' - Footer navigation links';color:#888;font-weight:400}
    body#layout #social-widget > h4::after{content:' - Follow-us social icon links';color:#888;font-weight:400}
    body#layout #hidden-widgets > h4::after{content:' - Retired widgets (kept for data, never shown)';color:#888;font-weight:400}

/* Settings panel visible in editor */
body#layout .zamd-settings{display:block!important;overflow:hidden}

/* Header static in editor */
body#layout .site-header{position:static;height:auto;display:block}
body#layout .header-inner{display:block}
body#layout .menu-source{display:block!important}

/* Hide non-essential elements in editor */
body#layout .primary-nav,body#layout .header-tools,body#layout #nav-toggle,body#layout .genre-nav,body#layout .rail,body#layout .rail-wrap,body#layout .poster-grid,body#layout .sfx-home-zone,body#layout .nf-search,body#layout .drawer,body#layout .backdrop,body#layout #back-top,body#layout .zamd-preview-overlay,body#layout .zamd-bookmarks-panel,body#layout .zamd-cookie-bar,body#layout .rail-btn,body#layout .site-main>.layout>.content-main,body#layout .site-sidebar{display:none!important}

/* Show hidden widgets in editor */
body#layout .hidden-widgets{display:block!important;visibility:visible!important}
body#layout .site-footer{position:static}
body#layout .home-zone{display:block!important}

body.script:
  //
  (function(){
  'use strict';
  var doc = document;
  function $(s, c){ return (c || doc).querySelector(s); }
  function $$(s, c){ return Array.prototype.slice.call((c || doc).querySelectorAll(s)); }
  var body = doc.body;
  var C = window.__zamd = window.__zamd || {};
  for (var cfgk in C){ if (typeof C[cfgk] === 'string') C[cfgk] = C[cfgk].trim(); }
  window.__zamd_blog = window.__zamd_blog || doc.documentElement.getAttribute('data-blog-url') || (location.protocol === 'http:' || location.protocol === 'https:' ? location.origin + '/' : './');
  var BLOG = window.__zamd_blog;
  if (BLOG.charAt(BLOG.length - 1) !== '/') BLOG += '/';
  window.__zamd_blog = BLOG;
  window.__sor_cbi = 0;

  /* ---------------- JSONP feed helper ---------------- */
  function feed(url, cb){
    var cacheKey = 'zamdfeed:' + url, cachedJson = null;
    try {
      var rawCache = sessionStorage.getItem(cacheKey);
      if (rawCache){ var parsedCache = JSON.parse(rawCache); if (parsedCache && parsedCache.d && ((new Date()).getTime() - parsedCache.t) < 600000){ cachedJson = parsedCache.d; } }
    } catch(e){}
    if (cachedJson){ var hitJson = cachedJson; setTimeout(function(){ try { cb(hitJson); } catch(e){} }, 0); return; }
    window.__sor_cbi += 1;
    var name = '__zamdcb_' + window.__sor_cbi;
    var settled = 0, timer = 0, s = null;
    function cleanupFeed(){
      if (timer){ try { clearTimeout(timer); } catch(e){} timer = 0; }
      try { delete window[name]; } catch(e){ window[name] = undefined; }
      if (s && s.parentNode){ try { s.parentNode.removeChild(s); } catch(e){} }
    }
    function settle(json, store){
      if (settled) return;
      settled = 1;
      if (store){ try { sessionStorage.setItem(cacheKey, JSON.stringify({ t: (new Date()).getTime(), d: json })); } catch(e){} }
      cleanupFeed();
      try { cb(json); } catch(e){}
    }
    window[name] = function(json){ settle(json, 1); };
    s = doc.createElement('script');
    s.src = url + (url.indexOf('?') > -1 ? '&' : '?') + 'callback=' + name;
    s.onerror = function(){ settle({ feed: { entry: [] } }, 0); };
    timer = setTimeout(function(){ settle({ feed: { entry: [] } }, 0); }, 8000);
    (doc.head || doc.getElementsByTagName('head')[0]).appendChild(s);
  }
  function feedUrl(params){
    var base = BLOG + 'feeds/posts/default?alt=json-in-script';
    if (params.label) base += '&q=' + encodeURIComponent('label:' + params.label);
    if (params.max) base += '&max-results=' + params.max;
    if (params.q) base += '&q=' + encodeURIComponent(params.q);
    if (params.orderby) base += '&orderby=' + params.orderby;
    if (params.min) base += '&published-min=' + encodeURIComponent(params.min);
    if (params.start) base += '&start-index=' + params.start;
    return base;
  }
  function flink(e){
    var l = (e && e.link) || [];
    for (var i = 0; i < l.length; i++){ if (l[i].rel === 'alternate' && l[i].href) return l[i].href; }
    return '';
  }
  /* Blogger post permalinks always carry a /YYYY/MM/ path segment; static pages
     resolve to /p/slug.html or /slug.html. Entries without a date path are Pages
     and must never reach rails, search results, previews or My List. */
  function isPostUrl(u){
    u = String(u || '');
    if (!u) return false;
    if (/[?&]m=1(&|$)/.test(u)) return true;
    return /\/\d{4}\/\d{2}(\/|$)/.test(u);
  }
  function fthumb(e, size){
    var t = e && e.media$thumbnail && e.media$thumbnail.url;
    if (t) return t.replace('/s72-c/', size);
    return 'https://4.bp.blogspot.com/-O3EpVMWcoKw/WxY6-6I4--I/AAAAAAAAB2s/KzC0FqUQtkMdw7VzT6oOR_8vbZO6EJc-ACK4BGAYYCw/w480/nth.png';
  }
  function flabels(e){
    var c = e && e.category || [];
    return c.map(function(x){ return x.term; });
  }
  function fyear(p){
    var d = new Date(p);
    return isNaN(d.getTime()) ? '' : String(d.getFullYear());
  }
  function fdate(p){
    var d = new Date(p);
    if (isNaN(d.getTime())) return '';
    return d.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
  }
  function stripHtml(html){
    var d = doc.createElement('div');
    d.innerHTML = html || '';
    return (d.textContent || '').replace(/\s+/g, ' ').trim();
  }
  function fsnippet(e, len){
    var c = e && e.content && e.content.$t || (e && e.summary && e.summary.$t) || '';
    var t = stripShortcodes(stripHtml(c)).replace(/\s+/g, ' ').trim();
    if (t.length > len) t = t.slice(0, len) + '\u2026';
    return t;
  }
  /* ------------------------------------------------------------------
     Release-metadata scrubber for post titles.

     This blog stores technical release info inside the post TITLE, e.g.
       Peaky Blinders (Season 5) BluRay [English DD5.1] 1080p 720p & 480p
         [x264/10Bit-HEVC] | NetFlix [ALL Episodes]
     and the reader should only ever see
       Peaky Blinders (Season 5) BluRay [English]

     Release names (BluRay / Blu-Ray / WEB-DL / WEB-HDRip / WEBRip / HDCAM)
     and the language list inside [...] are KEPT - only audio channels,
     resolutions, encoders, bit depth, subs, the pipe tail and a bare HD are
     removed. Applied to every title the reader can see.
  */
  /* ------------------------------------------------------------------
     Entertainment-name normaliser.

     cleanTitle() is deliberately conservative: it removes technical noise but
     KEEPS release names and the author's punctuation, because that string is
     what the reader sees and what the browser title and previews use.

     This is the other, far more aggressive pass, used only for
       - the OMDb ?t= query, which must be "Peaky Blinders", not
         "Peaky Blinders (Season 5) BluRay [English]"
       - the player's episode label, "Peaky Blinders S1 E1: Pilot"
     So it additionally drops the season marker, a standalone year, release
     names and marketing words. It still refuses to guess: no splitting on
     spaces, no stripping of ordinary words, and anything it cannot make sense
     of falls back to the cleanTitle() output rather than to nothing.
  */
  function entertainmentName(raw){
    var t = cleanTitle(raw);
    if (!t) return { title: '', season: 0, clean: '' };
    var season = 0, m, i;
    var seasonPats = [
      /\(\s*season\s*(\d{1,2})\s*\)/i,
      /\bseason\s*(\d{1,2})\b/i,
      /\bS(\d{1,2})\b(?![A-Za-z0-9])/i
    ];
    for (i = 0; i < seasonPats.length && !season; i++){
      m = seasonPats[i].exec(t);
      if (m) season = parseInt(m[1], 10) || 0;
    }
    var b = t;
    b = b.replace(/\(\s*season\s*\d{1,2}\s*\)/ig, ' ');
    b = b.replace(/\bseason\s*\d{1,2}\b/ig, ' ');
    b = b.replace(/\bS\d{1,2}\b(?![A-Za-z0-9])/ig, ' ');
    b = b.replace(/\b(?:blu\s*-?\s*ray|web\s*-?\s*(?:dl|hdrip|rip)|hdrip|webrip|hdtv|brrip|dvdrip|camrip|hdcam|remux|hdts)\b/ig, ' ');
    /* "Complete" / "All Episodes" are release wording. Bare CAM/TS/TC are NOT
       stripped: they are ordinary words and mangling a real title is far worse
       than leaving a stray token in an API query. */
    b = b.replace(/\b(?:complete|completed|full\s+season|season\s+complete|all\s+episodes?|all\s+parts?|episodes?)\b/ig, ' ');
    b = b.replace(/\b(?:netflix|amazon\s+prime|prime\s+video|disney\s*\+?|hotstar|hbo|zee5|voom)\b/ig, ' ');
    b = b.replace(/\(\s*(?:19|20)\d{2}\s*\)/g, ' ');
    b = b.replace(/\b(?:19|20)\d{2}\b/g, ' ');
    b = b.replace(/\[[^\]]*\]/g, ' ');
    b = b.replace(/\(\s*\)/g, ' ');
    b = b.replace(/\s{2,}/g, ' ');
    b = b.replace(/^[\s|,/&+.-]+/, '');
    b = b.replace(/[\s|,/&.]+$/, '');
    b = b.trim();
    return { title: b || t, season: season, clean: t };
  }
  function episodeLabel(base, ep){
    var s = String(base || '').trim();
    var season = ep && ep.season, num = ep && ep.episode, t = ep && ep.title;
    var head = s;
    if (season && num) head = s + ' S' + season + ' E' + num;
    else if (num) head = s + ' E' + num;
    if (t) head = head ? head + ': ' + t : t;
    return head;
  }
  /* Neutral 16:9 plate for cards whose post carries no artwork, so a missing
     image reads as a placeholder rather than a torn or empty box. */
  var ZD_NOIMG = 'data:image/svg+xml,%3Csvg xmlns=%22http://www.w3.org/2000/svg%22 width=%22480%22 height=%22270%22%3E%3Crect width=%22480%22 height=%22270%22 fill=%22%23181818%22/%3E%3C/svg%3E';

  function cleanTitle(raw){
    var t = String(raw == null ? '' : raw);
    if (!t) return '';
    /* 1. encoder / codec brackets: [x264/10Bit-HEVC], [x264/HEVC], [H.264] */
    t = t.replace(/\[[^\]]*\b(?:x264|x265|hevc|avc|h\.?26[45]|xvid|divx|10\s*-?\s*bits?|8\s*-?\s*bits?|av1|vp9)\b[^\]]*\]/gi, ' ');
    /* 2. named audio streams. No trailing \b: "DD5.1" has no word boundary after
          "DD" because a digit follows, so \bDD\b would silently never match. */
    t = t.replace(/(?:\bddp?|\bdts(?:-hd)?|\bac-?3|\beac-?3|\batmos|\btruehd|\baac|\bopus|\blpcm|\bflac)[\s.\-]*\d+(?:[.,]\d+)?/gi, ' ');
    /* 3. parenthesised channel counts - (ORG 2.0), (5.1). A decimal point is
          required so a plain year like (2022) is never touched. */
    t = t.replace(/\(\s*(?:org\s*)?\d+[.,]\d+\s*\)/gi, ' ');
    t = t.replace(/\b\d+[.,]\d+\b/g, ' ');
    /* 4. resolution runs with their connectors: "1080p 720p & 480p" */
    t = t.replace(/\b\d{3,4}\s*[pi]\b(?:\s*(?:&|and|,|\/|\|)\s*\b\d{3,4}\s*[pi]\b)*/gi, ' ');
    /* 5. loose resolutions and the bare quality tag. \bHD\b cannot match
          WEB-HDRip, HDCAM or BluRay because no word boundary follows the HD. */
    t = t.replace(/\b(?:2160|1440|1080|720|576|480|360)\s*[pi]?\b/g, ' ');
    t = t.replace(/\bHD\b/g, ' ');
    /* 6. remaining encoder / bit-depth / subtitle words */
    t = t.replace(/\b(?:x264|x265|hevc|avc|xvid|divx|av1|vp9)\b/gi, ' ');
    t = t.replace(/\b\d+\s*-?\s*bits?\b/gi, ' ');
    t = t.replace(/\b(?:esubs?|subbed|subtitles?|dubbed)\b/gi, ' ');
    /* 6b. release names: BluRay / WEB-DL / WEBRip / HDRip / HDTV / DVD and
       friends are inventory data and must never appear to the reader, on any
       surface (cards, player labels, search, history, document title) */
    t = t.replace(/\b(?:blu[\s-]*ray|bd[\s-]*rip|br[\s-]*rip|web[\s-]*(?:dl|rip|hdrip|cap)|hdrip|hdtv|hdts|hdtc|dvd(?:rip|scr|r)?|brscr|remux|hdcam|camrip|webdl|webrip)\b/ig, ' ');
    t = t.replace(/\b\d{3,4}\s*x\s*\d{3,4}\b/gi, ' ');
    t = t.replace(/\bDual\s+Audio\b/gi, ' ');
    /* 7. the pipe tail is release/marketing noise on this blog */
    var bar = t.indexOf('|');
    if (bar > -1) t = t.slice(0, bar);
    /* 8. tidy the seams - parentheses are left exactly as the author wrote them */
    t = t.replace(/\[[^\]]*\]/g, function(grp){
      var inner = grp.replace(/[\[\]]/g, '').replace(/\s{2,}/g, ' ').trim();
      return inner ? '[' + inner + ']' : '';
    });
    t = t.replace(/\(\s*\)/g, '');
    t = t.replace(/\s{2,}/g, ' ');
    t = t.replace(/\s*([|,/])\s*/g, ' $1 ');
    t = t.replace(/\s*[-–]\s*$/, '');
    t = t.replace(/^[\s|,/&+.-]+/, '');
    t = t.replace(/[\s|,/&]+$/, '');
    /* trailing release chatter: "Episode 10 Added!", "Updated!" */
    t = t.replace(/\s*\b(?:episode|ep)\.?\s*\d{1,3}\s*(?:added|updated|uploaded)?\s*[!:]?\s*$/i, '');
    t = t.replace(/\s*\b(?:added|updated|uploaded)\s*[!]?\s*$/i, '');
    t = t.replace(/\s{2,}/g, ' ').trim();
    return t;
  }

  /* ==================================================================
     Post shortcodes: [metadata] and [media].
     Every post carries its own data, so the theme never calls a third-party
     metadata API again. The blocks are DATA, not content: they are parsed
     out of the post and stripped from everything the reader sees.

       [metadata]{ "Title": "Breaking Bad", "Poster": "https://...",
                   "yt-trailer": "https://youtu.be/...", ... }[/metadata]

       [media]{ "Season 1": { "Episode 1: Pilot": "https://..." },
                "Season 2": { "Episode 1: Green Day": "https://..." } }[/media]

     A movie post simply carries one entry ("Full Movie": "url"), with or
     without a season wrapper. Both are handled.
  */
  function decodeEntities(s){
    var t = String(s == null ? '' : s);
    if (t.indexOf('&') < 0) return t;
    var d = doc.createElement('textarea');
    d.innerHTML = t;
    return d.value;
  }
  /* Tolerant JSON: authors paste from OMDb viewers, so smart quotes and a
     trailing comma must not break the post. */
  function jsonLoose(text){
    var t = String(text || '').trim();
    if (!t) return null;
    t = t.replace(/[\u201c\u201d]/g, '"').replace(/[\u2018\u2019]/g, "'");
    try { return JSON.parse(t); } catch (e) {}
    try { return JSON.parse(t.replace(/,\s*([}\]])/g, '$1')); } catch (e) {}
    return null;
  }
  /* The JSON chunk of one block, with Blogger's line-wrapping markup removed. */
  function scBlock(src, tag){
    var re = new RegExp('\\[' + tag + '\\]([\\s\\S]*?)\\[\\/' + tag + '\\]', 'i');
    var m = re.exec(String(src || ''));
    if (!m) return null;
    var inner = String(m[1] || '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(?:div|p|pre|span)>/gi, '\n')
      .replace(/<[^>]+>/g, '');
    return jsonLoose(decodeEntities(inner));
  }
  function parseMetaJson(json){
    if (!json || typeof json !== 'object' || Array.isArray(json)) return null;
    var out = {};
    Object.keys(json).forEach(function (k){ out[String(k).trim()] = json[k]; });
    return Object.keys(out).length ? out : null;
  }
  /* "Episode 1: Cats Black Day" and "Episode 2 Red skies" both parse; a key
     without an episode number keeps its position as the number. */
  function episodeKeyParse(key){
    var m = /^\s*episode\s*(\d{1,3})\s*(?::|-)?\s*(.*)$/i.exec(String(key || ''));
    if (m) return { num: parseInt(m[1], 10) || 0, title: (m[2] || '').trim() };
    return { num: 0, title: String(key || '').trim() };
  }
  /* [media] JSON -> { seasons: [{label, num, eps}], flat: [episode...] }.
     Insertion order is preserved everywhere, so next/previous walk the
     playlist exactly the way the author wrote it, across season boundaries. */
  function normalizeMedia(json){
    if (!json || typeof json !== 'object' || Array.isArray(json)) return null;
    var seasons = [], flat = [];
    function addSeason(label, map, snum){
      var eps = [];
      Object.keys(map || {}).forEach(function (k, i){
        var v = map[k];
        var src = (typeof v === 'string') ? videoSourceFrom(v) : null;
        if (!src) return;
        var p = episodeKeyParse(k);
        var num = p.num || (i + 1);
        var ep = {
          season: snum, seasonLabel: label, episode: num,
          title: p.title || ('Episode ' + num), src: src
        };
        eps.push(ep);
        flat.push(ep);
      });
      if (eps.length) seasons.push({ label: label, num: snum, eps: eps });
    }
    var keys = Object.keys(json);
    var looksLikeSeasons = keys.some(function (k){ return /^season/i.test(String(k).trim()); });
    if (looksLikeSeasons){
      keys.forEach(function (k, i){
        var v = json[k];
        if (!v || typeof v !== 'object' || Array.isArray(v)) return;
        var sm = /^season\s*(\d+)\s*$/i.exec(String(k).trim());
        addSeason(String(k).trim(), v, sm ? (parseInt(sm[1], 10) || (i + 1)) : (i + 1));
      });
    } else {
      addSeason(keys.length === 1 && !/^episode/i.test(keys[0]) ? 'Movie' : 'Season 1', json, 1);
    }
    if (!flat.length) return null;
    return { seasons: seasons, flat: flat };
  }
  /* Parse both blocks out of a post body string (feed content). */
  function extractPostData(html){
    var s = String(html || '');
    var meta = parseMetaJson(scBlock(s, 'metadata'));
    var media = normalizeMedia(scBlock(s, 'media'));
    return { meta: meta, media: media };
  }

  /* ---------------- per-post data registry ----------------
     record() fills it for every post that flows through a feed response, so
     rails, search results and hover previews never make a second request.
     Server-rendered cards (Blogger widgets) resolve through postInfo(),
     which fetches the single post by its path and caches for the session. */
  var POST_DATA = {};
  function normUrl(u){
    return String(u || '').split('#')[0].split('?')[0].replace(/\/+$/, '');
  }
  function rememberPost(url, meta, media, rec){
    var k = normUrl(url);
    if (!k) return;
    POST_DATA[k] = { meta: meta || null, media: media || null, rec: rec || null };
  }
  function fetchPostRecord(url, cb){
    var path = normUrl(url).replace(/^https?:\/\/[^/]+/i, '');
    if (!path){ cb(null); return; }
    feed(BLOG + 'feeds/posts/default?alt=json-in-script&max-results=1&path=' + encodeURIComponent(path), function (json){
      var e = ((json && json.feed && json.feed.entry) || [])[0];
      cb(e ? record(e) : null);
    });
  }
  function postInfo(url){
    return new Promise(function (resolve){
      var k = normUrl(url);
      if (!k) return resolve(null);
      if (POST_DATA[k]) return resolve(POST_DATA[k]);
      try {
        var raw = sessionStorage.getItem('zamd_post:' + k);
        if (raw){
          var p = JSON.parse(raw);
          if (p && p.d && p.t && ((new Date()).getTime() - p.t) < 600000){
            POST_DATA[k] = p.d;
            return resolve(p.d);
          }
        }
      } catch (e) {}
      fetchPostRecord(url, function (rec){
        var d = rec ? { meta: rec.meta || null, media: rec.media || null, rec: rec } : null;
        if (d) rememberPost(url, rec.meta, rec.media, rec);
        try { sessionStorage.setItem('zamd_post:' + k, JSON.stringify({ t: (new Date()).getTime(), d: d })); } catch (e) {}
        resolve(d);
      });
    });
  }

  /* Normalize a feed entry -> PostRecord. The post's own [metadata] shortcode
     is the data source: display title, year, portrait poster and the trailer.
     The legacy [trailer-link] shortcode still works as a fallback. */
  function record(e){
    var content = (e && e.content && e.content.$t) || (e && e.summary && e.summary.$t) || '';
    var data = extractPostData(content);
    var meta = data.meta;
    var labels = flabels(e);
    var yts = meta ? na(meta['yt-trailer']) : '';
    var trailer = '';
    if (yts){
      trailer = videoSourceFrom(yts)
        || (ytId(yts) ? { kind: 'iframe', id: ytId(yts), src: 'https://www.youtube.com/embed/' + ytId(yts) + '?rel=0&enablejsapi=1' } : '');
    }
    if (!trailer) trailer = trailerFrom(content);
    var rec = {
      url: flink(e),
      title: cleanTitle((meta && na(meta.Title)) || (e && e.title && e.title.$t) || ''),
      snippet: fsnippet(e, 180),
      labels: labels,
      label: labels[0] || '',
      year: (meta && naYear(meta.Year)) || fyear((e && e.published && e.published.$t) || ''),
      date: fdate((e && e.published && e.published.$t) || ''),
      published: (e && e.published && e.published.$t) || '',
      thumb: fthumb(e, '/w320-h180-p-k-no-nu/'),
      thumbBig: fthumb(e, '/w800-h450-p-k-no-nu/'),
      /* portrait art straight from the post's [metadata] Poster field — no
         third-party lookup; when absent the card keeps its black plate */
      poster: (meta && safeUrl(na(meta.Poster))) || '',
      trailer: trailer,
      meta: meta,
      media: data.media
    };
    if (rec.url && (meta || data.media)) rememberPost(rec.url, meta, data.media, rec);
    return rec;
  }

  /* ---------------- card renderer (poster/landscape/compact) ---------------- */
  function esc(s){ return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }
  /* Defence in depth for URLs that arrive from outside the theme - the Blogger
     feed and the OMDb response. esc() makes a string safe to put inside markup;
     it says nothing about where the browser will then navigate, so a hostile
     "javascript:" in a feed entry would still run. Anything that is not plainly
     http(s), protocol-relative or site-relative is dropped instead.

     Every real Blogger and OMDb URL passes through untouched, and the inline
     placeholder image is assigned directly rather than through here, so the
     data: URL it relies on is unaffected. */
  function safeUrl(u){
    var s = String(u == null ? '' : u).trim();
    if (!s) return '';
    /* control characters and stray whitespace are stripped before the scheme is
       read, so "java\tscript:" and " javascript:" cannot slip past */
    var scheme = s.replace(/[\u0000-\u0020\u007f]+/g, '').toLowerCase();
    if (/^[a-z][a-z0-9+.-]*:/.test(scheme) && !/^https?:/.test(scheme)) return '';
    return s;
  }
  /* Netflix-style corner badge. Deliberately stingy: a badge on every card reads
     as noise, so only genuinely fresh uploads get one. */
  function nfBadge(r){
    if (!r || !r.published) return '';
    var t = new Date(r.published).getTime();
    if (isNaN(t)) return '';
    var days = (new Date().getTime() - t) / 86400000;
    if (days < 0 || days > 10) return '';
    return days <= 2
      ? '<span class="nf-badge is-new">New</span>'
      : '<span class="nf-badge is-dark">New Episode</span>';
  }
  function card(r, mode){
    mode = mode || C.cardMode || 'landscape';
    var a = doc.createElement('a');
    a.className = 'poster-media';
    a.href = safeUrl(r.url);
    a.setAttribute('aria-label', r.title);
    var hover = '<span class="poster-hover"><span class="play-ic"><i class="fa fa-play"></i></span></span>';
    if (mode === 'poster'){
      /* Portrait art comes from the post's own [metadata] Poster field, parsed
         while the feed entry was normalized — no extra request, no lookup
         service. Until a post declares one, the slot is a black plate carrying
         the clean title, so the grid is never a field of empty boxes. */
      if (r.poster){
        /* the plate stays underneath: a poster that fails to load (hotlink
           blocks, ad blockers) reveals it instead of a torn image */
        a.innerHTML = nfBadge(r) + hover
          + '<span class="poster-plate"><span class="poster-plate-t">' + esc(r.title) + '</span></span>'
          + '<img alt="'+esc(r.title)+'" src="'+esc(r.poster)+'"'+(C.lazyLoad !== false ? ' loading="lazy"' : '')+'>';
        var pimg = a.querySelector('img');
        if (pimg){
          pimg.addEventListener('error', function(){
            if (pimg.parentNode) pimg.parentNode.removeChild(pimg);
          }, { once: true });
        }
      } else {
        a.innerHTML = nfBadge(r) + hover
          + '<span class="poster-plate"><span class="poster-plate-t">' + esc(r.title) + '</span></span>';
        a.setAttribute('data-plate', '1');
      }
    } else {
      var imgSrc = r.thumb;
      a.innerHTML = nfBadge(r)
        + '<img alt="'+esc(r.title)+'" src="'+esc(imgSrc)+'"'+(C.lazyLoad !== false ? ' loading="lazy"' : '')+'>'
        + hover;
    }
    var imgSrc = r.thumb;
    var box = doc.createElement('article');
    box.className = 'poster-card rail-card-' + mode;
    /* the hover preview is driven entirely by this attribute */
    if (r.trailer){
      box.setAttribute('data-trailer-kind', r.trailer.kind);
      box.setAttribute('data-trailer', r.trailer.src);
    }
    box.appendChild(a);
    var mi = doc.createElement('button');
    mi.type = 'button';
    mi.className = 'zd-preview-trigger poster-more';
    mi.setAttribute('data-url', r.url);
    mi.setAttribute('data-title', r.title);
    mi.setAttribute('data-label', r.label);
    mi.setAttribute('data-year', r.year);
    mi.setAttribute('data-thumb', imgSrc);
    mi.innerHTML = '<i class="fa fa-plus"></i>';
    box.appendChild(mi);
    var t = doc.createElement('h3');
    t.className = 'poster-title';
    t.innerHTML = '<a href="'+esc(r.url)+'">'+esc(r.title)+'</a>';
    box.appendChild(t);
    var sub = doc.createElement('div');
    sub.className = 'poster-sub';
    sub.innerHTML = '<time>' + esc(r.date || r.year || '') + '</time>'
      + (r.label ? '<span class="sep">\u2022</span><span>'+esc(r.label)+'</span>' : '');
    box.appendChild(sub);
    return box;
  }

/* ---------------- Content Query (source/label/sort/period/limit) ---------------- */
  /* Netflix-style progressive rows: paint RAIL_BATCH cards, then hand the
     visitor the rest of the window as soon as they reach the row's end. */
  var RAIL_BATCH = 8;
  var RAIL_FETCH = 24;
  /* One reusable query layer: every rail, series, related-supply and search result
     flows through contentQuery() and gets normalized to PostRecords. Blogger owns
     the data (posts feed, label feed, period filtering); this layer owns access. */
  function contentQuery(spec, cb){
    spec = spec || {};
    var source = spec.source || 'recent';
    var params = {
      label: (source === 'label' && spec.label) ? spec.label : '',
      /* pull a generous window so rails can reveal the next batch on demand,
         even when the gadget only asks for a handful of cards */
      max: spec.fetch || Math.max(spec.count || 8, RAIL_FETCH),
      orderby: (spec.sort === 'oldest') ? 'published' : '',
      min: periodMin(spec.period)
    };
    feed(feedUrl(params), function(json){
      var entries = (json && json.feed && json.feed.entry) || [];
      if (spec.sort === 'oldest'){
        entries = entries.slice().sort(function(a, b){
          var pa = (a.published && a.published.$t) || '';
          var pb = (b.published && b.published.$t) || '';
          return pa < pb ? -1 : pa > pb ? 1 : 0;
        });
      }
      entries = entries.filter(function(e){ return isPostUrl(flink(e)); });
      if (spec.count) entries = entries.slice(0, spec.count);
      cb(entries.map(function(e){ return record(e); }));
    });
  }
  function periodMin(period){
    if (!period) return '';
    var n = parseInt(period, 10);
    if (!n) return '';
    var d = new Date();
    d.setDate(d.getDate() - n);
    return d.toISOString().split('T')[0] + 'T00:00:00';
  }

  /* ---------------- one shortcode grammar for gadget rails ---------------- */
  /* Grammar (LiteSpot-compatible, extended):
       $source={recent|label}   $label={Label}   $count={N}
       $sort={newest|oldest}    $period={7|30|all}   $card={poster|landscape|compact}
     The gadget's Layout title becomes the public rail heading. */
  function parseShortcode(text){
    var cfg = { source: 'recent', label: '', count: 12, card: C.cardMode || 'landscape', sort: 'newest', period: '' };
    String(text || '').replace(/\s+/g, ' ').replace(/\$(\w+)=([^\s$]+)/g, function(m, k, v){
      if (k === 'count' || k === 'limit') cfg.count = parseInt(v, 10) || 12;
      else if (k === 'type') cfg.card = (v === 'block' || v === 'widget') ? 'poster' : v;
      else if (k === 'orderby' || k === 'sort') cfg.sort = (v.indexOf('old') === 0) ? 'oldest' : 'newest';
      else if (k === 'results') cfg.count = parseInt(v, 10) || 12;
      else if (k === 'period') cfg.period = (v === 'all' || v === 'all-time' || v === 'ALL_TIME') ? '' : v;
      else cfg[k] = v;
