      h.innerHTML = '<h2 class="rail-heading-title">' + esc(heading) + '</h2>'
        + '<a class="rail-explore" href="' + esc(railExploreHref(cfg)) + '">Explore all <i class="fa fa-chevron-right"></i></a>';
