      var cfg = parseShortcode(sc);
      cfg.heading = container.getAttribute('data-heading') || cfg.heading || '';
      /* If Blogger already rendered a widget title for this gadget, that title IS
         the row heading - never emit a second one on top of it. */
      var w = container.closest ? container.closest('.widget') : null;
      var srvTitle = w ? w.querySelector('.widget-title') : null;
      var srvText = srvTitle ? (srvTitle.textContent || '').trim() : '';
