  }

  /* ---------------- horizontal rails: arrows + wheel ---------------- */
  function initRails(){
    var finePointer = !window.matchMedia || !window.matchMedia('(hover: none)').matches;
    $$('.rail').forEach(function(rail){
      if (rail.getAttribute('data-init')) return;
      rail.setAttribute('data-init', '1');
      var wrap = rail.closest ? rail.closest('.rail-wrap') : null;
      var prev, next;
      var canScroll = function(){ return rail.scrollWidth - 2 > rail.clientWidth; };
      if (wrap && finePointer){
        prev = doc.createElement('button');
        prev.type = 'button';
        prev.className = 'rail-btn prev';
        prev.setAttribute('aria-label', 'Scroll left');
        prev.innerHTML = '<i class="fa fa-chevron-left"></i>';
        next = doc.createElement('button');
        next.type = 'button';
        next.className = 'rail-btn next';
        next.setAttribute('aria-label', 'Scroll right');
        next.innerHTML = '<i class="fa fa-chevron-right"></i>';
        wrap.appendChild(prev);
        wrap.appendChild(next);
        var scrollBy = function(d){ rail.scrollBy({ left: d, behavior: 'smooth' }); };
        prev.addEventListener('click', function(){ scrollBy(-Math.round(rail.clientWidth * 0.8)); });
        next.addEventListener('click', function(){ scrollBy(Math.round(rail.clientWidth * 0.8)); });
        var bound = function(){
          var atStart = rail.scrollLeft <= 2;
          var atEnd = rail.scrollLeft >= rail.scrollWidth - rail.clientWidth - 2;
          wrap.classList.toggle('has-scroll', canScroll());
          wrap.classList.toggle('at-start', atStart);
          wrap.classList.toggle('at-end', atEnd);
          prev.classList.toggle('is-hidden', atStart || !canScroll());
          next.classList.toggle('is-hidden', atEnd || !canScroll());
        };
        rail.addEventListener('scroll', bound, { passive: true });
        window.addEventListener('resize', bound, { passive: true });
