  /* Netflix rows run edge to edge. A short row - 7 titles in a wide window -
     used to stop dead and leave a large void on the right. These inert blanks
     fill that space so the strip reads as continuous. They carry no link, are
     hidden from assistive tech, and are skipped entirely when the row already
     overflows (i.e. when it is a real scroller). */
  var ZD_PAD_RO = ('ResizeObserver' in window) ? new ResizeObserver(function(entries){
    for (var i = 0; i < entries.length; i++){
      var r = entries[i].target;
      if (r.__padFill) r.__padFill();
