       pass through renderRail() and were therefore never padded at all. */
    $$('body.view-home .rail').forEach(function(r){ padRail(r); });
  }

  /* ---------------- preview overlay (More Info) ---------------- */
  var overlay, preview, pClose;
  /* Metadata comes from each post's own [metadata]/[media] shortcodes (see the
     registry above) — the third-party metadata API the theme used to call is
     gone, together with its keys, its queue and its daily request budget. */

  /* --- field helpers: OMDb-shaped strings answer "N/A" for anything unknown,
         and the brief is explicit that "N/A" must never be shown --- */
  /* --- field helpers: OMDb returns the string "N/A" for anything unknown,
         and the brief is explicit that "N/A" must never be shown --- */
  function na(v){
    var s = String(v == null ? '' : v).trim();
    return (!s || s === 'N/A') ? '' : s;
  }
  function naList(v){
    var s = na(v);
    if (!s) return [];
    if (s === 'N/A') return [];
    return s.split(/\s*,\s*/).filter(function (x) { return !!x && x !== 'N/A'; });
  }
  function naYear(v){
    var s = na(v);
    var m = /(\d{4})/.exec(s);
    return m ? m[1] : '';
  }

  /* The Netflix-style detail card, rendered from the post's own shortcodes.
     Structure and scale follow the captured reference (infocard example.htm):
     a 16:9 media region, a #181818 metadata area on a 2fr/1fr grid, a
     right-aligned season dropdown, episode rows separated by #404040 and an
     "About" block. Everything shown comes from the post's [metadata] and
     [media] JSON - nothing is invented, and a field the author left empty is
     left out rather than shown.
     ctx = { url, title, year, label, thumb, trailerId, seasons, episodes, meta } */
  function renderDetailCard(ov, ctx, state){
    var E = esc;
    var m = ctx.meta || {};
    var loading = state === 'loading';
    var seasons = ctx.seasons || (ctx.media && ctx.media.seasons) || [];
    var eps = ctx.episodes || (ctx.media && ctx.media.flat) || [];
    var title = na(m.Title) || ctx.title || '';
    var year = naYear(m.Year) || ctx.year || '';
    var type = (na(m.Type) || '').toLowerCase();
    var isSeries = type === 'series' || seasons.length > 1 || eps.length > 1;
    var rating = na(m.imdbRating);
    var votes = na(m.imdbVotes);
    var plot = na(m.Plot);
    var cast = naList(m.Actors);
    var genres = naList(m.Genre);
    var runtime = na(m.Runtime);
    var rated = na(m.Rated);
    var metascore = na(m.Metascore);
    var awards = na(m.Awards);
    var released = na(m.Released);
    var language = na(m.Language);
    var country = na(m.Country);
    var director = na(m.Director);
    var writer = na(m.Writer);
    var poster = safeUrl(na(m.Poster));
    var totalSeasons = na(m.totalSeasons) || (seasons.length ? String(seasons.length) : '');
    /* secondary ratings (Rotten Tomatoes, Metacritic, ...) from the array */
    var extraR = [];
    if (Array.isArray(m.Ratings)){
      m.Ratings.forEach(function (r){
        if (!r) return;
        var src = na(r.Source), val = na(r.Value);
        if (!val || !src) return;
        var tag = /rotten/i.test(src) ? 'RT' : (/metacritic/i.test(src) ? 'MC' : (/internet movie/i.test(src) ? '' : src.split(/\s+/)[0]));
        if (tag) extraR.push({ s: tag, v: val });
      });
    }

    /* ---------- media: the trailer plays; the wide art is the still ----------
       The 800px landscape thumb fills the 16:9 region natively; the portrait
       Poster is the fallback, so the backdrop is never an upscaled blur. */
    var art = ctx.thumb || poster || '';

    /* ---------- metadata: the left/right split Netflix uses ---------- */
    var left = [];
    if (year) left.push('<span class="zmd-f">' + E(year) + '</span>');
    if (isSeries && totalSeasons) left.push('<span class="zmd-f">' + E(totalSeasons) + ' Season' + (totalSeasons === '1' ? '' : 's') + '</span>');
    if (runtime) left.push('<span class="zmd-f">' + E(runtime) + '</span>');
    if (type) left.push('<span class="zmd-chip">' + E(type) + '</span>');
    if (rating) left.push('<span class="zmd-rating" title="IMDb rating">'
        + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 3.6l2.6 5.3 5.9.9-4.3 4.1 1 5.8-5.2-2.7-5.2 2.7 1-5.8L3.5 9.8l5.9-.9z"/></svg>'
        + E(rating) + '<span class="zmd-of">/10</span></span>');
    if (votes) left.push('<span class="zmd-votes">' + E(votes) + ' votes</span>');
    if (rated) left.push('<span class="zmd-mat">' + E(rated) + '</span>');
    /* Continue Watching: what this visitor was last watching on this title */
    var cwRec = cwMatch(ctx.url);
    var playHref = ctx.url || '';
