      }
    }
    extraR.forEach(function (r){
      left.push('<span class="zmd-mat" title="' + E(r.s) + '">' + E(r.s) + ' ' + E(r.v) + '</span>');
    });
    if (language) left.push('<span class="zmd-cap" title="Audio and subtitles">'
        + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9.5h3L11 6v12l-4-3.5H4z"/><path d="M14.5 9a4 4 0 0 1 0 6M17 6.5a7.5 7.5 0 0 1 0 11"/></svg>'
        + '<span class="zmd-cap-t">' + E(language.split(',')[0].trim()) + '</span></span>');

    var right = '';
    if (loading){
      right = '<div class="zmd-skel-row" style="flex-direction:column;align-items:stretch">'
        + '<span class="zmd-skel-line w4" style="width:70%"></span>'
        + '<span class="zmd-skel-line w3" style="width:56%"></span>'
        + '<span class="zmd-skel-line w2" style="width:40%"></span></div>';
    } else {
      if (cast.length){
        var shortCast = cast.slice(0, 3).join(', ');
        right += '<div class="zmd-field"><span class="zmd-label">Cast</span>'
          + '<span class="zmd-val">' + E(shortCast)
          + (cast.length > 3 ? ' <em class="zmd-more" data-cast="' + E(cast.join('|')) + '">more</em>' : '')
          + '</span></div>';
      }
      if (genres.length){
        right += '<div class="zmd-field"><span class="zmd-label">Genres</span>'
          + '<span class="zmd-val">' + E(genres.join(', ')) + '</span></div>';
      }
      if (director && !isSeries){
        right += '<div class="zmd-field"><span class="zmd-label">Director</span>'
          + '<span class="zmd-val">' + E(director) + '</span></div>';
      }
    }

    /* ---------- episodes, straight from this post's [media] shortcode ---------- */
    var epHtml = '';
    if (eps.length && !loading){
      var opts = seasons.map(function (s, i){
        return '<option value="' + E(String(s.num)) + '"' + (i === 0 ? ' selected' : '') + '>' + E(s.label) + '</option>';
      }).join('');
      epHtml = '<section class="zmd-sect zmd-episodeSelector">'
        + '<div class="zmd-sect-head"><h3 class="zmd-h">Episodes</h3>'
        + (seasons.length > 1
