              + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 10l5 5 5-5"/></svg></div>'
            : '')
        + '</div>'
        + seasons.map(function (s, oi){
            return '<div class="zmd-ep-season"' + (oi ? ' hidden' : '') + ' data-s="' + E(String(s.num)) + '">'
              + '<div class="zmd-season-label">' + E(s.label) + ':' + (rated ? ' <span class="zmd-mat">' + E(rated) + '</span>' : '') + '</div>'
              + s.eps.map(function (ep){
                  var num = ep.episode || 1;
                  var row = '<span class="zmd-ep-n">' + num + '</span>'
                    + '<span class="zmd-ep-main"><span class="zmd-ep-t">' + E(ep.title || ('Episode ' + num)) + '</span></span>'
                    + '<span class="zmd-ep-go"><svg viewBox="0 0 24 24" aria-hidden="true"><path class="ic-fill" d="M7 4.5v15l13-7.5z"/></svg></span>';
                  /* the current post's rows drive the player that is already on
                     screen; any other post's rows link to its watch page */
                  var epIx = eps.indexOf(ep);
                  if (isCurrentPost(ctx.url)){
                    return '<button class="zmd-ep" type="button" data-i="' + epIx + '">' + row + '</button>';
                  }
