    /* ---------- About ---------- */
    var about = [];
    if (director) about.push(['Director', director]);
    if (writer) about.push(['Writer', writer]);
    if (cast.length) about.push(['Cast', cast.join(', ')]);
    if (genres.length) about.push(['Genres', genres.join(', ')]);
    if (released) about.push(['Released', released]);
    if (language) about.push(['Language', language]);
    if (country) about.push(['Country', country]);
    if (metascore) about.push(['Metascore', metascore + '/100']);
    if (awards) about.push(['Awards', awards]);
    if (na(m.imdbID)) about.push(['IMDb', na(m.imdbID)]);
    var aboutHtml = (!loading && about.length)
      ? '<section class="zmd-sect about-wrapper"><h3 class="zmd-h">About ' + E(title) + '</h3>'
        + about.map(function (a) {
            return '<div class="zmd-field"><span class="zmd-label">' + E(a[0]) + '</span><span class="zmd-val">' + E(a[1]) + '</span></div>';
          }).join('')
        + (rated ? '<div class="zmd-maturity"><span class="zmd-label">Age rating</span><span class="zmd-mat">' + E(rated) + '</span></div>' : '')
        + '</section>'
      : '';

    var metaLeft = loading
      ? '<div class="zmd-skel-row"><span class="zmd-skel-line w2"></span><span class="zmd-skel-line w3"></span><span class="zmd-skel-line w4"></span></div>'
        + '<div class="zmd-skel-plot l1"></div><div class="zmd-skel-plot l2"></div><div class="zmd-skel-plot l3"></div>'
      : '<div class="zmd-meta-row">' + left.join(' ') + '</div>'
        + (plot ? '<p class="zmd-plot">' + E(plot) + '</p>' : '');

    ov.innerHTML =
        '<div class="zmd-card" role="document">'
      +   '<button class="zmd-close" type="button" aria-label="Close"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 5l14 14M19 5L5 19"/></svg></button>'
      +   '<div class="zmd-player_container">'
      +     '<div class="zmd-media">'
      +       '<div class="zmd-media-bg">' + (art ? '<img alt="" src="' + E(art) + '">' : '') + '</div>'
      +       '<div class="zmd-media-yt"></div>'
      +       '<div class="zmd-media-shade"></div>'
      +       '<div class="zmd-title-wrap">'
      +         '<span class="zmd-brand">ZaminDrive</span>'
      +         '<h2 class="zmd-title">' + E(title || 'Loading\u2026') + '</h2>'
      +         '<div class="zmd-play-row">'
      +           (playHref ? '<a class="zmd-play" href="' + E(playHref) + '"><svg viewBox="0 0 24 24" aria-hidden="true"><path class="ic-fill" d="M7 4.5v15l13-7.5z"/></svg><span>Play</span></a>' : '')
      +           '<button class="zmd-round zd-bm-addbtn" type="button" aria-label="My List"'
      +             ' data-url="' + E(ctx.url || '') + '"'
      +             ' data-title="' + E(ctx.title || '') + '"'
      +             ' data-thumb="' + E(ctx.thumb || '') + '"'
      +             ' data-year="' + E(ctx.year || '') + '"'
      +             ' data-label="' + E(ctx.label || '') + '">'
      +             '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 5v14M5 12h14"/></svg></button>'
      +           '<button class="zmd-round" type="button" aria-label="Rate"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 11v9H4v-9zM10 11l4.5-9 1.5 4H20a1 1 0 0 1 1 1.2l-1.2 7.8a1 1 0 0 1-1 .8H10z"/></svg></button>'
      +         '</div>'
      +       '</div>'
      +     '</div>'
      +   '</div>'
      +   '<div class="zmd-detail-modal-container">'
      +     '<div class="zmd-detail">'
      +       '<div class="zmd-meta-left">'
      +         metaLeft
      +       '</div>'
      +       '<div class="zmd-meta-right">' + right + '</div>'
      +     '</div>'
      +   '</div>'
      +   epHtml
      +   aboutHtml
      + '</div>';

    /* the trailer becomes the media whenever the post declares one, and it is
       only mounted once the card is on screen so it can be measured */
    var ytHost = $('.zmd-media-yt', ov);
    if (!loading && ctx.trailerId && ytHost){
      ytTrailer(ytHost, ctx.trailerId, { title: 'Trailer: ' + title, muted: true });
      ov.classList.add('has-trailer');
    }
    if (art) ov.classList.add('has-art');
    var artImg = $('.zmd-media-bg img', ov);
    if (artImg) artImg.addEventListener('error', function(){ artImg.style.display = 'none'; }, { once: true });
    ov.classList.toggle('is-series', eps.length > 1);
    var mb = $('.zd-bm-addbtn', ov);
    /* setBmState, not classList.add: a re-render after the metadata arrives
       rebuilds this button, and it has to come back already reflecting storage */
    if (mb) setBmState(mb, isBooked(ctx.url));
  }
  function isCurrentPost(url){
    if (!url) return false;
    try {
      var canon = doc.querySelector('link[rel=canonical]');
      var here = canon ? canon.getAttribute('href') : location.href;
      var norm = function (u) { return String(u || '').split('#')[0].split('?')[0].replace(/\/+$/, ''); };
      if (norm(here) && norm(here) === norm(url)) return true;
      /* m=1 and other query noise must not make the current post look foreign */
      var lp = norm(location.pathname);
      var up = norm(url).replace(/^https?:\/\/[^/]+/i, '');
      if (lp && up && lp === up) return true;
      var a = $('.detail-entry a[href], .post-body a[href]');
      if (a && norm(a.getAttribute('href')) === norm(url)) return true;
      var ap = window.__sora_active_post;
      return !!(ap && ap.url && norm(ap.url) === norm(url));
    } catch (e) { return false; }
  }
  /* the landscape image the author uploaded, found by its alt marker */
  function findLandscapeImage(root){
    var imgs = $$('img', root || doc);
    for (var i = 0; i < imgs.length; i++){
      if (LAND_ALT.test(imgs[i].getAttribute('alt') || '')) return imgs[i];
    }
    return null;
  }

  function buildPreview(){
    if ($('.zamd-preview-overlay')) return;
    var ov = doc.createElement('div');
    ov.className = 'zamd-preview-overlay';
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.setAttribute('aria-label', 'More info');
    doc.body.appendChild(ov);
    overlay = ov;
    overlay.addEventListener('click', function(e){
      /* the backdrop closes, card controls do not */
      if (e.target === overlay) closePreview();
    });
    overlay.addEventListener('keydown', function(e){
      if (e.key === 'Escape') closePreview();
    });
  }
  /* ---- the trigger: a card's "+", the hero's "More Info", or the card's
         "More Details". Same modal either way. ---- */
  function openPreview(e){
    if (!overlay) buildPreview();
    var el = (e && e.currentTarget) || e;
    var id = el.getAttribute('data-url') || '';
    var label = el.getAttribute('data-label') || '';
    var title = cleanTitle(el.getAttribute('data-title') || '') || el.getAttribute('data-title') || '';
    var thumb = el.getAttribute('data-thumb') || '';
    var year = el.getAttribute('data-year') || '';
    var ctx = {
      url: id, title: title, year: year, label: label, thumb: thumb,
      trailerId: ytId(el.getAttribute('data-trailer-id') || el.getAttribute('data-trailer') || ''),
      seasons: [], episodes: [],
      seriesName: entertainmentName(title).title
    };
    overlay.classList.add('is-active');
    body.classList.add('preview-open', 'zamd-preview-open');
    doc.addEventListener('keydown', previewKey);

    /* paint instantly from whatever the trigger knows, then swap in the post's
       own shortcode data. The visitor never sees an empty black rectangle. */
    renderDetailCard(overlay, ctx, 'loading');
    var cardSettled = false;
    postInfo(id).then(function (d){
      cardSettled = true;
      if (!overlay.classList.contains('is-active')) return;   /* closed meanwhile */
      if (d){
        ctx.meta = d.meta || {};
        ctx.seasons = (d.media && d.media.seasons) || [];
        ctx.episodes = (d.media && d.media.flat) || [];
        if (d.meta && na(d.meta.Title)) ctx.title = na(d.meta.Title);
        if (d.meta && naYear(d.meta.Year)) ctx.year = naYear(d.meta.Year);
        if (d.rec) ctx.thumb = d.rec.thumbBig || d.rec.thumb || ctx.thumb;
        if (!ctx.trailerId && d.meta) ctx.trailerId = ytId(na(d.meta['yt-trailer']));
      }
      renderDetailCard(overlay, ctx, 'ready');
      wireDetailCard(ctx);
    });
    setTimeout(function(){
      if (!cardSettled && overlay.classList.contains('is-active')){
        renderDetailCard(overlay, ctx, 'ready');
        wireDetailCard(ctx);
      }
    }, 9000);
    /* The close button is re-created by every render, so the handler is bound
       once on the overlay - which survives the re-render - and finds the button
       from the event target. Binding it on the button itself meant the metadata
       arriving replaced the button and left the new one with no handler. */
    if (!overlay.__zamdCloseBound){
      overlay.__zamdCloseBound = true;
      overlay.addEventListener('click', function (e) {
        var t = e.target;
        if (t && typeof t.closest === 'function' && t.closest('.zmd-close')) closePreview();
      });
    }
  }
  function wireDetailCard(ctx){
    if (!overlay) return;
    var mb = $('.zd-bm-addbtn', overlay);
    if (mb) setBmState(mb, isBooked(ctx.url));
    /* the season dropdown is a real <select>, so keyboard and mobile behave */
    var sel = $('.zmd-select', overlay);
    if (sel){
      sel.addEventListener('change', function () {
        $$('.zmd-ep-season', overlay).forEach(function (l) {
          l.hidden = l.getAttribute('data-s') !== sel.value;
        });
      });
    }
    /* "more" expands the full cast, the way the reference does */
    $$('.zmd-more', overlay).forEach(function (m) {
      m.addEventListener('click', function () {
        var full = (m.getAttribute('data-cast') || '').split('|');
        var field = m.parentNode;
        if (!field || !full.length) return;
        field.textContent = full.join(', ');
      });
    });
    $$('.zmd-ep', overlay).forEach(function (b) {
      b.addEventListener('click', function () {
        var i = parseInt(b.getAttribute('data-i'), 10) || 0;
        var v = $('#detail-player-frame video');
        if (v && v.__zdPlayer && typeof v.__zdPlayer.goEpisode === 'function'){
          v.__zdPlayer.goEpisode(i);
          if (playScroll()) closePreview();
          return;
        }
        /* an embed-based player cannot switch in place: deep-link the episode */
        if (ctx.url){
          closePreview();
          window.location.href = ctx.url + (ctx.url.indexOf('?') > -1 ? '&' : '?') + 'ep=' + i;
        }
      });
    });
  }
  function closePreview(){
    if (!overlay) return;
    overlay.classList.remove('is-active');
    body.classList.remove('preview-open', 'zamd-preview-open');
    /* a trailer left running behind a closed card would keep playing audio */
    $$('.zmd-media-yt iframe', overlay).forEach(function (f) {
      f.parentNode && f.parentNode.removeChild(f);
    });
    doc.removeEventListener('keydown', previewKey);
  }
  function previewKey(e){
    if (e.key === 'Escape') closePreview();
  }

  function bindPreviewTriggers(){
    $$('.zd-preview-trigger').forEach(function(el){
      if (el.getAttribute('data-bound')) return;
      el.setAttribute('data-bound', '1');
      el.addEventListener('click', function(ev){ ev.preventDefault(); ev.stopPropagation(); openPreview(el); });
    });
  }

  /* ---------------- hover preview: the card plays its own trailer ----------------
     Netflix lifts a wide panel above the hovered card, plays the trailer muted,
     and shows a strip of round actions plus a metadata line. Exactly one control
     is exposed on the video itself: mute / unmute. */
  var hpEl = null, hpCard = null, hpTimer = null, hpCloseTimer = null;
  function hpKill(){
    if (hpTimer){ clearTimeout(hpTimer); hpTimer = null; }
    if (hpCloseTimer){ clearTimeout(hpCloseTimer); hpCloseTimer = null; }
    var el = hpEl, card = hpCard;
    hpEl = null; hpCard = null;
    if (card) card.classList.remove('is-hp');
    if (!el) return;
    /* blank the iframe src first, otherwise YouTube keeps playing off-screen */
    if (el.__media && el.__media.tagName === 'IFRAME'){
      try { el.__media.setAttribute('src', ''); } catch(e){}
    }
    if (el.parentNode) el.parentNode.removeChild(el);
  }
  /* the rail is an overflow-x scroller, so a panel placed inside the card would be
     clipped vertically - it lives in a fixed layer and is positioned from the
     card's rect instead, flipping below when there is no room above. */
  function placeHp(panel, card){
    var r = card.getBoundingClientRect();
    var vw = window.innerWidth || document.documentElement.clientWidth || 1200;
    var headH = parseInt(window.getComputedStyle(doc.documentElement).getPropertyValue('--nf-head'), 10) || 80;
    var w = Math.min(Math.max(r.width * 2.35, 290), 540, vw - 24);
    panel.style.width = Math.round(w) + 'px';
    var ph = panel.offsetHeight || Math.round(w * 0.5625) + 74;
    var left = r.left + r.width / 2 - w / 2;
    left = Math.max(12, Math.min(left, vw - w - 12));
    var top = r.top - ph - 10;
    if (top < headH + 8) top = Math.min(r.bottom + 10, (window.innerHeight || 800) - ph - 12);
    panel.style.left = Math.round(left) + 'px';
    panel.style.top = Math.round(Math.max(top, headH + 8)) + 'px';
  }
  function hpPlay(card){
    var kind = card.getAttribute('data-trailer-kind');
    var src = card.getAttribute('data-trailer');
    if (!src && !card.getAttribute('data-trailer-pending')){
      /* server-rendered cards carry no trailer attribute: resolve it from the
         post's [metadata] once, then future hovers play like any other card */
      var link0 = card.querySelector('.poster-media');
      var href0 = (link0 && link0.getAttribute('href')) || '';
      if (href0 && isPostUrl(href0)){
        card.setAttribute('data-trailer-pending', '1');
        postInfo(href0).then(function (d){
          var tr = d && d.rec && d.rec.trailer;
          if (tr && tr.src){
            card.setAttribute('data-trailer', tr.src);
            card.setAttribute('data-trailer-kind', tr.kind);
          }
        });
      }
    }
    if (hpEl) return;
    var link = card.querySelector('.poster-media');
    var href = (link && link.getAttribute('href')) || '';
    var img = link ? link.querySelector('img') : null;
    var titleEl = card.querySelector('.poster-title');
    var title = titleEl ? (titleEl.textContent || '').trim() : '';
    var metaEl = card.querySelector('.poster-sub');
    var meta = metaEl ? (metaEl.textContent || '').trim() : '';
    var label = card.getAttribute('data-label') || '';
    var year = card.getAttribute('data-year') || '';

    var panel = doc.createElement('div');
    panel.className = 'zd-hp';
    /* Netflix hovers always open: the trailer plays when the post has one,
       otherwise the card's own art fills the media box */
    var media;
    if (src){
      media = buildMutedTrailer({ kind: kind === 'video' ? 'video' : 'iframe', src: src }, 'zd-hp-video');
    } else {
      media = doc.createElement('span');
      media.className = 'zd-hp-video zd-hp-still';
      media.style.backgroundImage = 'url("' + (img ? img.getAttribute('src') : '') + '")';
    }
    panel.__media = media;
    panel.appendChild(media);
    panel.insertAdjacentHTML('beforeend',
      '<div class="zd-hp-acts">'
      + '<a class="zd-hp-btn is-primary" href="' + esc(href) + '" aria-label="Play"><i class="fa fa-play"></i></a>'
      + '<button class="zd-hp-btn zd-bm-addbtn" type="button" data-url="' + esc(href) + '" data-title="' + esc(title) + '" data-thumb="' + esc(img ? img.getAttribute('src') : '') + '" data-year="' + esc(year) + '" data-label="' + esc(label) + '" aria-label="My List"><i class="fa fa-plus"></i></button>'
      + '<button class="zd-hp-btn" type="button" aria-label="Like"><i class="fa fa-thumbs-up"></i></button>'
      + (src ? '<button class="zd-hp-mute" type="button" aria-label="Unmute trailer" aria-pressed="false"><i class="fa fa-volume-off"></i></button>' : '')
      + '<button class="zd-hp-btn is-expand" type="button" aria-label="More info"><i class="fa fa-chevron-down"></i></button>'
      + '</div>'
      + '<div class="zd-hp-info"><div class="zd-hp-meta">'
      + (label ? '<span>' + esc(label) + '</span>' : '')
      + (year ? '<span>' + esc(year) + '</span>' : '')
      + (meta ? '<span>' + esc(meta) + '</span>' : '')
      + '</div></div>');
    doc.body.appendChild(panel);
    hpEl = panel; hpCard = card;
    card.classList.add('is-hp');
    placeHp(panel, card);
    /* native video needs an explicit play() - the muted autoplay attribute is
       unreliable when the element is created detached from a user gesture */
    if (media.tagName === 'VIDEO'){ try { media.play(); } catch(e){} }
    if (window.requestAnimationFrame) window.requestAnimationFrame(function(){ panel.classList.add('is-open'); });
    else panel.classList.add('is-open');

    /* one control on the video itself: mute / unmute */
    var muteBtn = $('.zd-hp-mute', panel);
    if (muteBtn) muteBtn.addEventListener('click', function(ev){
      ev.preventDefault(); ev.stopPropagation();
      var m = panel.__media;
      var on = muteBtn.getAttribute('aria-pressed') === 'true';
      if (m && m.tagName === 'VIDEO'){
        m.muted = !on;
        if (!on && m.paused){ try { m.play(); } catch(e){} }
      } else if (m && m.tagName === 'IFRAME'){
        m.setAttribute('src', on ? src + (src.indexOf('?') > -1 ? '&' : '?') + 'mute=1' : src.replace(/[?&]mute=1/, ''));
      }
      muteBtn.setAttribute('aria-pressed', on ? 'false' : 'true');
      muteBtn.setAttribute('aria-label', on ? 'Unmute trailer' : 'Mute trailer');
      var ic = muteBtn.firstChild;
      if (ic) ic.className = on ? 'fa fa-volume-off' : 'fa fa-volume-up';
    });
    var ex = $('.zd-hp-btn.is-expand', panel);
    if (ex) ex.addEventListener('click', function(ev){ ev.preventDefault(); ev.stopPropagation(); openPreview(card); });
  }
  function initHoverPreview(){
    /* Deliberately not gated on '(hover: hover)': that query is unreliable in
       headless/embedded webviews. Touch devices never fire mouseover, and the
       stylesheet hides the panel under (hover:none), so a coarse-pointer check
       is enough. */
    if (window.matchMedia && window.matchMedia('(hover: none)').matches) return;
    doc.addEventListener('mouseover', function(e){
      var card = e.target && e.target.closest ? e.target.closest('.poster-card') : null;
      if (!card) return;
      if (card.contains(e.relatedTarget)) return;
      if (hpCloseTimer){ clearTimeout(hpCloseTimer); hpCloseTimer = null; }
      if (hpEl && hpEl.__card === card) return;
      hpKill();
      if (hpTimer) clearTimeout(hpTimer);
      hpTimer = setTimeout(function(){ hpTimer = null; hpPlay(card); }, 420);
    });
    doc.addEventListener('mouseout', function(e){
      var card = e.target && e.target.closest ? e.target.closest('.poster-card') : null;
      if (!card) return;
      if (e.relatedTarget && card.contains(e.relatedTarget)) return;
      if (hpTimer){ clearTimeout(hpTimer); hpTimer = null; }
      if (hpEl && hpCard === card && !hpCloseTimer){
        hpCloseTimer = setTimeout(function(){ hpCloseTimer = null; hpKill(); }, 220);
      }
    });
    /* scrolling or resizing under an open panel leaves it stranded, so drop it */
    window.addEventListener('scroll', function(){ if (hpEl) hpKill(); }, { passive: true });
    window.addEventListener('resize', function(){ if (hpEl) hpKill(); });
  }

  /* ---------------- hero billboard: trailer instead of the still --------------- */
  function heroTrailerUrl(){
    var hero = $('.hero');
    if (!hero) return '';
    var link = hero.querySelector('.hero-body a[href]');
    if (!link) return '';
    var href = (link.getAttribute('href') || '').split('#')[0];
    if (!/\/\d{4}\/\d{2}\//.test(href)) return '';
    return href;
  }
  function loadHeroTrailer(){
    var hero = $('.hero');
    if (!hero) return;
    var media = hero.querySelector('.hero-media');
    if (!media) return;
    var url = heroTrailerUrl();
    if (!url) return;
    /* the story, the meta line and the trailer all come from the post's
       [metadata]: the server snippet can leak the raw JSON, so the real Plot
       is written over it once the post is resolved */
    postInfo(url).then(function (d){
      if (d && d.meta){
        var m = d.meta;
        var syn = hero.querySelector('.hero-synopsis');
        var plot = na(m.Plot);
        if (syn && plot) syn.textContent = plot;
        var ttl = hero.querySelector('.hero-title a');
        if (ttl && na(m.Title)) ttl.textContent = na(m.Title);
        var hm = hero.querySelector('.hero-meta');
        if (hm){
          var parts = [];
          var tp = na(m.Type);
          if (tp) parts.push(tp.charAt(0).toUpperCase() + tp.slice(1));
          var gen = naList(m.Genre);
          if (gen.length) parts.push(gen[0]);
          var yr = naYear(m.Year);
          if (yr) parts.push(yr);
          var epsN = d.media && d.media.flat.length;
          if (epsN > 1) parts.push(epsN + ' Episodes');
          else if (na(m.Runtime)) parts.push(na(m.Runtime));
          if (na(m.Rated)) parts.push(na(m.Rated));
          if (parts.length){
            hm.innerHTML = parts.map(function (p){ return '<span class="hero-label">' + esc(p) + '</span>'; })
              .join('<span class="sep">\u2022</span>');
          }
        }
      }
      var raw = d && d.meta ? na(d.meta['yt-trailer']) : '';
      var id = raw ? ytId(raw) : '';
      if (!id) return;                        /* no trailer written -> keep the still */
      var still = media.querySelector('img');
      var ctl = ytTrailer(media, id, {
        title: (hero.querySelector('.hero-title a') || {}).textContent
          ? 'Trailer: ' + hero.querySelector('.hero-title a').textContent.trim()
          : 'Trailer',
        muted: true
      });
      if (!ctl) return;
      hero.classList.add('has-trailer', 'video-playing');
      media.classList.add('has-trailer');
      /* the still cross-fades out once the trailer is on screen */
      if (still) still.setAttribute('data-fade', '1');
    });
  }
  /* ---------------- bookmarks (My List) ---------------- */
  var BM_KEY = '__zamd_bookmarks__';
  function bookmarks(){ try { return JSON.parse(localStorage.getItem(BM_KEY) || '{}'); } catch(e){ return {}; } }
  function saveBookmarks(b){ try { localStorage.setItem(BM_KEY, JSON.stringify(b)); } catch(e){} updateBmUI(); }
  function isBooked(url){ return !!bookmarks()[url]; }
  function bookmarkToggle(r){
    var b = bookmarks();
    if (b[r.url]){ delete b[r.url]; }
    else { b[r.url] = r; }
    saveBookmarks(b);
    return !!b[r.url];
  }
  function buildBmPanel(){
    if ($('.zamd-bookmarks-panel')) return;
    var panel = doc.createElement('div');
    panel.className = 'zamd-bookmarks-panel';
    panel.setAttribute('role', 'dialog');
    panel.setAttribute('aria-label', 'My List');
    panel.setAttribute('aria-live', 'polite');
    panel.innerHTML = '<div class="zamd-bm-header"><h3><i class="fa fa-bookmark-o"></i> My List</h3>'
      +'<button class="zamd-bm-close" aria-label="Close"><i class="fa fa-times"></i></button></div>'
      +'<div class="zamd-bm-list"></div>';
    var backdrop = doc.createElement('div');
    backdrop.className = 'zamd-bm-backdrop';
    doc.body.appendChild(panel);
    doc.body.appendChild(backdrop);
    $('.zamd-bm-close', panel).addEventListener('click', function(){ closeBmPanel(); });
    backdrop.addEventListener('click', function(){ closeBmPanel(); });
    panel.addEventListener('click', function(e){
      if (e.target && e.target.closest('.zamd-bm-item-remove')){
        var it = e.target.closest('.zamd-bm-item');
        if (it){ bookmarkToggle({ url: it.getAttribute('data-url') }); renderBmList(); }
      }
    });
  }
  function renderBmList(){
    var list = $('.zamd-bm-list');
    if (!list) return;
    var b = bookmarks();
    var keys = Object.keys(b);
    if (!keys.length){
      list.innerHTML = '<div class="zamd-bm-empty">Your list is empty. Tap + on any title to add it.</div>';
      return;
    }
    list.innerHTML = keys.map(function(url){
      var r = b[url];
      return '<div class="zamd-bm-item" data-url="'+esc(url)+'">'
        +'<img src="'+esc(r.poster || r.thumb || '')+'" alt="">'
        +'<div class="zamd-bm-item-info">'
        +'<div class="zamd-bm-item-title"><a href="'+esc(url)+'">'+esc(r.title)+'</a></div>'
        +'<div class="zamd-bm-item-meta">'+esc(r.year || '')+(r.label ? ' \u2022 '+esc(r.label) : '')+'</div>'
        +'<button class="zamd-bm-item-remove" type="button">Remove</button>'
        +'</div></div>';
    }).join('');
  }
  function updateBmUI(){
    var count = Object.keys(bookmarks()).length;
    var el = $('.zamd-bm-count');
    if (el){ el.textContent = count; el.setAttribute('data-count', count); }
    syncBmButtons();
    if (C.bookmarks === false){ var btn = $('#zamd-bm-open'); if (btn) btn.style.display = 'none'; }
  }
  function openBmPanel(){ if (!$('.zamd-bookmarks-panel')) buildBmPanel(); renderBmList(); $('.zamd-bookmarks-panel').classList.add('is-open'); $('.zamd-bm-backdrop').classList.add('is-show'); }
  function closeBmPanel(){ var p = $('.zamd-bookmarks-panel'); if (p) p.classList.remove('is-open'); var b = $('.zamd-bm-backdrop'); if (b) b.classList.remove('is-show'); }
  function bindBm(){
    var bmBtn = $('#zamd-bm-open');
    if (bmBtn) bmBtn.addEventListener('click', function(){
      /* the panel does not exist until the first open, so it must be probed
         lazily - reading .classList on it before then threw and the button
         silently did nothing */
      var p = $('.zamd-bookmarks-panel');
      if (p && p.classList.contains('is-open')) closeBmPanel();
      else openBmPanel();
    });
    document.addEventListener('click', function(e){
      var btn = e.target && typeof e.target.closest === 'function' ? e.target.closest('.zd-bm-addbtn') : null;
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      var r = {
        url: btn.getAttribute('data-url') || '',
        title: btn.getAttribute('data-title') || '',
        thumb: btn.getAttribute('data-thumb') || '',
        year: btn.getAttribute('data-year') || '',
        label: btn.getAttribute('data-label') || ''
      };
      if (!r.url) return;
      var added = bookmarkToggle(r);
      updateBmUI();
      /* the reference card uses circular icon buttons, so the state is carried
         by the is-on ring plus the icon and the accessible label. Replacing
         innerHTML with text here used to strip the icon and reflow the row. */
      setBmState(btn, added);
    });
  }
  /* one place that knows how a "+" button looks when the title is in My List */
  var BM_PLUS = '<path d="M12 5v14M5 12h14"/>';
  var BM_CHECK = '<path class="ic-fill" d="M9.2 16.6 5 12.4l1.6-1.6 2.6 2.6 8.2-8.2L19 6.8z"/>';
  function setBmState(btn, added){
    if (!btn) return;
    btn.classList.toggle('is-on', !!added);
    btn.setAttribute('aria-pressed', added ? 'true' : 'false');
    btn.setAttribute('aria-label', added ? 'In My List' : 'My List');
    var svg = btn.querySelector('svg');
    if (svg) svg.innerHTML = added ? BM_CHECK : BM_PLUS;
  }
  /* keep every "+" button on the page in step with storage */
  function syncBmButtons(){
    $$('.zd-bm-addbtn').forEach(function (btn){
      setBmState(btn, isBooked(btn.getAttribute('data-url') || ''));
    });
  }

    /* ---------------- lightbox + pagination polish ---------------- */
  var lbOverlay;
  function highRes(src){
    src = String(src || '');
    if (/\/s72-c\//.test(src)) return src.replace(/\/s72-c\//, '/s1600/');
    var m = /=w\d+-h\d+-p-k-no-nu/.exec(src);
    if (m) return src.replace(m[0], '=w1600-h1600-p-k-no-nu');
    return src;
  }
  function buildLightboxBox(){
    if (lbOverlay) return;
    lbOverlay = doc.createElement('div');
    lbOverlay.className = 'zamd-lightbox';
    lbOverlay.setAttribute('role', 'dialog');
    lbOverlay.setAttribute('aria-modal', 'true');
    lbOverlay.setAttribute('aria-label', 'Image viewer');
    lbOverlay.innerHTML = '<button class="zamd-lightbox-close" type="button" aria-label="Close"><i class="fa fa-times"></i></button>'
      + '<figure class="zamd-lightbox-stage"><img class="zamd-lightbox-img" alt=""><figcaption class="zamd-lightbox-cap"></figcaption></figure>';
    doc.body.appendChild(lbOverlay);
    $('.zamd-lightbox-close', lbOverlay).addEventListener('click', closeLightbox);
    lbOverlay.addEventListener('click', function(e){ if (e.target === lbOverlay) closeLightbox(); });
  }
  function openLightbox(img){
    if (C.lightbox === false) return;
    buildLightboxBox();
    $('.zamd-lightbox-img', lbOverlay).src = highRes(img.getAttribute('src') || img.getAttribute('data-src') || '');
    var cap = img.getAttribute('title') || img.getAttribute('alt') || '';
    var capEl = $('.zamd-lightbox-cap', lbOverlay);
    capEl.textContent = cap;
    capEl.style.display = cap ? '' : 'none';
    lbOverlay.classList.add('is-active');
    body.classList.add('lightbox-open');
    doc.addEventListener('keydown', lbKey);
  }
  function closeLightbox(){
    if (!lbOverlay) return;
    lbOverlay.classList.remove('is-active');
    body.classList.remove('lightbox-open');
    doc.removeEventListener('keydown', lbKey);
  }
  function lbKey(e){ if (e.key === 'Escape') closeLightbox(); }
  function bindLightbox(){
    if (C.lightbox === false) return;
    doc.addEventListener('click', function(e){
      if (!e.target || typeof e.target.closest !== 'function') return;
      var img = e.target.closest('.post-body img');
      if (!img) return;
      e.preventDefault();
      openLightbox(img);
    });
  }
  function bindPager(){
    var pager = $('#blog-pager');
    if (!pager) return;
    var cur = $('.pager-cur', pager);
    if (!cur) return;
    var search = location.search || '';
    var max = parseInt((search.match(/[?&]max-results=(\d+)/) || [])[1], 10) || 12;
    var start = parseInt((search.match(/[?&]start-index=(\d+)/) || [])[1], 10) || 0;
    var page = start ? Math.floor((start - 1) / max) + 1 : 1;
    cur.textContent = String(page);
    cur.setAttribute('aria-label', 'Page ' + page);
  }
/* ---------------- search: the page itself becomes the results ----------------
   There is no dropdown under the field. Typing swaps the page's own content
   for the results grid, on every page that can show it (the watch page
   navigates on Enter instead). An empty, focused field shows the blog's most
   popular titles - read from the Trending widget Blogger already ranked, so
   the Layout settings (all-time / last week / count) govern the window.
   Layout options: topSearchesTitle, topSearchesCount, searchPlaceholder. */
  var SI_KEY = 'zamd_sidx_v1', SI_TTL = 600000, SI_MAX = 500;
  var searchIndex = null, searchIndexLoading = false;
  function usize(n){ return parseInt(n, 10) || 0; }

  function siStore(){
    try {
      var raw = sessionStorage.getItem(SI_KEY);
      if (raw){
        var p = JSON.parse(raw);
        if (p && p.d && p.t && ((new Date()).getTime() - p.t) < SI_TTL) return p.d;
      }
    } catch(e){}
    return null;
  }
  function siSave(d){ try { sessionStorage.setItem(SI_KEY, JSON.stringify({ t: (new Date()).getTime(), d: d })); } catch(e){} }

  function buildIndex(done){
    var cached = siStore();
    if (cached){ searchIndex = cached; done && done(true); return; }
    if (searchIndexLoading){
      var iv = setInterval(function(){
        if (!searchIndexLoading){ clearInterval(iv); done && done(!!searchIndex); }
      }, 120);
      return;
    }
    searchIndexLoading = true;
    var pages = [], total = 0;
    function finish(){
      searchIndexLoading = false;
      var all = [], seen = {};
      pages.forEach(function(list){ (list || []).forEach(function(x){ if (x && x.u && !seen[x.u]){ seen[x.u] = 1; all.push(x); } }); });
      all = all.slice(0, SI_MAX);
      if (all.length){ searchIndex = all; siSave(all); }
      done && done(!!searchIndex);
    }
    function page(start, cb){
      feed(BLOG + 'feeds/posts/summary?alt=json-in-script&max-results=150&start-index=' + start, function(json){
        var fd = (json && json.feed) || {};
        total = usize(fd.openSearch$totalResults && fd.openSearch$totalResults.$t) || total;
        pages.push(((fd.entry) || []).map(indexFromEntry));
        cb();
      });
    }
    page(1, function(){
      var extra = Math.min(3, Math.ceil((total || 150) / 150) - 1);
      if (extra <= 0){ finish(); return; }
      var doneN = 0;
      for (var k = 1; k <= extra; k++){
        (function(start){
          page(start, function(){ if (++doneN >= extra) finish(); });
        })(k * 150 + 1);
      }
    });
  }
  function indexFromEntry(e){
    var r = record(e);
    return { u: r.url, t: r.title, l: r.label, y: r.year, th: r.thumb, po: r.poster };
  }

  var nf = $('#nf-search');
  var nfOpen = $('#nf-search-open');
  var nfInput = $('#nf-search-input');
  var nfClear = $('#nf-search-clear');
  if (nfInput && C.searchPlaceholder) nfInput.setAttribute('placeholder', C.searchPlaceholder);
  var nfGrid = $('#nf-results-grid');
  var nfResTitle = $('#nf-results-title');
  var nfResCount = $('#nf-results-count');
  var nfSearchTimer = null;

  function nfValue(){ return nfInput ? nfInput.value.trim() : ''; }
  function skeletonGrid(host, n){
    if (!host) return;
    host.innerHTML = '';
    for (var i = 0; i < n; i++){
      var sk = doc.createElement('div');
      sk.className = 'skel-card';
      sk.setAttribute('aria-hidden', 'true');
      sk.style.setProperty('--skel-i', String(i));
      sk.innerHTML = '<div class="skel-media skel"></div><div class="skel-line skel"></div>';
      host.appendChild(sk);
    }
  }
  function indexCard(it){
    return card({
      url: it.u, title: it.t, labels: it.l ? [it.l] : [], label: it.l || '',
      year: it.y || '', date: '', thumb: it.th || ZD_NOIMG, poster: it.po || '',
      published: '', trailer: '', meta: null, media: null
    }, 'landscape');
  }
  function searchMatch(q){
    if (!searchIndex || !searchIndex.length) return [];
    var s = q.toLowerCase();
    var scored = [];
    for (var i = 0; i < searchIndex.length; i++){
      var it = searchIndex[i];
      var t = (it.t || '').toLowerCase();
      var l = (it.l || '').toLowerCase();
      var sc = 0;
      if (t.indexOf(s) === 0) sc = 6;
      else if (t.indexOf(' ' + s) > -1) sc = 5;
      else if (t.indexOf(s) > -1) sc = 4;
      else if (l.indexOf(s) === 0 || l.indexOf(' ' + s) > -1) sc = 3;
      else if (l.indexOf(s) > -1) sc = 2;
      if (sc) scored.push({ it: it, sc: sc });
    }
    scored.sort(function(a, b){ return b.sc - a.sc; });
    return scored.map(function(x){ return x.it; });
  }

  function renderResults(records, q){
    if (!nfGrid) return;
    nfGrid.innerHTML = '';
    if (nfResTitle) nfResTitle.textContent = 'Results for \u201c' + q + '\u201d';
    if (!records.length){
      if (nfResCount) nfResCount.textContent = '';
      var none = doc.createElement('div');
      none.className = 'nf-results-empty';
      none.textContent = 'No titles matched \u201c' + q + '\u201d.';
      nfGrid.appendChild(none);
      return;
    }
    if (nfResCount) nfResCount.textContent = records.length > 1 ? records.length + ' titles' : '1 title';
    records.slice(0, 48).forEach(function(it){ nfGrid.appendChild(indexCard(it)); });
    bindPreviewTriggers();
  }
  function runSearch(q){
    if (!nfGrid) return;
    body.classList.add('nf-taken-over');
    if (!searchIndex){
      if (nfResTitle) nfResTitle.textContent = 'Results for \u201c' + q + '\u201d';
      if (nfResCount) nfResCount.textContent = 'Searching\u2026';
      if (!nfGrid.children.length) skeletonGrid(nfGrid, 8);
      buildIndex(function(ok){ runSearch(q); });
      return;
    }
    renderResults(searchMatch(q), q);
  }
  function searchRelease(){
    if (!nfGrid || !body.classList.contains('nf-taken-over')) return;
    body.classList.remove('nf-taken-over');
    nfGrid.innerHTML = '';
    if (nfResTitle) nfResTitle.textContent = 'Results';
    if (nfResCount) nfResCount.textContent = '';
  }
  /* a q= param on a page Blogger served as something else - the mobile form
     can land on /?m=1/search?q=... - still shows results, never the home rows */
  function searchOverride(){
    if (!nfGrid) return false;
    if (body.classList.contains('view-single') || body.classList.contains('view-error')) return false;
    if ($('.catalog .poster-grid')) return false;   /* a real search page: catalogAll owns it */
    var m = (location.search || '').match(/[?&]q=([^&]*)/);
    if (!m){
      var joined = location.pathname.replace(/\+/g, ' ') + (location.search || '');
      m = joined.match(/q=([^&]*)/);
    }
    if (!m) return false;
    var q = '';
    try { q = decodeURIComponent(m[1].replace(/\+/g, ' ')).trim(); } catch (e) { q = m[1]; }
    if (!q || q.length < 2) return false;
    runSearch(q);
    if (nfInput){ nfInput.value = q; nf.classList.add('has-input'); }
    return true;
  }
  /* the magnifier opens the field on every page (the homepage pill is always
     visible); Escape or an outside click closes it again */
  function setNfSearch(open){
    if (!nf) return;
    nf.classList.toggle('is-open', !!open);
    if (open && nfInput && nfInput.focus) nfInput.focus();
  }
  function bindSearch(){
    if (!nfInput) return;
    /* Blogger's own searchUrl is unreliable on ?m=1 pages; submit to /search */
    var sform = $('#nf-search-form');
    if (sform) sform.setAttribute('action', BLOG + 'search');
    var zsform = $('.zd-search-form');
    if (zsform) zsform.setAttribute('action', BLOG + 'search');
    if (nfOpen) nfOpen.addEventListener('click', function(e){ e.preventDefault(); setNfSearch(true); });
    nfInput.addEventListener('input', function(){
      var v = nfValue();
      nf.classList.toggle('has-input', v.length > 0);
      if (nfSearchTimer) clearTimeout(nfSearchTimer);
      if (v.length < 2){
        searchRelease();
        return;
      }
      if (C.searchLive === false) return;
      if (body.classList.contains('view-post')) return;   /* Enter navigates instead */
      nfSearchTimer = setTimeout(function(){ runSearch(v); }, 60);
    });
    nfInput.addEventListener('keydown', function(e){
      if (e.key === 'Escape'){
        e.stopPropagation();
        if (nfInput) nfInput.blur();
        searchRelease();
        setNfSearch(false);
        return;
      }
      if (e.key === 'Enter'){
        e.preventDefault();
        var v = nfValue();
        if (v) window.location.href = BLOG + 'search?q=' + encodeURIComponent(v);
      }
    });
    if (nfClear) nfClear.addEventListener('click', function(){
      if (nfInput){ nfInput.value = ''; nfInput.focus(); }
      nf.classList.remove('has-input');
      searchRelease();
    });
    doc.addEventListener('click', function(e){
      if (!e.target || typeof e.target.closest !== 'function') return;
      /* results release when the click lands outside search + results */
      if (body.classList.contains('nf-taken-over') && nfValue()
          && !e.target.closest('#nf-search') && !e.target.closest('.nf-results')){
        searchRelease();
        if (nfInput){ nfInput.value = ''; nf.classList.remove('has-input'); }
        return;
      }
      /* the opened field closes too (non-home pages) */
      if (!body.classList.contains('view-home') && nf.classList.contains('is-open')
          && !e.target.closest('#nf-search')){
        setNfSearch(false);
      }
    });
  }

  /* ---------------- menu builder (underscore groups) ---------------- */
  function buildNavs(){
    var src = $('#main-menu-nav');
    if (!src) return;
    var items = Array.prototype.map.call(src.children, function(li){
      var a = li.querySelector('a');
      return {
        t: (a ? (a.textContent || '').trim() : (li.textContent || '').trim()),
        href: a ? (a.getAttribute('href') || '#') : '#'
      };
    });
    var groups = [];
    for (var k = 0; k < items.length; k++){
      var it = items[k];
      if (it.t.charAt(0) === '_'){
        var children = [];
        while (k + 1 < items.length && items[k + 1].t.charAt(0) !== '_'){
          children.push(items[k + 1]);
          k++;
        }
        groups.push(children.length ? { label: it.t.replace(/^_+/, ''), href: it.href, children: children } : { label: it.t.replace(/^_+/, ''), href: it.href, children: [] });
      } else {
        groups.push({ label: it.t, href: it.href, children: [] });
      }
    }
    function renderInto(ul){
      if (!ul) return;
      ul.innerHTML = '';
      groups.forEach(function(g){
        var li = doc.createElement('li');
        if (g.children.length){
          li.className = 'has-sub';
          var btn = doc.createElement('button');
          btn.type = 'button';
          btn.className = 'sub-toggle';
          btn.setAttribute('aria-haspopup', 'true');
          btn.setAttribute('aria-expanded', 'false');
          btn.textContent = g.label;
          var sub = doc.createElement('ul');
          sub.className = 'sub-menu';
          g.children.forEach(function(c){
            var cli = doc.createElement('li');
            var ca = doc.createElement('a');
            ca.href = c.href;
            ca.textContent = c.t.replace(/^_+/, '');
            cli.appendChild(ca);
            sub.appendChild(cli);
          });
          li.appendChild(btn);
          li.appendChild(sub);
          ul.appendChild(li);
        } else {
          var a = doc.createElement('a');
          a.href = g.href;
          a.textContent = g.label;
          if (g.href === '#' && g.label === 'My List'){ a.addEventListener('click', function(ev){ ev.preventDefault(); try { openBmPanel(); } catch(e){} }); }
          li.appendChild(a);
          ul.appendChild(li);
        }
      });
    }
    renderInto($('#menu-list'));
    renderInto($('#drawer-acc'));
$$('#drawer-acc li.has-sub > .sub-toggle, #menu-list li.has-sub > .sub-toggle').forEach(function(btn){
      btn.addEventListener('click', function(){
        var li = btn.parentNode;
        var open = li.classList.contains('is-open');
        var root = li.parentNode;
        $$('#drawer-acc li.has-sub, #menu-list li.has-sub').forEach(function(sib){
          if (sib.parentNode === root){
            sib.classList.remove('is-open');
            var sb = sib.querySelector('.sub-toggle');
            if (sb) sb.setAttribute('aria-expanded', 'false');
          }
        });
        li.classList.toggle('is-open', !open);
        btn.setAttribute('aria-expanded', !open ? 'true' : 'false');
      });
    });
  }

  /* ---------------- genre nav: resolve # links ---------------- */
  function fixGenreLinks(){
    $$('#menu-cat .genre-nav a').forEach(function(a){
      if ((a.getAttribute('href') || '').trim() === '#'){
        a.setAttribute('href', BLOG + 'search/label/' + encodeURIComponent((a.textContent || '').trim()));
      }
    });
  }

  /* ---------------- related posts ---------------- */
  function loadRelated(){
    var wrap = $('#related-wrap');
    if (!wrap) return;
    var tag = $('.related-ready .related-tag');
    if (!tag) return;
    var label = tag.getAttribute('data-label') || 'random';
    var active = window.__sora_active_post || {};
    function renderRelated(json){
      var list = $('#related-list');
      if (!list) return false;
      var entries = (json && json.feed && json.feed.entry) || [];
      var items = [];
      for (var i = 0; i < entries.length && items.length < 4; i++){
        var url = flink(entries[i]);
        if (active.url && url === active.url) continue;
        items.push(entries[i]);
      }
      if (!items.length) return false;
      items.forEach(function(en){ list.appendChild(card(record(en), 'poster')); });
      initRails();
      bindPreviewTriggers();
      return true;
    }
    function dropRelated(){
      if (wrap.parentNode) wrap.parentNode.removeChild(wrap);
    }
    feed(feedUrl({ label: label !== 'random' ? label : '', max: 6 }), function(json){
      if (renderRelated(json)) return;
      if (label && label !== 'random'){
        feed(feedUrl({ max: 6 }), function(json2){
          if (renderRelated(json2)) return;
          dropRelated();
        });
        return;
      }
      dropRelated();
    });
  }

  /* ---------------- next-title resolution for the player ----------------
     The post's own [media] playlist owns next/previous episode. When that
     playlist is exhausted, the control bar hands over to the next post
     sharing the current post's first label - the way Netflix rolls into the
     next title at the end of a season. */
  function resolveNextPost(){
    var cur = window.__sora_active_post;
    if (!cur || !cur.label) return;
    var pv = doc.querySelector('#detail-player-frame video');
    if (!pv || !pv.__zdPlayer || !pv.__zdPlayer.setNext) return;
    contentQuery({ source: 'label', label: cur.label, sort: 'oldest', count: 100 }, function(records){
      if (!records.length) return;
      var idx = -1;
      records.forEach(function(r, i){ if (r.url === cur.url) idx = i; });
      if (idx < 0) return;
      var next = idx < records.length - 1 ? records[idx + 1] : null;
      pv.__zdPlayer.setNext(next ? next.url : '');
    });
  }

  /* ---------------- scroll state (back-to-top removed) ---------------- */
  function onScroll(){
    var y = window.pageYOffset || doc.documentElement.scrollTop || 0;
    body.classList.toggle('is-scrolled', y > 30);
  }
  var ticking = false;
  window.addEventListener('scroll', function(){
    if (!ticking){ ticking = true; requestAnimationFrame(function(){ ticking = false; onScroll(); }); }
  }, { passive: true });

  /* ---------------- drawer ---------------- */
  var drawer = $('#drawer');
  var backdrop = $('#drawer-backdrop');
  var navToggle = $('#nav-toggle');
  var drawerClose = $('#drawer-close');
  function setDrawer(open){
    if (!drawer || !backdrop) return;
    drawer.classList.toggle('is-open', open);
    backdrop.classList.toggle('is-show', open);
    body.classList.toggle('drawer-locked', open);
    drawer.setAttribute('aria-hidden', open ? 'false' : 'true');
    if (navToggle) navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
    if (navToggle) navToggle.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
    if (!open && navToggle && drawer.contains(doc.activeElement)){ try { navToggle.focus(); } catch(e){} }
  }
  if (navToggle) navToggle.addEventListener('click', function(){ setDrawer(!drawer.classList.contains('is-open')); });
  if (drawerClose) drawerClose.addEventListener('click', function(){ setDrawer(false); });
if (backdrop) backdrop.addEventListener('click', function(){ setDrawer(false); });
  if (drawer) drawer.addEventListener('click', function(e){
    if (e.target && e.target.closest && e.target.closest('a')) setDrawer(false);
  });
  doc.addEventListener('keydown', function(e){
    if ((e.key === 'Escape' || e.key === 'Esc') && drawer.classList.contains('is-open')) setDrawer(false);
  });

/* ---------------- P6: homepage genre chips + active nav ---------------- */
    function genreChips(){
      var host = $('#genre-chips');
      if (!host) return;
      var render = function(items){
        var chips = '', count = 0;
        items.forEach(function(a){
          if (count >= 10) return;
          var href = (a.h || '').trim ? (a.h || '').trim() : '';
          var text = (a.t || '').trim ? (a.t || '').trim() : '';
          if (!href || href === '#' || !text) return;
          if (href.indexOf('/search/') === -1) return;
          chips += '<a class="chip" href="'+esc(href)+'">'+esc(text)+'</a>';
          count++;
        });
        host.innerHTML = chips;
        host.classList.toggle('is-empty', !chips);
        var zone = host.closest ? host.closest('.home-chips-zone') : null;
        if (zone) zone.style.display = chips ? '' : 'none';
      };
      var dom = [];
      $$('#menu-cat .genre-nav a').forEach(function(a){
        dom.push({ t: a.textContent || '', h: a.getAttribute('href') || '' });
      });
      var usable = dom.filter(function(x){ var h = (x.h || '').trim(); return h && h !== '#' && h.indexOf('/search/') > -1 && (x.t || '').trim(); });
      if (usable.length){ render(usable); return; }
      feed(BLOG + 'feeds/posts/summary?alt=json-in-script&max-results=0', function(json){
        var cats = (((json || {}).feed || {}).category) || [];
        var items = [];
        cats.forEach(function(c){ var t = (c && c.term) || ''; if (t) items.push({ t: t, h: BLOG + 'search/label/' + encodeURIComponent(t) }); });
        render(items.length ? items : dom);
      });
    }
  function activeNav(){
    var cur = location.pathname || '/';
    cur = cur.replace(/\/$/, '') || '/';
    $$('#menu-list a, #drawer-acc a, .genre-nav a, #genre-chips a').forEach(function(a){
      var href = (a.getAttribute('href') || '').trim();
      if (!href || href === '#') return;
      var h = href.split('#')[0].split('?')[0];
      var path = h.indexOf('://') > -1 ? h.replace(/^[a-z]+:\/\/[^/]*/i, '') : h;
      path = path.replace(/\/$/, '') || '/';
      var on = path === cur;
      if (!on && path.indexOf('/search/') === 0 && cur.indexOf(path) === 0) on = true;
      a.classList.toggle('is-active', on);
      if (on) a.setAttribute('aria-current', 'page');
    });
  }
/* ---------------- detail page: video-first watch hero ---------------- */
  var RESERVED_ALT = /(poster|banner|hide|dont-show)/i;
  /* ---- Pixeldrain ----
     https://pixeldrain.com/u/FILE_ID            -> https://cdn.pixeldrain.eu.cc/FILE_ID
     https://pixeldrain.com/api/file/FILE_ID      -> same
     https://cdn*.pixeldrain.eu.cc/api/file/ID    -> same (the /api/file/ path is
                                                      temporary and hotlink-blocks,
                                                      so it is always normalised)
     https://cdn.pixeldrain.eu.cc/FILE_ID         -> used as-is
     The cdn.pixeldrain.eu.cc/FILE_ID form is the stable *input* URL: it performs
     its own redirect to the playable resource. Never an iframe, never the
     pixeldrain.com webpage. */
  var PD_CDN = 'https://cdn.pixeldrain.eu.cc/';
  function pixeldrainId(u){
    var s = String(u || ''), m;
