     Custom HTML5 player
     ============================================================
     Plain DOM only, no framework. Wraps a native <video> and gives it
     Netflix-style chrome: big centred play/pause, a scrubbing bar with a
     buffered track and hover time preview, current + total time, volume,
     mute, playback speed, fullscreen, a buffering spinner, controls that
     fade while playing, click-to-toggle, and keyboard shortcuts.

     The video element itself NEVER gets the native `controls` attribute -
     every control below is ours, which is also what makes the mute-only
     billboard/hover previews possible.
  */
  var ZD_SPEEDS = [0.5, 0.75, 1, 1.25, 1.5];
  function fmtTime(s){
    s = (!isFinite(s) || s < 0) ? 0 : Math.floor(s);
    var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), x = s % 60;
    var mm = (m < 10 ? '0' : '') + m, ss = (x < 10 ? '0' : '') + x;
    return h ? h + ':' + mm + ':' + ss : mm + ':' + ss;
  }
  /* Thin-stroke SVG icons. The Font Awesome glyphs are far too heavy at
     control-bar size, which is what made the bar read as unfinished next to
     Netflix's - these are 24x24, stroked, and inherit currentColor. */
  var ZD_ICONS = {
    play:     '<path class="ic-fill" d="M7 4.5v15l13-7.5z"/>',
    pause:    '<path class="ic-fill" d="M6.5 4.5h4v15h-4zM13.5 4.5h4v15h-4z"/>',
    back10:   '<path d="M12 5V2.5L8 6l4 3.5V7a5.5 5.5 0 1 1-5.5 5.5"/><text x="12" y="15.4" text-anchor="middle" font-size="7" font-family="inherit" font-weight="700" fill="currentColor" stroke="none">10</text>',
    fwd10:    '<path d="M12 5V2.5L16 6l-4 3.5V7a5.5 5.5 0 1 0 5.5 5.5"/><text x="12" y="15.4" text-anchor="middle" font-size="7" font-family="inherit" font-weight="700" fill="currentColor" stroke="none">10</text>',
    volume:   '<path d="M4 9.5h3L11 6v12l-4-3.5H4z"/><path d="M14.5 9a4 4 0 0 1 0 6M17 6.5a7.5 7.5 0 0 1 0 11"/>',
    volumeLow:'<path d="M4 9.5h3L11 6v12l-4-3.5H4z"/><path d="M14.5 9a4 4 0 0 1 0 6"/>',
    mute:     '<path d="M4 9.5h3L11 6v12l-4-3.5H4z"/><path d="M15 9.5l5 5M20 9.5l-5 5"/>',
    next:     '<path class="ic-fill" d="M5 4.5v15l11-7.5z"/><path class="ic-fill" d="M17.5 4.5h2.5v15h-2.5z"/>',
    prevEp:   '<path class="ic-fill" d="M19 4.5v15L8 12z"/><path class="ic-fill" d="M4 4.5h2.5v15H4z"/>',
    nextEp:   '<path class="ic-fill" d="M5 4.5v15l11-7.5z"/><path class="ic-fill" d="M17.5 4.5h2.5v15h-2.5z"/>',
    episodes: '<rect x="3" y="4.5" width="12" height="9" rx="1.5"/><rect x="8" y="10.5" width="12" height="9" rx="1.5"/>',
    audio:    '<path d="M3 6.5A2.5 2.5 0 0 1 5.5 4h13A2.5 2.5 0 0 1 21 6.5v7a2.5 2.5 0 0 1-2.5 2.5H12l-4.5 4v-4h-2A2.5 2.5 0 0 1 3 13.5z"/><path d="M7 10h10M7 13h6"/>',
    speed:    '<path d="M4 17a9 9 0 1 1 16 0"/><path d="M12 12.5l4-3.5"/><circle class="ic-fill" cx="12" cy="13" r="1.4" stroke="none"/>',
    full:     '<path d="M4 9V4.5h5M20 9V4.5h-5M4 15v4.5h5M20 15v4.5h-5"/>',
    exitFull: '<path d="M9 4.5V9H4.5M15 4.5V9h4.5M9 19.5V15H4.5M15 19.5V15h4.5"/>',
    comments: '<path d="M3 6.5A2.5 2.5 0 0 1 5.5 4h13A2.5 2.5 0 0 1 21 6.5v7a2.5 2.5 0 0 1-2.5 2.5H12l-4.5 4v-4h-2A2.5 2.5 0 0 1 3 13.5z"/>',
    back:     '<path d="M14 5l-7 7 7 7"/>'
  };
  function icon(name){
    var body = ZD_ICONS[name] || '';
    return '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">' + body + '</svg>';
  }

  function zdPlayer(video, opts){
    opts = opts || {};
    if (video.__zdPlayer) return video.__zdPlayer;
    video.removeAttribute('controls');
    video.setAttribute('playsinline', '');
    video.setAttribute('preload', 'metadata');
    video.classList.add('zd-player-video');

    var root = doc.createElement('div');
    root.className = 'zd-player is-idle';
    var seekable = video.tagName === 'VIDEO';
    if (!seekable) root.classList.add('is-embed');

    var title = (opts.title || '').replace(/\s+/g, ' ').trim();

    root.innerHTML =
      '<div class="zd-player-main">'
      + '<div class="zd-player-stage"></div>'
      + '<div class="zd-player-spinner" aria-hidden="true"><span></span><span></span><span></span></div>'
      + '<button class="zd-player-big is-big-play" type="button" aria-label="Play">' + icon('play') + '</button>'
      + '<div class="zd-player-grad is-top"></div>'
      + '<div class="zd-player-grad is-bottom"></div>'
      + '<div class="zd-player-chrome">'
      +   '<div class="zd-player-scrubwrap">'
      +     '<div class="zd-player-scrub" role="slider" tabindex="0" aria-label="Seek" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0">'
      +       '<div class="zd-player-track"><div class="zd-player-buffered"></div><div class="zd-player-played"></div></div>'
      +       '<div class="zd-player-head"></div>'
      +       '<div class="zd-player-tip"></div>'
      +     '</div>'
      +     '<span class="zd-remain" aria-hidden="true">0:00</span>'
      +   '</div>'
      +   '<div class="zd-player-row">'
      +     '<div class="zd-player-group is-left">'
      +       '<button class="zd-pbtn is-play" type="button" aria-label="Play">' + icon('play') + '</button>'
      +       '<button class="zd-pbtn is-skip is-back10" type="button" aria-label="Back 10 seconds">' + icon('back10') + '</button>'
      +       '<button class="zd-pbtn is-skip is-fwd10" type="button" aria-label="Forward 10 seconds">' + icon('fwd10') + '</button>'
      +       '<div class="zd-volume">'
      +         '<button class="zd-pbtn is-mute" type="button" aria-label="Mute">' + icon('volume') + '</button>'
      +         '<input class="zd-vol" type="range" min="0" max="1" step="0.05" value="1" aria-label="Volume">'
      +       '</div>'
      +     '</div>'
      +     (title ? '<div class="zd-player-title" title="' + title.replace(/"/g, '&quot;') + '">' + title + '</div>' : '')
      +     '<div class="zd-player-group is-right">'
      +       (opts.episodes && opts.episodes.length > 1
                ? '<button class="zd-pbtn is-prevEp" type="button" aria-label="Previous episode" title="Previous episode">' + icon('prevEp') + '</button>'
                  + '<button class="zd-pbtn is-nextEp" type="button" aria-label="Next episode" title="Next episode">' + icon('nextEp') + '</button>'
                  + '<button class="zd-pbtn is-epsbtn" type="button" aria-label="Episodes" title="Episodes" aria-expanded="false">' + icon('episodes') + '</button>'
                : '')
      +       '<a class="zd-pbtn is-next"' + (opts.nextHref ? ' href="' + esc(opts.nextHref) + '"' : ' hidden aria-hidden="true"') + ' aria-label="Next episode" title="Next episode">' + icon('next') + '</a>'
      +       (opts.audioTrack ? '<button class="zd-pbtn is-audio" type="button" aria-label="Audio and subtitles">' + icon('audio') + '</button>' : '')
      +       '<div class="zd-speed"><button class="zd-pbtn is-speed" type="button" aria-label="Playback speed" aria-expanded="false">' + icon('speed') + '</button></div>'
      +       (opts.comments === false ? '' : '<button class="zd-pbtn is-comments" type="button" aria-label="Comments" aria-expanded="false">' + icon('comments') + '</button>')
      +       '<button class="zd-pbtn is-full" type="button" aria-label="Fullscreen">' + icon('full') + '</button>'
      +     '</div>'
      +   '</div>'
      + '</div>'
      + '</div>';

    /* the wrapper has to be inserted while `video` is still in place, otherwise
       appending the video into the stage first orphans it and insertBefore throws */
    if (video.parentNode) video.parentNode.insertBefore(root, video);
    else doc.body.appendChild(root);
    root.querySelector('.zd-player-stage').appendChild(video);

    var $r = function(s){ return root.querySelector(s); };
    var scrub = $r('.zd-player-scrub');
    var track = $r('.zd-player-track');
    var played = $r('.zd-player-played');
    var buffered = $r('.zd-player-buffered');
    var head = $r('.zd-player-head');
    var tip = $r('.zd-player-tip');
    var remainEl = $r('.zd-remain');
    var bigBtn = $r('.zd-player-big');
    var playBtn = $r('.is-play'), muteBtn = $r('.is-mute'), speedBtn = $r('.is-speed');
    var fullBtn = $r('.is-full'), commentsBtn = $r('.is-comments');
    var back10Btn = $r('.is-back10'), fwd10Btn = $r('.is-fwd10');
    var vol = $r('.zd-vol');

    var hideTimer = null, scrubbing = false, seekTo = 0;

    function setPlay(playing){
      playBtn.innerHTML = icon(playing ? 'pause' : 'play');
      playBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');
      bigBtn.innerHTML = icon(playing ? 'pause' : 'play');
      bigBtn.setAttribute('aria-label', playing ? 'Pause' : 'Play');
      root.classList.toggle('is-playing', playing);
      root.classList.toggle('is-idle', !playing);
    }
    function showChrome(){
      root.classList.remove('is-chrome-off');
      if (hideTimer) clearTimeout(hideTimer);
      if (!video.paused && !root.classList.contains('is-scrubbing')){
        hideTimer = setTimeout(function(){ root.classList.add('is-chrome-off'); }, 2600);
      }
    }
    function hideChrome(){ root.classList.add('is-chrome-off'); }
    function paint(){
      var d = (video.duration && isFinite(video.duration)) ? video.duration : 0;
      var now = scrubbing ? seekTo : video.currentTime;
      var p = d ? now / d : 0;
      played.style.width = (p * 100).toFixed(2) + '%';
      head.style.left = (p * 100).toFixed(2) + '%';
      /* Netflix shows only the time left, at the right end of the scrubber */
      remainEl.textContent = d ? fmtTime(Math.max(0, d - now)) : '0:00';
      scrub.setAttribute('aria-valuenow', Math.round(p * 100));
      try {
        if (video.buffered && video.buffered.length && d){
          var end = video.buffered.end(video.buffered.length - 1);
          buffered.style.width = ((end / d) * 100).toFixed(2) + '%';
        }
      } catch(e){}
      if (epsPanel && root.classList.contains('is-eps-open')){
        var curRow = $('.zd-eps-row.is-cur', epsPanel);
        if (curRow){
          var pr = $('.zd-eps-prog i', curRow);
          if (pr) pr.style.width = watchedPct().toFixed(1) + '%';
        }
      }
    }
    function skipBy(sec){
      if (!seekable) return;
      var d = video.duration || 0;
      var to = video.currentTime + sec;
      if (isFinite(d) && d) to = Math.max(0, Math.min(d - 0.25, to));
      else to = Math.max(0, to);
      try { video.currentTime = to; } catch(e){}
      showChrome();
    }
    function seekRatio(clientX){
      var r = track.getBoundingClientRect();
      if (!r.width) return 0;
      return Math.max(0, Math.min(1, (clientX - r.left) / r.width));
    }
    function commitSeek(ratio){
      var d = video.duration;
      if (!d || !isFinite(d)) return;
      try { video.currentTime = ratio * d; } catch(e){}
    }
    function toggle(){
      if (video.paused){ var pr = video.play(); if (pr && pr.catch) pr.catch(function(){}); }
      else video.pause();
    }

    /* ---- events ---- */
    bigBtn.addEventListener('click', function(e){ e.stopPropagation(); toggle(); showChrome(); });
    playBtn.addEventListener('click', function(e){ e.stopPropagation(); toggle(); showChrome(); });
    video.addEventListener('click', function(e){ e.stopPropagation(); toggle(); showChrome(); });
    if (back10Btn) back10Btn.addEventListener('click', function(e){ e.stopPropagation(); skipBy(-10); });
    if (fwd10Btn) fwd10Btn.addEventListener('click', function(e){ e.stopPropagation(); skipBy(10); });
    video.addEventListener('play', function(){ setPlay(true); showChrome(); });
    video.addEventListener('pause', function(){ setPlay(false); root.classList.remove('is-chrome-off'); });
    video.addEventListener('ended', function(){ setPlay(false); root.classList.remove('is-chrome-off'); });
    video.addEventListener('timeupdate', paint);
    video.addEventListener('progress', paint);
    video.addEventListener('durationchange', paint);
    video.addEventListener('waiting', function(){ root.classList.add('is-buffering'); });
    video.addEventListener('playing', function(){ root.classList.remove('is-buffering'); });
    video.addEventListener('canplay', function(){ root.classList.remove('is-buffering'); });
    video.addEventListener('error', function(){ root.classList.remove('is-buffering'); root.classList.add('is-error'); });
    video.addEventListener('volumechange', function(){
      var v = video.muted ? 0 : video.volume;
      vol.value = String(v);
      muteBtn.innerHTML = icon(v === 0 ? 'mute' : (v < .5 ? 'volumeLow' : 'volume'));
      muteBtn.setAttribute('aria-label', v === 0 ? 'Unmute' : 'Mute');
    });

    /* scrubbing */
    scrub.addEventListener('pointerdown', function(e){
      if (!seekable) return;
      scrubbing = true;
      root.classList.add('is-scrubbing');
      try { scrub.setPointerCapture(e.pointerId); } catch(err){}
      seekTo = seekRatio(e.clientX) * (video.duration || 0);
      paint();
      e.preventDefault(); e.stopPropagation();
    });
    scrub.addEventListener('pointermove', function(e){
      var d = video.duration || 0;
      var ratio = seekRatio(e.clientX);
      tip.textContent = fmtTime(ratio * d);
      tip.style.left = (ratio * 100).toFixed(2) + '%';
      if (!scrubbing) return;
      seekTo = ratio * d;
      paint();
    });
    scrub.addEventListener('pointerup', function(e){
      if (!scrubbing) return;
      scrubbing = false;
      root.classList.remove('is-scrubbing');
      commitSeek(seekRatio(e.clientX));
      showChrome();
      try { scrub.releasePointerCapture(e.pointerId); } catch(err){}
    });
    scrub.addEventListener('keydown', function(e){
      if (!seekable) return;
      var d = video.duration || 0;
      if (e.key === 'ArrowRight'){ video.currentTime = Math.min(d, video.currentTime + 5); }
      else if (e.key === 'ArrowLeft'){ video.currentTime = Math.max(0, video.currentTime - 5); }
      else return;
      e.preventDefault(); e.stopPropagation(); showChrome();
    });

    /* volume + mute */
    vol.addEventListener('input', function(){
      video.muted = false;
      video.volume = parseFloat(vol.value);
      showChrome();
    });
    muteBtn.addEventListener('click', function(e){ e.stopPropagation(); video.muted = !video.muted; showChrome(); });

    /* ---- playback speed: Netflix shows a rail of ticks with labels, not a
       plain dropdown list ---- */
    var speedMenu = null;
    function closeSpeed(){
      if (!speedMenu) return;
      speedMenu.parentNode && speedMenu.parentNode.removeChild(speedMenu);
      speedMenu = null;
      root.classList.remove('is-speed-open');
      speedBtn.setAttribute('aria-expanded', 'false');
    }
    if (speedBtn){
      speedBtn.addEventListener('click', function(e){
        e.stopPropagation();
        if (speedMenu){ closeSpeed(); showChrome(); return; }
        speedMenu = doc.createElement('div');
        speedMenu.className = 'zd-speed-menu';
        speedMenu.setAttribute('role', 'dialog');
        speedMenu.setAttribute('aria-label', 'Playback speed');
        var on = video.playbackRate;
        speedMenu.innerHTML =
            '<b class="zd-speed-title">Playback speed</b>'
          + '<div class="zd-speed-rail"><span class="zd-speed-rail-line"></span>'
          +   ZD_SPEEDS.map(function(s){
                return '<button type="button" data-s="' + s + '"' + (Math.abs(on - s) < .001 ? ' class="is-on" aria-checked="true"' : ' aria-checked="false"')
                     + ' aria-label="' + s + 'x"></button>';
              }).join('')
          + '</div>'
          + '<div class="zd-speed-legend">'
          +   ZD_SPEEDS.map(function(s){
                var lbl = (Math.abs(s - 1) < .001) ? '1x (Normal)' : s + 'x';
                return '<span' + (Math.abs(on - s) < .001 ? ' class="is-on"' : '') + '>' + lbl + '</span>';
              }).join('')
          + '</div>';
        speedMenu.addEventListener('click', function(ev){
          var b = ev.target.closest('button[data-s]');
          if (!b) return;
          video.playbackRate = parseFloat(b.getAttribute('data-s'));
          var val = video.playbackRate;
          $$('button[data-s]', speedMenu).forEach(function(x){
            var hit = Math.abs(parseFloat(x.getAttribute('data-s')) - val) < .001;
            x.classList.toggle('is-on', hit);
            x.setAttribute('aria-checked', hit ? 'true' : 'false');
          });
          $$('.zd-speed-legend span', speedMenu).forEach(function(x, i){
            x.classList.toggle('is-on', Math.abs(ZD_SPEEDS[i] - val) < .001);
          });
          speedBtn.classList.add('is-on');
          showChrome();
        });
        speedBtn.parentNode.appendChild(speedMenu);
        root.classList.add('is-speed-open');
        speedBtn.setAttribute('aria-expanded', 'true');
        showChrome();
      });
    }

    /* fullscreen */
    fullBtn.addEventListener('click', function(e){
      e.stopPropagation();
      var el = root;
      if (document.fullscreenElement) { if (document.exitFullscreen) document.exitFullscreen(); }
      else if (el.requestFullscreen) el.requestFullscreen();
      else if (el.webkitRequestFullscreen) el.webkitRequestFullscreen();
      showChrome();
    });

    /* ---- comments: a real section under the watch frame ----
       Disqus NEVER renders inside the player - an iframe measured against a
       hidden or flex-collapsed container is exactly what painted the thread
       over the video. The control-bar button leaves the fullscreen watch view
       (body.zd-show-comments): the frame drops to 16:9, the page unlocks and
       the existing #comments-panel section shows below the player, where
       Disqus embeds once, visibly, into its own #disqus_thread. Pressing
       again returns to the fullscreen view. */
    if (commentsBtn){
      commentsBtn.addEventListener('click', function(e){
        e.stopPropagation();
        var on = !body.classList.contains('zd-show-comments');
        body.classList.toggle('zd-show-comments', on);
        commentsBtn.setAttribute('aria-expanded', on ? 'true' : 'false');
        if (on){
          var panel = $('#comments-panel');
          if (panel){
            ensurePanelDisqus(panel);
            var y = panel.getBoundingClientRect().top + (window.pageYOffset || 0) - 84;
            try { window.scrollTo({ top: y, behavior: 'smooth' }); } catch (err) { window.scrollTo(0, y); }
          }
        }
        showChrome();
      });
    }
    /* Escape still closes the panels */
    doc.addEventListener('keydown', function(e){
      if (e.key === 'Escape'){
        if (speedMenu) closeSpeed();
        if (root.classList.contains('is-eps-open')) setEps(false);
      }
    });

    /* ---- episode playlist ----
       Every [video] block in the post is an entry. The player walks them with
       Next/Previous, and the label in the middle of the control bar becomes
       "<series> S1 E2: <episode title>", taken from the shortcode attributes. */
    var list = (opts.episodes || []).filter(function (e) { return e && e.src; });
    var epIndex = 0;
    var prevEpBtn = $r('.is-prevEp'), nextEpBtn = $r('.is-nextEp');
    var titleEl = $r('.zd-player-title');
    function setTitle(text){
      if (!titleEl) return;
      titleEl.textContent = text || '';
      if (text) titleEl.setAttribute('title', text);
    }
    function paintEpButtons(){
      if (prevEpBtn) prevEpBtn.disabled = epIndex <= 0;
      if (nextEpBtn) nextEpBtn.disabled = epIndex >= list.length - 1;
      root.classList.toggle('is-first-ep', epIndex <= 0);
      root.classList.toggle('is-last-ep', epIndex >= list.length - 1);
    }
    function gotoEpisode(i, play){
      if (!list.length) return;
      epIndex = Math.max(0, Math.min(list.length - 1, i));
      var ep = list[epIndex];
      try {
        if (video.tagName === 'VIDEO'){
          video.setAttribute('src', typeof ep.src === 'string' ? ep.src : ep.src.src);
          video.load();
          video.currentTime = 0;
        }
      } catch (e){}
      setTitle(ep.label);
      paintEpButtons();
      paintEps();
      if (play !== false && video.tagName === 'VIDEO'){
        var pr = video.play();
        if (pr && pr.catch) pr.catch(function () {});
      }
      showChrome();
    }
    if (prevEpBtn){
      prevEpBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        gotoEpisode(epIndex - 1);
      });
    }
    if (nextEpBtn){
      nextEpBtn.addEventListener('click', function (e) {
        e.stopPropagation();
        gotoEpisode(epIndex + 1);
      });
    }
    if (list.length){
      setTitle(list[0].label);
      paintEpButtons();
    }

    /* ---- episodes panel: the captured netflix.com player lists the season's
       episodes in a right-hand panel with a "Now Playing" row and a red
       progress line. Built lazily from the [media] playlist. ---- */
    var epsPanel = null;
    var epsBtn = $r('.is-epsbtn');
    function watchedPct(){
      var d = video.duration && isFinite(video.duration) ? video.duration : 0;
      return d ? Math.min(100, (video.currentTime / d) * 100) : 0;
    }
    function ensureEpsPanel(){
      if (epsPanel || !list.length) return;
      epsPanel = doc.createElement('div');
      epsPanel.className = 'zd-player-eps';
      epsPanel.setAttribute('aria-label', 'Episodes');
      var bySeason = {};
      list.forEach(function (ep, i){
        var key = ep.seasonLabel || ('Season ' + (ep.season || 1));
        (bySeason[key] = bySeason[key] || []).push({ i: i, ep: ep });
      });
      var keys = Object.keys(bySeason);
      var head = '<div class="zd-eps-head"><b>Episodes</b>';
      if (keys.length > 1){
        head += '<select class="zd-eps-select" aria-label="Season">'
          + keys.map(function (k, ix){
              return '<option value="' + esc(String(ix)) + '"' + (ix === 0 ? ' selected' : '') + '>' + esc(k) + '</option>';
            }).join('')
          + '</select>';
      }
      head += '</div><div class="zd-eps-body">';
      var body = keys.map(function (k, ix){
        return '<div class="zd-eps-group"' + (ix ? ' hidden' : '') + ' data-g="' + ix + '">'
          + '<div class="zd-eps-season">' + esc(k) + '</div>'
          + bySeason[k].map(function (row){
              return '<button class="zd-eps-row" type="button" data-i="' + row.i + '">'
                + '<span class="zd-eps-n">' + (row.ep.episode || (row.i + 1)) + '</span>'
                + '<span class="zd-eps-main"><span class="zd-eps-t">' + esc(row.ep.title || ('Episode ' + (row.ep.episode || row.i + 1))) + '</span>'
                + '<span class="zd-eps-prog"><i></i></span></span>'
                + '<span class="zd-eps-go"><svg viewBox="0 0 24 24" aria-hidden="true"><path class="ic-fill" d="M7 4.5v15l13-7.5z"/></svg></span>'
                + '</button>';
            }).join('')
          + '</div>';
      }).join('');
      epsPanel.innerHTML = head + body + '</div>';
      $r('.zd-player-main').appendChild(epsPanel);
      var sel = $('.zd-eps-select', epsPanel);
      if (sel){
        sel.addEventListener('change', function(){
          $$('.zd-eps-group', epsPanel).forEach(function (g){
            g.hidden = g.getAttribute('data-g') !== sel.value;
          });
        });
      }
      epsPanel.addEventListener('click', function (ev){
        var row = ev.target.closest && ev.target.closest('.zd-eps-row');
        if (row){ ev.stopPropagation(); gotoEpisode(parseInt(row.getAttribute('data-i'), 10) || 0); paintEps(); }
      });
      paintEps();
    }
    function paintEps(){
      if (!epsPanel) return;
      $$('.zd-eps-row', epsPanel).forEach(function (row){
        var on = parseInt(row.getAttribute('data-i'), 10) === epIndex;
        row.classList.toggle('is-cur', on);
        var prog = $('.zd-eps-prog i', row);
        if (prog) prog.style.width = on ? watchedPct().toFixed(1) + '%' : '0%';
      });
    }
    function setEps(open){
      if (open && !list.length) return;
      ensureEpsPanel();
      root.classList.toggle('is-eps-open', !!open);
      if (epsBtn) epsBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
      if (open) paintEps();
      showChrome();
    }
    if (epsBtn){
      epsBtn.addEventListener('click', function (e){
        e.stopPropagation();
        setEps(!root.classList.contains('is-eps-open'));
      });
    }

    /* ---- resume: pick up the episode and position the visitor left off at.
       The URL's ?ep=/?t= (info-card deep links) win, then Continue Watching
       storage. While watching, progress is written back every few seconds and
       on pause, so a reload or a later visit continues exactly in place. ---- */
    var resume = opts.resume || {};
    var resumeEp = intAttr(resume.ep);
    var resumeT = parseFloat(resume.t);
    if (resumeEp > 0 && resumeEp < list.length) gotoEpisode(resumeEp, false);
    if (resumeT && isFinite(resumeT) && resumeT > 5){
      var seekResume = function(){
        try {
          if (isFinite(video.duration) && video.duration) video.currentTime = Math.min(resumeT, Math.max(0, video.duration - 5));
          else video.currentTime = resumeT;
        } catch (e) {}
      };
      if (video.readyState >= 1) seekResume();
      else video.addEventListener('loadedmetadata', seekResume, { once: true });
    }
    var lastSave = 0;
    video.addEventListener('timeupdate', function(){
      var now = (new Date()).getTime();
      if (now - lastSave < 5000) return;
      lastSave = now;
      if (opts.onProgress && video.duration && video.currentTime > 3){
        try { opts.onProgress(epIndex, video.currentTime, video.duration); } catch (e) {}
      }
    });
    video.addEventListener('pause', function(){
      if (opts.onProgress && video.currentTime > 3){
        try { opts.onProgress(epIndex, video.currentTime, video.duration); } catch (e) {}
      }
    });

    /* chrome auto-hide */
    root.addEventListener('mousemove', showChrome);
    root.addEventListener('touchstart', showChrome, { passive: true });
    root.addEventListener('touchmove', showChrome, { passive: true });
    root.addEventListener('mouseleave', function(){ if (!video.paused) hideChrome(); });

    /* keyboard: only when focus is inside the player or on the body */
    root.addEventListener('keydown', function(e){
      var k = e.key;
      if (k === ' ' || k === 'k' || k === 'K'){ toggle(); e.preventDefault(); }
      else if (k === 'ArrowRight'){ if (seekable) video.currentTime = Math.min(video.duration || 0, video.currentTime + 5); e.preventDefault(); }
      else if (k === 'ArrowLeft'){ if (seekable) video.currentTime = Math.max(0, video.currentTime - 5); e.preventDefault(); }
      else if (k === 'l' || k === 'L'){ skipBy(10); e.preventDefault(); }
      else if (k === 'j' || k === 'J'){ skipBy(-10); e.preventDefault(); }
      else if (k === 'ArrowUp'){ video.muted = false; video.volume = Math.min(1, video.volume + 0.1); e.preventDefault(); }
      else if (k === 'ArrowDown'){ video.volume = Math.max(0, video.volume - 0.1); e.preventDefault(); }
      else if (k === 'm' || k === 'M'){ video.muted = !video.muted; e.preventDefault(); }
      else if (k === 'f' || k === 'F'){ fullBtn.click(); e.preventDefault(); }
      else if (/^[0-9]$/.test(k) && seekable && video.duration){
        video.currentTime = video.duration * (parseInt(k, 10) / 10); e.preventDefault();
      } else return;
      showChrome();
    });
    root.tabIndex = 0;

    /* swap the fullscreen glyph with the exit glyph while it is active */
    var onFs = function(){
      var on = !!(document.fullscreenElement || document.webkitFullscreenElement);
      fullBtn.innerHTML = icon(on ? 'exitFull' : 'full');
      fullBtn.setAttribute('aria-label', on ? 'Exit fullscreen' : 'Fullscreen');
    };
    doc.addEventListener('fullscreenchange', onFs);
    doc.addEventListener('webkitfullscreenchange', onFs);

    setPlay(true);
    paint();
    var nextEl = $r('.is-next');
    video.__zdPlayer = {
      root: root, video: video, show: showChrome, toggle: toggle,
      episodes: list,
      goEpisode: gotoEpisode,
      episodeIndex: function () { return epIndex; },
      /* the series feed resolves after the player is built, so the Next button
         is created hidden and switched on here */
      setNext: function(href){
        if (!nextEl) return;
        if (href){ nextEl.setAttribute('href', href); nextEl.hidden = false; nextEl.removeAttribute('aria-hidden'); }
        else { nextEl.hidden = true; nextEl.setAttribute('aria-hidden', 'true'); }
      }
    };
    return video.__zdPlayer;
  }

  /* ============================================================
     Shortcode -> episode list
     ============================================================
     Every [video] block in the post becomes one entry in the post's playlist.
     An entry may carry attributes:
       [video season="1" episode="2" title="Cat's in the Bag"]
       https://example.com/episode-2.mp4
       [/video]
     and a bare [video]url[/video] is simply a one-entry playlist, which is what
     a movie is.

     The blocks are DATA, not content: they are cut out of the body and the
     author's prose around them is left untouched. The first entry is promoted
     into the watch hero; the player then walks the rest with next/previous. */
  function collectShortcodeVideos(body){
    var found = [];
    var walker = doc.createTreeWalker(body, 4, null);
    var t;
    while ((t = walker.nextNode())){
      var p = t.parentNode;
      if (!p || p.tagName === 'A' || p.tagName === 'SCRIPT' || p.tagName === 'STYLE') continue;
      var text = t.nodeValue || '';
      if (!text || text.indexOf('[') < 0) continue;
      var re = new RegExp(VIDEO_SC.source, 'gi');
      var m;
      while ((m = re.exec(text))){
        found.push({
          tag: m[1], m: m, start: m.index, end: m.index + m[0].length,
          wrap: p, text: t
        });
      }
      if (found.length) break;   /* one text node per pass keeps offsets valid */
    }
    return found;
  }
  function buildEpisodeList(body){
    var list = [];
    /* peel one at a time so each text node's offsets stay valid */
    for (var guard = 0; guard < 60 && list.length < 60; guard++){
      var hits = collectShortcodeVideos(body);
      if (!hits.length) break;
      var h = hits[0];
      var parsed = parseVideoShortcode(h.m);
      var src = scResolve(h.tag, parsed.url);
      /* cut the shortcode text first, so prose on either side is never disturbed */
      cutFromText(h.text, h.start, h.end);
      pruneEmpty(h.wrap, body);
      if (!src) continue;
      var season = intAttr(parsed.attrs.season);
      var episode = intAttr(parsed.attrs.episode);
      list.push({
        src: src,
        season: season,
        episode: episode,
        title: (parsed.attrs.title || '').trim(),
        label: episodeLabel('', { season: season, episode: episode, title: (parsed.attrs.title || '').trim() })
      });
    }
    return list;
  }

  /* Cut the [metadata]/[media] blocks out of the rendered post body, parse
     them and hand them back. Blogger's compose view may wrap a pasted block
     in one container, split it across sibling lines, or keep it in a single
     text node - all three shapes are handled, and the blocks never survive
     to be read as content. */
  var DATA_PAIR_RE = /\[\s*(metadata|media)\s*\]([\s\S]*?)\[\s*\/\s*\1\s*\]/ig;
  function absorbDataBlocks(text, out){
    var re = new RegExp(DATA_PAIR_RE.source, 'ig'), m;
    while ((m = re.exec(String(text || '')))){
      var json = jsonLoose(decodeEntities(m[2]));
      if (String(m[1]).toLowerCase() === 'metadata'){
        var pm = parseMetaJson(json);
        if (pm) out.meta = pm;
      } else {
        var nm = normalizeMedia(json);
        if (nm) out.media = nm;
      }
      out.hit = true;
    }
  }
  function collectDataBlocks(rootEl){
    var out = { meta: null, media: null, hit: false };
    if (!rootEl || !doc.createTreeWalker) return out;
    /* 1) one container element holding the whole block (compose view) */
    $$('pre,div,p,span', rootEl).slice(0, 400).forEach(function (el){
      if (!el.parentNode) return;
      if (el.querySelector('img,iframe,video,a,button')) return;
      var txt = el.textContent || '';
      if (!DATA_PAIR_RE.test(txt)) return;
      DATA_PAIR_RE.lastIndex = 0;
      absorbDataBlocks(txt, out);
      el.parentNode.removeChild(el);
    });
    /* 2) a single text node holding a complete pair (HTML view) */
    var nodes = [], w = doc.createTreeWalker(rootEl, 4, null), t;
    while ((t = w.nextNode())) nodes.push(t);
    nodes.forEach(function (node){
      var text = node.nodeValue || '';
      if (!text || text.indexOf('[') < 0) return;
      var re = new RegExp(DATA_PAIR_RE.source, 'ig'), m, cuts = [];
      while ((m = re.exec(text))){
        absorbDataBlocks(m[0], out);
        cuts.push([m.index, m.index + m[0].length]);
      }
      for (var i = cuts.length - 1; i >= 0; i--) cutFromText(node, cuts[i][0], cuts[i][1]);
    });
    /* 3) a block Blogger split across sibling lines: the opener's nearest
          ancestor that also holds the closer is dropped wholesale */
    if (!out.hit){
      var w2 = doc.createTreeWalker(rootEl, 4, null), tn;
      while ((tn = w2.nextNode())){
        var sn = tn.nodeValue || '';
        var om = /\[\s*(metadata|media)\s*\]/i.exec(sn);
        if (!om) continue;
        var anc = tn.parentNode, depth = 0, target = null;
        while (anc && anc !== rootEl && depth < 6){
          if (anc.querySelector && anc.querySelector('img,iframe,video,a,button')) break;
          var at = anc.textContent || '';
          if (DATA_PAIR_RE.test(at)){
            DATA_PAIR_RE.lastIndex = 0;
            target = anc;
            break;
          }
          anc = anc.parentNode;
          depth++;
        }
        if (target && target !== rootEl && target.parentNode){
          absorbDataBlocks(target.textContent, out);
          target.parentNode.removeChild(target);
        }
        break;
      }
    }
    return out;
  }

  function buildPlayer(){
    var player = $('#detail-player');
    if (!player) return;
    var frame = $('#detail-player-frame');
    var body = $('#post-body') || $('.post-body');
    if (!frame || !body) return;

    /* the post's own [metadata]/[media] shortcodes are the primary source;
       they are parsed and cut out of the body here, so the JSON can never
       flash on screen and the player builds around [media] */
    var data = collectDataBlocks(body);
    var curUrl = (window.__sora_active_post && window.__sora_active_post.url) || location.href.split('#')[0];
    if (curUrl) rememberPost(curUrl, data.meta, data.media, null);

    var got = null;
    var episodes = [];
    /* 1) the [media] shortcode IS the playlist - seasons and episode names in
          the order the author wrote them */
    if (data.media && data.media.flat.length){
      episodes = data.media.flat;
    }
    /* 2) legacy [video] blocks still parse as a one-season playlist */
    if (!episodes.length) episodes = buildEpisodeList(body);
    if (episodes.length){
      got = { node: makeVideoNode(episodes[0].src) };
    }
    /* 3) otherwise fall back to an existing <video>/iframe, a bare shortcode, or a link */
    if (!got) got = scanBodyForVideo(body) || scanTextForVideo(body) || scanLinksForVideo(body);

    if (got && got.node && frame){
      frame.appendChild(got.node);
      if (got.wrap && got.wrap !== frame) pruneEmpty(got.wrap, body);
      player.classList.add('has-player');
      setHeroEmpty(false);
      /* the display base: the post's [metadata] Title first, then the scrubbed
         post title, so the control bar reads "Breaking Bad S1 E1: Cats Black Day" */
      var postTitle = (function(){
        var t = $('.detail-title') || $('.post-title') || $('h1.entry-title') || $('h1');
        if (t && (t.textContent || '').trim()) return t.textContent.trim();
        return (doc.title || '').replace(/\s*\|\s*.*$/, '').trim();
      })();
      var ent = entertainmentName(postTitle);
      var base = (data.meta && na(data.meta.Title)) || ent.title;
      var named = episodes.map(function(ep){
        return {
          src: ep.src, season: ep.season, episode: ep.episode, title: ep.title,
          seasonLabel: ep.seasonLabel || ('Season ' + (ep.season || 1)),
          label: episodeLabel(base, ep)
        };
      });
      /* the title sits in the middle of the control bar, Netflix style */
      var shown = named.length > 1
        ? named[0].label
        : ((data.meta && na(data.meta.Title)) || ent.clean || base);
      /* resume: the info-card deep link (?ep=/?t=) first, then Continue
         Watching storage for this exact post */
      var resume = { ep: 0, t: 0 };
      var epm = location.search.match(/[?&]ep=(\d+)/);
      var tm = location.search.match(/[?&]t=(\d+)/);
      if (epm) resume.ep = parseInt(epm[1], 10);
      if (tm) resume.t = parseInt(tm[1], 10);
      if (!resume.ep && !resume.t){
        var cwList = cwGet();
        for (var ci = 0; ci < cwList.length; ci++){
          if (normUrl(cwList[ci].url) === normUrl(curUrl) && (cwList[ci].ep || cwList[ci].t)){
            resume.ep = cwList[ci].ep || 0;
            resume.t = cwList[ci].t || 0;
            break;
          }
        }
      }
      var seriesOpts = {
        title: shown, episodes: named, seriesName: base,
        resume: named.length > 1 ? resume : (resume.t ? resume : null),
        onProgress: function (epIdx, t, dur){
          var ep = named[epIdx] || {};
          cwProgress(curUrl, { ep: epIdx, epLabel: ep.label || '', t: t, dur: dur });
        }
      };
      if (got.node.tagName === 'VIDEO') zdPlayer(got.node, seriesOpts);
      /* any further <video> the author placed by hand still gets the chrome,
         but with the episode controls hidden so the two do not fight */
      $$('video, iframe', body).forEach(function(v){
        if (v.tagName === 'VIDEO' && v !== got.node) zdPlayer(v, { comments: false, title: shown });
      });
      window.__zamd_episodes = named;
    } else {
      player.classList.add('is-empty');
      setHeroEmpty(true);
    }
  }
  /* reserved poster/banner alt images: hidden on post pages only.
     The landscape marker is deliberately exempt: "landscape-poster" and
     "land-post" are how the author says "this is the wide artwork", so those
     two are kept and published to the card as its 16:9 media. */
  function hideReservedImages(){
    if (!$('#detail-player')) return;
    var root = $('.detail-entry') || $('#post-body');
    if (!root) return;
    var imgs = $$('img', root);
    for (var i = 0; i < imgs.length; i++){
      var alt = imgs[i].getAttribute('alt') || '';
      if (LAND_ALT.test(alt) && !/hide|dont-show/i.test(alt)) continue;
      if (RESERVED_ALT.test(alt) && imgs[i].parentNode) imgs[i].parentNode.removeChild(imgs[i]);
    }
    /* the landscape image is the post's own wide artwork: hand it to the
       player hero and the info card, and hide it from the body so it is not
       shown twice */
    var land = findLandscapeImage(root);
    if (land){
      var src = land.getAttribute('src') || '';
      var post = window.__sora_active_post;
      if (post){ post.landscape = src; }
      var hero = $('.detail-hero-media');
      if (hero && !hero.querySelector('img')){
        var im = doc.createElement('img');
        im.className = 'hero-img';
        im.alt = '';
        im.src = src;
        hero.appendChild(im);
      }
      if (land.parentNode) land.parentNode.style.display = 'none';
    }
  }
  function tryPlayVideo(){
    var frame = $('#detail-player-frame');
    if (!frame) return false;
    var v = frame.querySelector('video');
    if (v){ try { v.play(); } catch(e){} return true; }
    var f = frame.querySelector('iframe');
    if (!f) return false;
    var s = f.getAttribute('src') || '';
    try {
      if (/enablejsapi=1/.test(s)){
        var msg = /vimeo/.test(s) ? JSON.stringify({ method:'play' })
          : JSON.stringify({ event:'command', func:'playVideo', args:'' });
        f.contentWindow.postMessage(msg, '*');
        return true;
      }
      if (/youtube|youtu\.be|vimeo|dailymotion/i.test(s)){
        f.setAttribute('src', s + (s.indexOf('?') > -1 ? '&' : '?') + 'enablejsapi=1&autoplay=1');
        return true;
      }
    } catch(e){}
    return true;
  }
  function playScroll(){
    var target = $('#detail-player');
    if (target && !target.classList.contains('is-empty')){
      var y = target.getBoundingClientRect().top + window.pageYOffset - 76;
      window.scrollTo({ top: y, behavior: 'smooth' });
      return true;
    }
    return false;
  }
  doc.addEventListener('click', function(e){
    if (e.target && typeof e.target.closest === 'function' && e.target.closest('.detail-play')){
      var a = e.target.closest('.detail-play');
      e.preventDefault();
      tryPlayVideo();
      if (!playScroll()){
        var target = $('#sora-video-details, #video-player, .video-details-bar, #moviedownloadlinks, .post-videoWrapper');
        if (target){
          var y = target.getBoundingClientRect().top + window.pageYOffset - 76;
          window.scrollTo({ top: y, behavior: 'smooth' });
        } else {
          window.location.href = a.getAttribute('href') || window.location.href;
        }
      }
}
  });

  /* Disqus embeds once, into the thread's own visible container in the page
     flow - never into anything the player flexes, so it can always measure */
  function ensurePanelDisqus(panel){
    if (!panel || panel.getAttribute('data-disqus-on') === '1') return;
    panel.setAttribute('data-disqus-on', '1');
    var shortname = panel.getAttribute('data-disqus-shortname') || 'zamindrive';
    var url = panel.getAttribute('data-disqus-url') || (location.protocol + '//' + location.host + location.pathname);
    window.disqus_config = function () {
      this.page.url = url;
      this.page.identifier = url;
    };
    window.disqus_shortname = shortname;
    window.disqus_url = url;
    window.disqus_identifier = url;
    var s = doc.createElement('script');
    s.src = 'https://' + shortname + '.disqus.com/embed.js'
      + '?background_color=141414&text_color=e5e5e5&link_color=e50914&brand_color=181818';
    s.setAttribute('data-timestamp', String(+new Date()));
    (doc.head || doc.body).appendChild(s);
  }

  /* Blogger can close *new* comments while still showing existing ones. Disqus
     has no per-thread lock, so its form is hidden once it renders and a notice
     is shown instead - the only way to honour the setting on Disqus. */
  function respectCommentSettings(){
    var sec = $('#comments-panel');
    if (!sec || sec.getAttribute('data-allow-new') === '1') return;
    var tries = 0;
    var apply = function(){
      var forms = $$('#disqus_thread form, #disqus_thread #dsq-form');
      if (!forms.length) return false;
      forms.forEach(function(f){ f.style.display = 'none'; });
      if (!$('.comments-closed-note.is-live')){
        var n = doc.createElement('div');
        n.className = 'comments-closed-note is-live';
        n.textContent = 'New comments are closed for this post.';
        sec.appendChild(n);
      }
      return true;
    };
    /* Disqus is only embedded once the reader opens the comments bar, which can
       be long after load, so poll generously and also re-run whenever the bar
       appears - otherwise a closed thread could keep its form. */
    var watch = function(){
      if (tries++ > 60) return;                    /* ~24s, well past a click */
      if (!$('#disqus_thread') || !apply()){ setTimeout(watch, 400); return; }
    };
    watch();
    doc.addEventListener('zamd:comments-open', apply);
  }

  /* Blogger static Pages resolve to /p/slug.html, posts to /YYYY/MM/slug. CSS
     already hides them so they never flash; this sweeps them out of any grid
     Blogger rendered server-side (home, search, label, archive). */
  function dropStaticPages(){
    var removed = 0;
    $$('.poster-card').forEach(function(card){
      var a = card.querySelector('a[href]');
      if (!a) return;
      var href = (a.getAttribute('href') || '').split('#')[0];
      if (!href || isPostUrl(href)) return;
      /* only treat it as a Page when it really looks like one */
      if (/\/p\/[^/]+\.html?$/.test(href) || /\/p\/[^/]+\/?$/.test(href)){
        if (card.parentNode){ card.parentNode.removeChild(card); removed++; }
      }
    });
    return removed;
  }

  /* ---------------- navigation gate: the red loader between pages ----------------
     Shown only while the browser is actually unloading to another document, so
     opening the info card, changing a season or pressing an in-page control
     never flashes it. It is torn down on pageshow because a back/forward
     navigation can be cancelled and the visitor would be left staring at it. */
  var gateArmed = false;
  function navigationGate(){
    if (gateArmed) return;
    gateArmed = true;
    var g = $('.zamd-gate');
    if (!g){
      g = doc.createElement('div');
      g.className = 'zamd-gate';
      g.setAttribute('role', 'status');
      g.setAttribute('aria-live', 'polite');
      g.setAttribute('aria-label', 'Loading');
      g.innerHTML = '<div class="zamd-gate-inner">'
        + '<span class="zamd-gate-mark">ZaminDrive</span>'
        + '<span class="zamd-gate-bar"><i></i></span>'
        + '</div>';
      doc.body.appendChild(g);
    }
    g.classList.add('is-on');
  }
  function navigationGateArm(){
    if (gateArmed) return;
    gateArmed = true;
    doc.addEventListener('click', function (e){
      var a = e.target && typeof e.target.closest === 'function'
        ? e.target.closest('a[href]') : null;
      if (!a) return;
      /* only a real document navigation gets the loader */
      if (a.target === '_blank' || a.hasAttribute('download')) return;
      var href = a.getAttribute('href') || '';
      if (!href || href.charAt(0) === '#' || /^(javascript|mailto|tel):/i.test(href)) return;
      if (a.hostname && a.hostname !== location.hostname) return;
      navigationGate();
    }, true);
    /* if the navigation is abandoned (bfcache restore, hash change, a blocked
       request) the page comes back with the loader still up */
    window.addEventListener('pageshow', function () {
      gateArmed = false;
      var g = $('.zamd-gate');
      if (g) g.classList.remove('is-on');
    });
  }

  /* Netflix-style watch view: the only chrome is a back button top left, which
     returns the reader to wherever they came from (falling back to the blog). */  function postBackButton(){
    if (!body.classList.contains('view-post')) return;
    if ($('#zamd-back')) return;
    var b = doc.createElement('button');
    b.id = 'zamd-back';
    b.type = 'button';
    b.className = 'zamd-back';
    b.setAttribute('aria-label', 'Go back');
    b.innerHTML = '<i class="fa fa-angle-left"></i><span>Back</span>';
    b.addEventListener('click', function(){
      navigationGate();
      var n = 0;
      try { n = (window.history && window.history.length) ? window.history.length : 0; } catch(e){}
      if (n > 1) window.history.back();
      else window.location.href = BLOG;
    });
    doc.body.appendChild(b);
  }

  /* ---------------- theme mode / layout gating ---------------- */
  function applyMode(){
    var root = doc.documentElement;
    var mode = C.darkMode || 'dark';
    if (mode === 'system'){
      var mq = window.matchMedia && window.matchMedia('(prefers-color-scheme: light)');
      var set = function(){ root.setAttribute('data-mode', (mq && mq.matches) ? 'light' : 'dark'); };
      set();
      if (mq && mq.addEventListener) mq.addEventListener('change', set);
    } else {
      root.setAttribute('data-mode', mode === 'light' ? 'light' : 'dark');
    }
    body.classList.toggle('zamd-boxed', C.boxedLayout === true);
    body.classList.toggle('zamd-fixed-sidebar', C.fixedSidebar === true);
    var bt = $('#back-top');
    if (bt) bt.style.display = (C.backToTop === false) ? 'none' : '';
  }

  /* ---------------- cookie consent ---------------- */
  var COOKIE_KEY = '__zamd_consent__';
  var cookieBuilt = false;
  function buildCookieBar(){
    if (cookieBuilt || $('.zamd-cookie-bar')) return;
    cookieBuilt = true;
    var bar = doc.createElement('div');
    bar.className = 'zamd-cookie-bar';
    bar.innerHTML = '<p>We use cookies to personalize content and analyze site traffic. By continuing you agree to our cookie policy.</p>'
      +'<button class="zamd-cookie-accept" type="button">Accept</button>';
    doc.body.appendChild(bar);
    $('.zamd-cookie-accept', bar).addEventListener('click', function(){
      try { localStorage.setItem(COOKIE_KEY, '1'); } catch(e){}
      bar.classList.remove('is-show');
    });
    bar.classList.add('is-show');
  }
  function setUpCookie(){
    if (C.cookieConsent === true){
      var ok = false;
      try { ok = !!localStorage.getItem(COOKIE_KEY); } catch(e){}
      if (!ok) buildCookieBar();
    }
  }

  /* ---------------- real view counter (Firebase RTDB) ---------------- */
  function setUpViews(){
    if (C.viewsCounter !== true) return;
    if (!C.firebaseDatabaseURL || !C.firebaseApiKey) return;
    var DB = C.firebaseDatabaseURL.replace(/\/+$/, '');
    var nodes = $$('.zamd-views');
    if (!nodes.length) return;
    var path = (location.pathname + (location.search ? '?' + location.search : '')).replace(/[^a-zA-Z0-9\/\-\_\.\?\=]/g, '') || '/';
    var key = 'page-' + path;
    var seen = false;
    try { seen = !!sessionStorage.getItem(key); } catch(e){}
    function render(count){
      nodes.forEach(function(el){
        el.classList.add('has-count');
        el.setAttribute('data-label', String(count) + ' views');
        el.innerHTML = '<i class="fa fa-eye"></i><span>' + count + '</span>';
      });
    }
    var script = doc.createElement('script');
    script.src = 'https://www.gstatic.com/firebasejs/10.13.2/firebase-app.js';
    script.onload = function(){
      var dbScript = doc.createElement('script');
      dbScript.src = 'https://www.gstatic.com/firebasejs/10.13.2/firebase-database.js';
      dbScript.onload = function(){
        try {
          var app = firebase.initializeApp({ apiKey: C.firebaseApiKey, databaseURL: DB }, 'zamd');
          var db = firebase.database(app);
          var ref = db.ref('sora-views/' + encodeURIComponent(path));
          ref.once('value', function(snap){
            var n = (snap.val() && snap.val().count) || 0;
            if (!seen){
              ref.set({ count: n + 1 });
              try { sessionStorage.setItem(key, '1'); } catch(e){}
              render(n + 1);
            } else {
              render(n);
            }
          });
        } catch(e){}
      };
      doc.head.appendChild(dbScript);
    };
    doc.head.appendChild(script);
  }

  /* ---------------- PWA (installable) ---------------- */
  function setUpPWA(){
    if (C.pwa !== true) return;
    if (!('serviceWorker' in navigator)) return;
    window.addEventListener('load', function(){
      var sw = [
        "'use strict';",
        "var CACHE = 'zamd-v1';",
        "self.addEventListener('install', function(e){ e.waitUntil(caches.open(CACHE).then(function(c){ return c.addAll(['" + BLOG + "']); })); self.skipWaiting(); });",
        "self.addEventListener('activate', function(e){ e.waitUntil(caches.keys().then(function(k){ return Promise.all(k.filter(function(x){ return x !== CACHE; }).map(function(x){ return caches.delete(x); })); })); self.clients.claim(); });",
        "self.addEventListener('fetch', function(e){",
        "  if (e.request.method !== 'GET') return;",
        "  e.respondWith(caches.match(e.request).then(function(hit){",
        "    var f = fetch(e.request).then(function(res){",
        "      if (res && res.status === 200 && res.type === 'basic'){ var cp = res.clone(); caches.open(CACHE).then(function(c){ c.put(e.request, cp); }); }",
        "      return res;",
        "    });",
        "    return hit || f;",
        "  }).catch(function(){ return caches.match('" + BLOG + "' + '?' + 'offline'); }));",
        "})"
      ].join('\n');
      try {
        var url = URL.createObjectURL(new Blob([sw], { type: 'text/javascript' }));
        navigator.serviceWorker.register(url).catch(function(){});
      } catch(e){}
    });
  }

  /* ---------------- footer year ---------------- */
  var yearEl = $('#copyright-year');
  if (yearEl) yearEl.textContent = String(new Date().getFullYear());
  /* Netflix's footer language control doubles as a way into search here. */
  var langBtn = $('#footer-lang');
  if (langBtn) langBtn.addEventListener('click', function(){
    window.scrollTo({ top: 0, behavior: 'smooth' });
    if (nfOpen) setNfSearch(true);
  });

  /* ---------------- continue watching (local recency only, no fake progress) ---------------- */
  function cwGet(){ try { var raw = localStorage.getItem('zamd_cw'); var arr = JSON.parse(raw || '[]'); return Array.isArray(arr) ? arr : []; } catch(e){ return []; } }
  function cwSet(list){ try { localStorage.setItem('zamd_cw', JSON.stringify((list || []).slice(0, 10))); } catch(e){} }
  function cwPush(entry){
    if (!entry || !entry.url) return;
    var list = cwGet();
    var hit = null;
    for (var i = 0; i < list.length; i++){
      if (normUrl(list[i].url) === normUrl(entry.url)){ hit = list[i]; break; }
    }
    if (hit){
      /* never clobber saved episode progress with a plain metadata refresh */
      hit.title = entry.title || hit.title;
      hit.thumb = entry.thumb || hit.thumb;
      hit.label = entry.label || hit.label;
      hit.year = entry.year || hit.year || '';
    } else {
      list.unshift({ url: entry.url, title: entry.title || '', thumb: entry.thumb || '', year: entry.year || '', label: entry.label || '', ep: 0, t: 0, pct: 0 });
    }
    cwSet(list);
  }
  function cwMatch(url){
    var list = cwGet();
    for (var i = 0; i < list.length; i++){
      if (normUrl(list[i].url) === normUrl(url)) return list[i];
    }
    return null;
  }
  /* write-back from the player: which episode, how far in, red progress */
  function cwProgress(url, info){
    var list = cwGet();
    var hit = cwMatch(url);
    if (!hit){
      var tEl = $('.detail-title');
      var cur = window.__sora_active_post || {};
      hit = { url: url, title: cleanTitle(tEl ? (tEl.textContent || '') : ''), thumb: '', label: cur.label || '' };
      list.unshift(hit);
    }
    var regP = POST_DATA[normUrl(url)];
    if (regP && regP.rec && regP.rec.thumb) hit.thumb = regP.rec.thumb;
    hit.ep = info.ep || 0;
    hit.epLabel = info.epLabel || '';
    hit.t = info.t || 0;
    hit.dur = info.dur || 0;
    hit.pct = hit.dur ? Math.min(100, Math.round((hit.t / hit.dur) * 100)) : 0;
    if (hit.pct > 95){ hit.ep = 0; hit.t = 0; hit.pct = 0; hit.epLabel = ''; }  /* finished */
    cwSet(list);
  }
  function trackCW(){
    var cur = window.__sora_active_post;
    if (!cur || !cur.url) return;
    var titleEl = $('.detail-title');
    var title = titleEl ? (titleEl.textContent || '').trim() : '';
    if (!title) return;
    /* the feed's 16:9 thumb is the right shape for a rail card; the post
       body's first image is often the portrait poster */
    var reg0 = POST_DATA[normUrl(cur.url)];
    var thumb = (reg0 && reg0.rec && reg0.rec.thumb) || '';
    if (!thumb){
      var heroImg = $('.detail-hero-media img');
      if (heroImg) thumb = heroImg.getAttribute('src') || '';
      else {
        var bimg = $('#post-body img');
        if (bimg) thumb = bimg.getAttribute('src') || '';
      }
    }
    var gEl = $('.detail-genres a, .post-labels a');
    var label = gEl ? (gEl.textContent || '').trim() : '';
    /* store the scrubbed title, not the raw one: the history row and the
       "Because You Watched" heading both read straight back out of storage */
    cwPush({ url: cur.url, title: cleanTitle(title), thumb: thumb, label: label });
  }
  function renderCW(){
    var rail = $('#cw-rail'), zone = $('#cw-zone');
    if (!rail || !zone) return;
    var list = cwGet().filter(function(x){ return x && x.url && (x.title || '').trim(); });
    if (!list.length){ zone.style.display = 'none'; return; }
    zone.style.display = '';
    rail.innerHTML = '';
    list.forEach(function(e){
      /* clean again on the way out, so titles saved before the scrubber existed
         are corrected without needing the reader to clear their history */
      var ttl = cleanTitle(e.title);
      var box = doc.createElement('article');
      box.className = 'poster-card rail-card-landscape cw-card';
      /* a history entry saved before the post had artwork used to render an
         empty box; fall back to the same neutral plate the other rows use */
      /* the More Info trigger is server-rendered on the other rails, so the
         client-built history row had none and the card looked inconsistent */
      var pct = e.pct || 0;
      box.innerHTML = '<a class="poster-media" href="'+esc(e.url)+'" aria-label="'+esc(ttl)+'">'
        + '<img src="'+esc(e.thumb || ZD_NOIMG)+'" alt="" loading="lazy">'
        + '<span class="poster-hover"><span class="play-ic"><i class="fa fa-play"></i></span></span>'
        + (pct ? '<span class="cw-bar"><i style="width:'+pct+'%"></i></span>' : '')
        + '</a>'
        + '<button class="zd-preview-trigger poster-more" type="button"'
        + ' data-url="'+esc(e.url)+'"'
        + ' data-title="'+esc(e.raw || e.title || '')+'"'
        + ' data-year="'+esc(e.year || '')+'"'
        + ' data-label="'+esc(e.label || '')+'"'
        + ' data-thumb="'+esc(e.thumb || '')+'"'
        + ' aria-label="More info about '+esc(ttl)+'"><i class="fa fa-plus"></i></button>'
        + '<h3 class="poster-title"><a href="'+esc(e.url)+'">'+esc(ttl)+'</a></h3>'
        + (e.epLabel ? '<span class="cw-ep">'+esc(e.epLabel)+'</span>' : (e.year ? '<div class="poster-sub">'+esc(e.year)+'</div>' : ''));
      rail.appendChild(box);
    });
    /* the history row is a Netflix row like the rest, so it gets the same
       trailing filler blanks instead of stopping short of the right edge */
    padRail(rail);
    bindPreviewTriggers(rail);
  }

  /* ---------------- personal rows: "Because You Watched" / "Today's Top Picks" -------
     Both react to local watch history, and both disappear entirely when the visitor
     has not watched anything yet — a Netflix row is never shown empty. */
  function dropRow(el){ if (el && el.parentNode) el.parentNode.removeChild(el); }
  function buildPersonalRows(){
    var because = $('#zd-rail-because');
    var today = $('#zd-rail-today');
    if (!body.classList.contains('view-home')){ dropRow(because); dropRow(today); return; }
    if (!because && !today) return;
    var list = cwGet().filter(function(x){ return x && x.url && (x.title || '').trim(); });
    var seed = list[0] || null;

    if (because && seed){
      var spec = seed.label
        ? { source: 'label', label: seed.label, sort: 'newest', count: 12, card: 'landscape' }
        : { source: 'recent', sort: 'newest', count: 12, card: 'landscape' };
      contentQuery(spec, function(records){
        var picked = records.filter(function(r){ return r.url !== seed.url; }).slice(0, RAIL_FETCH);
        if (picked.length){
          renderRail(because, { heading: 'Because You Watched ' + cleanTitle(seed.title), card: 'landscape', source: 'recent' }, picked, 1);
        } else {
          dropRow(because);
        }
      });
    } else if (because){
      dropRow(because);
    }

    if (today && seed){
      var seen = {};
      list.forEach(function(x){ seen[x.url] = 1; });
      contentQuery({ source: 'recent', sort: 'newest', count: RAIL_FETCH, card: 'landscape' }, function(records){
        var picked = records.filter(function(r){ return !seen[r.url]; }).slice(0, RAIL_FETCH);
        if (picked.length >= 4){
          renderRail(today, { heading: 'Today\u2019s Top Picks for You', card: 'landscape', source: 'recent' }, picked, 1);
        } else {
          dropRow(today);
        }
      });
    } else if (today){
      dropRow(today);
    }
  }

  /* hide broken hero backdrops instead of showing torn images */
  function fixHeroMedia(){
    doc.addEventListener('error', function(e){
      var t = e && e.target;
      if (t && t.tagName === 'IMG' && t.className && t.className.indexOf && t.className.indexOf('hero-img') > -1){
        var m = t.closest ? t.closest('.hero-media, .detail-hero-media') : null;
        if (m) m.style.display = 'none';
      }
    }, true);
  }
  /* hero copy must never wait on artwork: paint the text on the neutral
     gradient, then cross-fade the image in once it has decoded. */
  function heroArt(){
    $$('.hero').forEach(function(hero){
      var img = hero.querySelector('.hero-img');
      var media = hero.querySelector('.hero-media');
      if (!media) return;
      var ready = function(){
        media.classList.add('is-ready');
        hero.classList.add('has-art');
      };
      if (!img || !img.getAttribute('src')) return;
      if (img.complete && img.naturalWidth) ready();
      else img.addEventListener('load', ready, { once: true });
    });
  }

  /* strip video shortcodes from server-rendered snippets (synopsis/meta/cards) */
  function cleanSnippets(){
    var g = function(t){ return stripShortcodes(t).replace(/\s+/g, ' ').trim(); };
    $$('.detail-synopsis, .hero-synopsis').forEach(function(el){ el.textContent = g(el.textContent); });
    /* release metadata must never survive in a visible title, including the ones
       Blogger rendered server-side. Only the text node is rewritten so anchors,
       the series list and the preview card keep working. */
    $$('.poster-title, .rail-title, .zamd-ep-item-title, .detail-title, .hero-title, .nf-item .nf-title, .index-title, .catalog-title').forEach(function(el){
      var a = el.querySelector('a') || el;
      var txt = (a.textContent || '').trim();
      if (!txt) return;
      var clean = cleanTitle(txt);
      if (clean && clean !== txt){
        if (a.firstChild && a.firstChild.nodeType === 3) a.firstChild.nodeValue = clean;
        else a.textContent = clean;
      }
    });
    /* document title + social cards, so shares/search results are clean too */
    try {
      var dt = cleanTitle(doc.title);
      if (dt && dt !== doc.title) doc.title = dt;
    } catch(e){}
    $$('meta[property="og:title"], meta[name="twitter:title"], meta[itemprop="name"]').forEach(function(m){
      var v = m.getAttribute('content');
      var cv = v && cleanTitle(v);
      if (cv && cv !== v) m.setAttribute('content', cv);
    });
    /* JSON-LD Movie name */
    $$('script[type="application/ld+json"]').forEach(function(s){
      var txt = s.textContent || '';
      if (!txt || txt.indexOf('"name"') < 0) return;
      try {
        var obj = JSON.parse(txt);
        if (obj && obj.name){
          var cn = cleanTitle(obj.name);
          if (cn && cn !== obj.name){ obj.name = cn; s.textContent = JSON.stringify(obj); }
        }
      } catch(e){}
    });
    var md = $('meta[name="description"]');
    if (md){
      var mc = md.getAttribute('content') || '';
      var c2 = g(mc);
      if (c2 !== mc) md.setAttribute('content', c2);
    }
  }
  /* Last line of defence: sweep every text node on the page for a shortcode
     fragment. Blogger truncates snippets mid-tag and authors paste malformed
     blocks, so a grammar must never be readable no matter its shape. */
  function sweepShortcodes(){
    var walker = doc.createTreeWalker(doc.body, 4, null);
    var t;
    while ((t = walker.nextNode())){
      var p = t.parentNode;
      if (!p) continue;
      if (p.tagName === 'SCRIPT' || p.tagName === 'STYLE' || p.tagName === 'TEXTAREA') continue;
      var text = t.nodeValue;
      if (!text) continue;
      if (text.indexOf('[') < 0 || !new RegExp('\\[(?:' + SC_TAGS + ')\\b', 'i').test(text)) continue;
      var clean = stripShortcodes(text).replace(/\s{2,}/g, ' ');
      if (clean !== text) t.nodeValue = clean;
    }
  }
  /* [trailer] is billboard/chrome only: remove it from the rendered post body so
     it never appears as text, and never gets promoted into the main player. */
  function stripTrailer(){
    var body = $('#post-body') || $('.post-body');
    if (!body) return;
    var walker = doc.createTreeWalker(body, 4, null);
    var t, hit = false;
    while ((t = walker.nextNode())){
      var p = t.parentNode;
      if (!p || p.tagName === 'A' || p.tagName === 'SCRIPT' || p.tagName === 'STYLE') continue;
      var text = t.nodeValue || '';
      if (!text) continue;
      var m = TRAILER_SC.exec(text);
      if (!m) continue;
      cutFromText(t, m.index, m.index + m[0].length);
      hit = true;
    }
    if (hit) pruneEmpty(body, body);
  }

/* ---------------- catalog pages show everything ----------------
   "View all" and search result pages are Netflix grids, not paginated lists:
   the pager disappears and every matching title is fetched (150 per request,
   up to 600) and painted into the same grid. Blogger still serves its first
   page server-side, so nothing is blank while the fetch runs. */
  function fetchAll(spec, cb){
    var out = [], seen = {}, total = 0, start = 1, pages = 0;
    function step(){
      /* total is unknown until the first response lands, so the window check
         only applies from the second page on */
      if (out.length >= 600 || pages >= 4){ cb(out); return; }
      if (pages && start > total){ cb(out); return; }
      var url = BLOG + 'feeds/posts/default?alt=json-in-script&max-results=150&start-index=' + start;
      if (spec.label) url += '&q=' + encodeURIComponent('label:' + spec.label);
      if (spec.q) url += '&q=' + encodeURIComponent(spec.q);
      pages++;
      feed(url, function(json){
        var fd = (json && json.feed) || {};
        total = usize(fd.openSearch$totalResults && fd.openSearch$totalResults.$t) || 0;
        var es = ((fd.entry) || []).filter(function(e){ return isPostUrl(flink(e)); });
        es.forEach(function(e){
          var r = record(e);
          if (r.url && !seen[r.url]){ seen[r.url] = 1; out.push(r); }
        });
        if (!es.length){ cb(out); return; }
        start += 150;
        step();
      });
    }
    step();
  }
  function catalogAll(){
    var grid = $('.catalog .poster-grid');
    if (!grid || body.classList.contains('view-home') || body.classList.contains('view-single')) return;
    var qm = (location.search || '').match(/[?&]q=([^&]*)/);
    var lm = (location.pathname || '').match(/\/search\/label\/([^/]+)/);
    var browseAll = false;
    if (!qm && !lm){
      /* /search with no query is the browse-all page: every title, one grid */
      if (!/\/search\/?$/.test(location.pathname || '')) return;   /* archives keep their window */
      browseAll = true;
    }
    var pager = $('#blog-pager');
    if (pager) pager.style.display = 'none';
    var original = grid.innerHTML;
    var spec = lm ? { label: decodeURIComponent(lm[1]) }
      : (qm ? { q: decodeURIComponent(qm[1].replace(/\+/g, ' ')) } : {});
    fetchAll(spec, function(records){
      if (!records.length || !grid.parentNode) return;   /* keep the server page */
      var frag = doc.createDocumentFragment();
      records.forEach(function(r){ frag.appendChild(card(r, 'poster')); });
      grid.innerHTML = '';
      grid.appendChild(frag);
      bindPreviewTriggers();
      dropStaticPages();
      /* the head line should tell the truth about the full count */
      var head = $('.catalog-desc');
      if (head && records.length){
        var span = head.querySelector('.zd-count');
        if (!span){ span = doc.createElement('span'); span.className = 'zd-count'; head.appendChild(span); }
        span.textContent = records.length + (records.length === 1 ? ' title' : ' titles');
      }
    });
  }
  /* ---------------- mobile bottom tab bar ----------------
     The Netflix app navigates from a floating bar: Home, Search, My List.
     Search opens the same live search the header uses; My List opens the
     bookmarks panel. */
  function bindTabbar(){
    var tabHome = $('#zd-tab-home');
    var tabSearch = $('#zd-tab-search');
    var tabList = $('#zd-tab-list');
    if (tabHome && body.classList.contains('view-home')) tabHome.classList.add('is-active');
    if (tabSearch){
      if (/\/search\b/.test(location.pathname)) tabSearch.classList.add('is-active');
      tabSearch.addEventListener('click', function(){
        if (nfOpen) setNfSearch(true);
      });
    }
    if (tabList) tabList.addEventListener('click', function(){
      openBmPanel();
    });
  }

/* ---------------- init ----------------
   Guarded: a thrown error in one module is logged and skipped, never allowed
   to take the back button, the player or the search down with it. */
  [
    applyMode, buildNavs, fixGenreLinks, bindSearch, bindBm, updateBmUI,
    loadRelated, loadRails, initRails, padAllRails, bindPreviewTriggers,
    bindLightbox, bindPager, buildPlayer, hideReservedImages, stripTrailer,
    dropStaticPages, cleanSnippets, sweepShortcodes, resolveNextPost,
    trackCW, renderCW, buildPersonalRows, fixHeroMedia, heroArt,
    loadHeroTrailer, initHoverPreview, genreChips, activeNav, catalogAll,
    searchOverride, setUpCookie, setUpViews, setUpPWA, postBackButton,
    navigationGateArm, respectCommentSettings, bindTabbar
  ].forEach(function (f){
    try { f(); } catch (e) { if (window.console && console.warn) console.warn('zamd init:', e); }
  });
  onScroll();
  /* window resizes change how many cards fit, so the filler blanks are redrawn */
  var padTimer = null;
  window.addEventListener('resize', function(){
    if (padTimer) clearTimeout(padTimer);
    padTimer = setTimeout(function(){ padTimer = null; padAllRails(); }, 200);
  }, { passive: true });
  })();
